(window.GIM_TS=window.GIM_TS||{})["Pesachim.9"]={"from":216,"a":[["\u0003מצוה באפי נפשה הוא\u0004 \u0005[בפני עצמה היא],\u0006 ומתוך כך אין זה נוגע לענין זוגות. ומעתה באים לדון בענין הדברים שנאסרו לעשותם בזוגות.","שנינו: \u0003\"לא יעשה צרכיו תרי\"\u0004 ושואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 יש לחשוש כאן? הלא \u0003נמלך הוא!\u0004 שאין אדם עושה זאת פעמיים בכוונה תחילה אלא נמלך לאחר מעשה וכיון שכך אינו מצטרף לזוגות! \u0003אמר אביי הכי קאמר\u0004 \u0005[כך אמר]\u0006 כך יש להבין: \u0003לא יאכל תרי\u0004 \u0005[שתים]\u0006 \u0003וישתה תרי\u0004 \u0005[שתים]\u0006 \u0003ולא יעשה צרכיו\u0004 מיד לאחר מכן \u0003אפילו פעם אחת דילמא חליש ומיתרע\u0004 \u0005[שמא יחלש\u0006 בתוך כדי מעשה \u0005וירע\u0006 מזלו\u0005]\u0006 כיון שקודם לכן סעד בזוגות.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא אחרת: אם \u0003שותה\u0004 אדם \u0003כפלים\u0004 (בזוגות) — \u0003דמו בראשו. אמר רב יהודה: אימתי — בזמן שלא ראה פני השוק\u0004 שלא יצא מחוץ לבית בין כוס לכוס, \u0003אבל ראה פני השוק\u0004 לאחר ששתה כוס ראשונה — \u0003הרשות בידו.\u0004 וכעין זה \u0003אמר רב אשי: חזינא ליה\u0004 \u0005[ראיתי אותו]\u0006 את \u0003רב חנניא בר ביבי, דאכל כסא הוה נפיק וחזי אפי שוקא\u0004 \u0005[שעל כל כוס\u0006 שהיה שותה \u0005היה יוצא ורואה את פני השוק].\u0006","\u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 שיש חשש בשתיית זוגות \u0003אלא\u0004 כשהוא מתכוון \u0003לצאת לדרך\u0004 לאחר השתייה, \u0003אבל\u0004 אם נשאר \u0003בביתו — לא. אמר ר' זירא: ולישן כלצאת לדרך דמי\u0004 \u0005[נחשב],\u0006 ויש חשש סכנה שמא יחלה. \u0003אמר רב פפא: ולצאת לבית הכסא — כלצאת לדרך דמי\u0004 \u0005[נחשב].\u0006 ושואלים: וכי \u0003בביתו לא,\u0004 אין חוששים לזוגות? \u0003והא רבא מני כשורי\u0004 \u0005[\u0006היה \u0005מונה את הקורות]\u0006 קורה כנגד כל כוס ששותה, כדי שלא ישכח וישתה זוגות.","\u0003ואביי כי שתי חד כסא מנקיט ליה אימיה תרי כסי בתרי ידיה\u0004 \u0005[כאשר היה שותה כוס אחת\u0006 מיד \u0005היתה נותנת לו אמו שתי כוסות בשתי ידיו]\u0006 כדי שלא ישכח וישתה רק אחת ונמצא שותה זוגות. וכן \u0003רב נחמן בר יצחק, כי הוה שתי תרי כסי\u0004 \u0005[כאשר היה שותה שתי כוסות]\u0006 \u0003מנקיט ליה שמעיה חד כסא\u0004 \u0005[היה נותן לו שמשו\u0006 מיד \u0005כוס אחת\u0006 נוספת\u0005],\u0006 וכאשר היה שותה \u0003חד כסא\u0004 \u0005[כוס אחת],\u0006 \u0003מנקיט ליה תרי כסי בתרי ידיה\u0004 \u0005[נותן לו\u0006 שמשו מיד \u0005שתי כוסות בשתי ידיו]\u0006 הרי שאף בבית חוששים לזוגות! ומשיבים: \u0003אדם חשוב שאני\u0004 \u0005[שונה],\u0006 שהמזיקים נטפלים אליו וצריך להזהר בעצמו יותר.","\u0003אמר עולא:\u0004 השותה \u0003עשרה כוסות אין בהם משום\u0004 חשש \u0003זוגות.\u0004 ומסבירים כי \u0003עולא לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005].\u0006 ש\u0003אמר עולא, ואמרי לה במתניתא תנא\u0004 \u0005[ויש אומרים שבברייתא\u0006 היא \u0005שנויה]:\u0006 \u0003עשרה כוסות תיקנו חכמים\u0004 לשתות \u0003בבית האבל\u0004 בשעת סעודת ההבראה, \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר ש\u0003עשרה כוסות יש בהן משום זוגות —\u0004 אם כן \u0003היכי קיימי רבנן ותקנו מילתא דאתי לידי סכנה\u0004 \u0005[איך עומדים חכמים ומתקנים דבר שיכול לבוא בו לידי סכנה]?\u0006 \u0003אבל תמניא\u0004 \u0005[שמונה]\u0006 אכן \u0003יש בהן משום\u0004 חשש \u0003זוגות.\u0004","\u0003רב חסדא ורבה בר רב הונא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 שגם בשמונה אין לחשוש כי \u0003\"שלום\", לטובה — מצטרף, לרעה — לא מצטרף.\u0004 שהמספר שמונה הוא לאחר המספר שבע, שהוא מספר המילים שבפסוק האחרון של ברכת כהנים \"ישא ה' פניו אליך וישם לך שלום\" (במדבר ו, כו) והמילה \"שלום\" השביעית בו אפשר לומר שתצטרף לטובה אבל לא לרעה. \u0003אבל שיתא\u0004 \u0005[שש]\u0006 אכן \u0003יש בהן משום\u0004 חשש \u0003זוגות.\u0004","\u0003רבה ורב יוסף דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 שגם המספר שש שהוא בא לאחר המילה החמישית בפסוק השני של ברכת כהנים \u0003\"\u0004יאר ה' פניו אליך \u0003ויחנך\"\u0004 (במדבר ו, כה), \u0003לטובה — מצטרף לרעה — לא מצטרף. אבל ארבעה יש בהן משום\u0004 חשש \u0003זוגות.\u0004","\u0003אביי ורבא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 אף בארבע אין משום זוגות, משום שהמילה השלישית שבפסוק הראשון של ברכת כהנים \u0003\"\u0004יברכך ה' \u0003וישמרך\"\u0004 (במדבר ו, כד), \u0003לטובה — מצטרף לרעה — לא מצטרף.\u0004","\u0003ואזדא\u0004 \u0005[והלך]\u0006 \u0003רבא\u0004 בענין זה \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003רבא אפקינהו לרבנן\u0004 \u0005[הוציא את החכמים]\u0006 שהיו לומדים לפניו אחרי ששתו אצלו לפעמים \u0003ארבעה כוסות\u0004 ולא חשש, \u0003אף על גב דאיתזק\u0004 \u0005[אף על פי שניזק]\u0006 אחר כך \u0003רבא בר ליואי לא חש לה למילתא\u0004 \u0005[חשש\u0006 רבא \u0005לדבר]\u0006 שמא זוגות הם שגרמו לכך, ש\u0003אמר: ההוא\u0004 \u0005[אותו]\u0006 נזק שקרה לו הוא \u0003משום דאותבן בפירקא הוה\u0004 \u0005[שהקשה לי בשעת הדרשה\u0006 לרבים \u0005היה],\u0006 שאין ראוי לתלמיד להקשות על רבו כשהוא דורש ברבים, שמא לא יוכל להשיב ונמצא מביישו.","\u0003אמר רב יוסף: אמר לי יוסף שידא\u0004 \u0005[השד]\u0006 \u0003אשמדאי מלכא דשידי\u0004 \u0005[מלך השדים]\u0006 \u0003ממונה הוא אכולהו זוגי\u0004 \u0005[על כל\u0006 העושים \u0005זוגות]\u0006 \u0003ומלכא לא איקרי מזיק\u0004 \u0005[והמלך אינו נקרא מזיק]\u0006 ואין לחשוש לנזק מן השדים על ידי זוגות. \u0003איכא דאמרי לה להאי גיסא\u0004 \u0005[יש אומרים\u0006 את הדבר \u0005הזה לצד זה]:\u0006 \u0003אדרבה, מלכא רתחנא הוא, מאי דבעי עביד\u0004 \u0005[מלך כעסן הוא ומה שרוצה עושה],\u0006 שהרי הלכה היא \u0003שהמלך פורץ גדר\u0004 של יחיד \u0003לעשות לו דרך ואין מוחין בידו\u0004 אם מזיק לאחרים, וכך ניתנה רשות למלך השדים להזיק.","\u0003אמר רב פפא: אמר לי יוסף שידא\u0004 \u0005[השד],\u0006 \u0003בתרי קטלינן\u0004 \u0005[בשנים אנו ממיתים]\u0006 שאם שתה אדם שני כוסות הורגים אנו אותו, \u0003בארבעה לא קטלינן, בארבעה מזקינן\u0004 \u0005[בארבעה אין אנו הורגים, בארבעה מזיקים אנו].\u0006 והבדל נוסף: \u0003בתרי\u0004 \u0005[בשתים]\u0006 \u0003בין\u0004 ששתה \u0003בשוגג בין במזיד\u0004 מזיקים אנו לו, \u0003בארבעה במזיד — אין\u0004 \u0005[כן]\u0006 הריהו ניזוק על ידינו, \u0003בשוגג — לא.\u0004","ושואלים: \u0003ואי אישתלי ואיקרי ונפק מאי תקנתיה\u0004 \u0005[ואם שכח והזדמן ויצא\u0006 החוצה לאחר ששתה זוגות \u0005מה תקנתו]?\u0006 משיבים: \u0003לינקוט זקפא דידיה דימיניה בידא דשמאליה וזקפא דשמאליה בידא דימיניה\u0004 \u0005[שיטול את בוהן ידו הימנית בידו השמאלית ואת בוהן ידו השמאלית בידו הימנית]\u0006 \u0003ונימא הכי\u0004 \u0005[ויאמר כך]:\u0006 \u0003\"אתון ואנא — הא תלתא\u0004 \u0005[אתם\u0006 הבהונות \u0005ואני —\u0006 \u0005הרי\u0006 אנו \u0005שלושה]\u0006 \u0003\",\u0004 ואין כאן אם כן זוגות. \u0003ואי שמיע ליה דאמר אתון ואנא הא ארבעה\u0004 \u0005[ואם הוא שומע\u0006 קול \u0005שאומר: אתם ואני הרי\u0006 אנו \u0005ארבעה]\u0006 ויש כאן שוב זוגות, \u0003נימא ליה\u0004 \u0005[יאמר לו]:\u0006 \u0003\"אתון ואנא הא חמשה\u0004 \u0005[אתם ואני הרי\u0006 אנו \u0005חמישה]\u0006 \u0003\". ואי שמיע ליה\u0004 \u0005[ואם ישמע ]\u0006 אותו קול ש\u0003אמר: \"אתון ואנא הא שיתא\u0004 \u0005[אתם ואני הרי\u0006 אנו \u0005ששה]\u0006 \u0003\", נימא ליה\u0004 \u0005[יאמר לו]:\u0006 \u0003\"אתון ואנא הא שבעה\u0004 \u0005[אתם ואני הרי שבעה]\u0006 \u0003\".\u0004 מסופר: \u0003הוה עובדא עד מאה וחד ופקע שידא\u0004 \u0005[היה מעשה\u0006 שכך מנה לו לשד \u0005עד מאה ואחד ופקע השד\u0006 מרוב כעס\u0005].\u0006","\u0003אמר אמימר: אמרה לי רישתינהי\u0004 \u0005[גבירתן]\u0006 של ה\u0003נשים\u0004 ה\u0003כשפניות: האי מאן דפגע בהו\u0004 \u0005[מי שפוגע בהן]\u0006 \u0003בנשים כשפניות, נימא הכי\u0004 \u0005[יאמר כך]\u0006 השבעה זו: \u0003\"חרי חמימי בדיקולא בזייא לפומייכו נשי דחרשייא\u0004 \u0005[צואה חמה בסלי תמרים קרועים לפיכן נשים מכשפות],\u0006 \u0003קרח קרחייכי\u0004 \u0005[ימרטו שערותיכם],\u0006 שאתן עושות בהן כישוף, \u0003פרח פרחייכי\u0004 \u0005[\u0006ישא הרוח \u0005ויפריח את הפירורים]\u0006 שאתן מכשפות בהן,"],["\u0003איבדור תבלונייכי\u0004 \u0005[התפזרו תבלינים שלכן]\u0006 המשמשים לכשפים, \u0003פרחא זיקא למוריקא חדתא דנקטיתו\u0004 \u0005[נשא הרוח את הכרכום החדש שאתן מחזיקות]\u0006 \u0003נשים כשפניות\u0004 כדי לכשף בו\u0005,\u0006 \u0003אדחנני וחננכי\u0004 \u0005[עד שחסו עלי\u0006 מן השמים \u0005וחסתן עלי]\u0006 \u0003לא אתיתי לגו\u0004 \u0005[הייתי מגיע לכאן],\u0006 \u0003השתא דאתיתי לגו קרחנני וחננכי\u0004 \u0005[כיון שהגעתי לכאן נתקררו רחמיכן עלי ותהא לכן חנינה]\u0006.","בענין זוגות אמרו, כי \u0003במערבא\u0004 \u0005[בארץ ישראל]\u0006 \u0003לא קפדי אזוגי\u0004 \u0005[היו מקפידים על זוגות]\u0006 ולא היו חוששים כלל לכך. \u0003רב דימי מנהרדעא קפיד\u0004 \u0005[היה מקפיד]\u0006 בזוגות \u0003אפילו ארושמא דחביתא\u0004 \u0005[על סימנים\u0006 שהיו מסמנים \u0005על החבית]\u0006 שלא יעשו סימנים בזוגות. מסופר: \u0003הוה עובדא ופקע חביתא\u0004 \u0005[היה מעשה ופקעה החבית]\u0006 שהיה בה סימון כזה של זוגות. ומסכמים: \u0003כללא דמילתא, כל דקפיד — קפדי בהדיה\u0004 \u0005[כללו של דבר: כל שמקפיד\u0006 על זוגות \u0005—\u0006 \u0005מקפידים\u0006 המזיקים \u0005עליו],\u0006 \u0003ודלא קפיד לא קפדי בהדיה\u0004 \u0005[ומי שאינו מקפיד אין מקפידים עליו].\u0006 ומעירים: \u0003ומיהו למיחש מיבעי\u0004 \u0005[ומכל מקום, לחשוש צריך]\u0006 שלא יסכן עצמו ולא יעשה כן לכתחילה.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר: שתי ביצים, ושתי אגוזין, שתי קישואין\u0004 ועוד \u0003דבר אחר — הלכה למשה מסיני\u0004 כלומר מסורת היא שהם מזיקים בזוגות. ואולם \u0003מסתפקא להו לרבנן מאי ניהו\u0004 \u0005[והיה מסופק להם לחכמים מהו אותו]\u0006 \u0003דבר אחר\u0004 שלא נתפרש, \u0003וגזור רבנן בכולהו זוגי\u0004 \u0005[ו\u0006לפיכך \u0005גזרו חכמים\u0006 לחשוש \u0005בכל הזוגות],\u0006 \u0003משום\u0004 אותו \u0003דבר אחר.\u0004","ומעירים: \u0003והא דאמרן\u0004 \u0005[וזה שאמרנו]\u0006 קודם \u0003עשרה, תמניא, שיתא\u0004 \u0005[שמונה, ששה],\u0006 \u0003ארבעה,\u0004 שכל אלו \u0003אין בהן משום זוגי\u0004 \u0005[זוגות]\u0006 \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 זאת \u0003אלא לענין מזיקין\u0004 שאינם מזיקים בשל זוגות אלה. \u0003אבל לענין כשפים אפילו טובא נמי חיישינן\u0004 \u0005[ביותר\u0006 ממספר זה \u0005גם כן חוששים אנו],\u0006 שמי שעשה דבר בזוגות (אף בעשרה, שמונה, ששה וארבעה) — כשפים יכולים לחול עליו.","\u0003כי הא דההוא גברא דגרשה לדביתהו אזיל אינסבה לחנואה\u0004 \u0005[כמו זה\u0006 שאירע, \u0005אדם אחד שגרש את אשתו, הלכה\u0006 היא \u0005והתחתנה עם החנוני]\u0006 שהיה מוכר בין השאר יין בחנותו, \u0003כל יומא הוה אזיל ושתי חמרא\u0004 \u0005[יום היה הולך ושותה יין]\u0006 באותו מקום \u0003הוה קא עבדא ליה\u0004 \u0005[היתה עושה לו]\u0006 \u0003כשפים, ולא קא מהניא לה ביה\u0004 \u0005[היתה מועילה לו\u0006 להזיקו\u0005]\u0006 \u0003משום דהוה מזדהר בנפשיה בזוגא\u0004 \u0005[שהיה נזהר בעצמו מזוגות].\u0006","\u0003יומא חד אשתי טובא\u0004 \u0005[יום אחד שתה הרבה]\u0006 \u0003ולא הוה ידע\u0004 \u0005[היה יודע]\u0006 \u0003כמה שתי\u0004 \u0005[\u0006הוא \u0005שותה].\u0006 \u0003עד שיתסר הוה צייל ואיזדהר בנפשיה\u0004 \u0005[שש עשרה\u0006 כוסות \u0005היתה\u0006 דעתו \u0005צלולה\u0006 והיה \u0005נזהר בעצמו],\u0006 \u0003מכאן ואילך לא הוה צייל\u0004 \u0005[היה צלול]\u0006 \u0003ולא איזדהר בנפשיה\u0004 \u0005[נזהר בעצמו],\u0006 \u0003ואפיקתיה בזוגא\u0004 \u0005[והוציאה אותו בזוגות]\u0006 גרמה שיצא לאחר ששתה מספר זוגי של כוסות. \u0003כי הוה אזיל, גס ביה ההוא טייעא\u0004 \u0005[כשהלך\u0006 ברחוב \u0005פגש בו ערבי אחד],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003גברא קטילא\u0004 \u0005[אדם הרוג]\u0006 \u0003הוא דאזיל הכא\u0004 \u0005[\u0006זה \u0005שהולך כאן],\u0006 שראה שכשפים שולטים בו. \u0003אזיל חבקיה לדיקלא\u0004 \u0005[הלך\u0006 ומרוב בהלה \u0005חבק דקל\u0006 להשען בו\u0005]\u0006 \u0003צווח דיקלא\u0004 \u0005[יבש הדקל]\u0006 מכוח הכישוף \u0003ופקע הוא.\u0004","\u0003אמר רב עוירא:\u0004 האוכל משתי \u0003קערות\u0004 או שאוכל שני \u0003ככרות\u0004 לחם \u0003אין בהם משום זוגות.\u0004 וביתר הרחבה: \u0003כללא דמילתא\u0004 \u0005[כללו של דבר]:\u0006 \u0003כל שגמרו בידי אדם\u0004 בין שהוא כלי או מאכל מתוקן \u0003אין בהן משום זוגות.\u0004 אם \u0003גמרו בידי שמים\u0004 — \u0003במילי מיני דמיכל חיישינן\u0004 \u0005[בדברים\u0006 שהם \u0005מיני מאכל חוששים אנו].\u0006","ועוד, \u0003חנות\u0004 כלומר האוכל או שותה בחנות — \u0003אין בהן משום\u0004 חשש \u0003זוגות,\u0004 שאין זו דרך קביעות. \u0003נמלך\u0004 לאחר שאכל או שתה מספר שאינו זוגי להוסיף עוד אחת אבל לא נתכוון מתחילה לזוגות — \u0003אין בהם משום זוגות. אורח\u0004 השותה, או האוכל בבית של אחר — \u0003אין בו משום זוגות,\u0004 שהרי לא הוא קובע מה ישתה אלא בעלי הבית. \u0003אשה — אין בה\u0004 (באכילתה, או בשתייתה) \u0003משום\u0004 חשש \u0003זוגות\u0004 שאין המזיקים מקפידים. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003אשה חשובה\u0004 היא — \u0003חיישינן\u0004 \u0005[חוששים אנו].\u0006","\u0003אמר רב חיננא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: איספרגוס\u0004 (משקה העשוי מיין מבוסם בתבלינים) והיו רגילים לשתותו בבוקר — \u0003מצטרף לטובה\u0004 כדי להוציא מכלל זוגות אם מספר הכוסות בלעדיו זוגי, \u0003ואין מצטרף לרעה\u0004 כשמספר הכוסות בלעדיו אינו זוגי.","\u0003אמר רבינא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: זוגי — לחומרא\u0004 \u0005[להחמיר],\u0006 כלומר, אם ספק בידו אם גמר בזוגות ישתה כוס נוספת. \u0003ואמרי ליה\u0004 \u0005[ויש אומרים]:\u0006 \u0003זוגי\u0004 \u0005[זוגות] —\u0006 \u0003לקולא\u0004 \u0005[להקל],\u0006 שלא יוסיף עוד, שמא על ידי כך ימצא שותה בזוגות. \u0003אמר רב יוסף: תרי דחמרא וחד דשיכרא\u0004 \u0005[שתי כוסות\u0006 של \u0005יין\u0006 וכוס \u0005אחת של שיכר]\u0006 — \u0003לא מצטרף, תרי דשיכרא וחד דחמרא\u0004 \u0005[שתי\u0006 כוסות של \u0005שיכר ואחת של יין]\u0006 — \u0003מצטרף.\u0004","\u0003וסימניך\u0004 לזכור את הדבר, המשנה בדיני טומאה שנאמר בה, \u0003זה הכלל: כל המחובר לו מן החמור ממנו — טמא,\u0004 ואם מחובר לו \u0003מן הקל ממנו — טהור,\u0004 שאם חיבר לדבר המקבל טומאה רק בשיעור גדול (והוא לכן \"קל\") דבר המקבל טומאה אף בשיעור קטן (שהוא \"חמור\") — הריהם יחד מצטרפים לשיעור הגדול. ואף כאן, כיון שיין חמור, כלומר חשוב מן השיכר, הריהו מצטרף לשיכר ולא להיפך.","\u0003אמר רב נחמן אמר רב: תרי קמא תכא וחד אתכא — מצטרפי\u0004 \u0005[שתי\u0006 כוסות \u0005לפני\u0006 שמביאים את \u0005השולחן\u0006 לאכול, \u0005ואחד על השולחן —\u0006 \u0005מצטרפות]\u0006 לכך שלא ייחשבו כזוגות, אבל \u0003חד מקמי תכא ותרי אתכא\u0004 \u0005[אחת לפני השולחן ושתים על השולחן] —\u0006 \u0003לא מצטרפין\u0004 \u0005[מצטרפות],\u0006 ואלו שעל השולחן נחשבות כזוגות.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב משרשיא: אטו אנן לתקוני תכא קא בעינן\u0004 \u0005[וכי אנחנו לתקן את השולחן אנחנו צריכים]?\u0006 \u0003לתקוני גברא בעינן\u0004 \u0005[לתקן את האיש אנו צריכים],\u0006 כדי שישתה, \u0003וגברא קא מיתקן וקאי\u0004 \u0005[והאדם מתוקן ועומד]\u0006 שהרי שתה שלוש כוסות.","\u0003אלא אמר רב משרשייא: דכולי עלמא תרי אתכא וחד לבתר תכא\u0004 \u0005[לדעת הכל, שתים על השולחן ואחת לאחר השולחן] —\u0006 \u0003לא מצטרפי\u0004 \u0005[מצטרפות].\u0006 \u0003כי ההיא\u0004 \u0005[כאותו]\u0006 \u0003מעשה\u0004 שהיה אצל \u0003רבה בר נחמני\u0004 ( ב\"מ פו, א ), באדם ששתה זוגות וניזק, שאמר רבה שישתה כוס שלישית אבל הורה להחזיר את השולחן ושישתה לידו, משמע שבלא זה אינן מצטרפות.","\u0003אמר רב יהודה אמר שמואל: כל\u0004 מין משקה שהוא \u0003מזוג — מצטרף\u0004 למנין,"],["\u0003חוץ מן המים\u0004 שאם מזג מים במים, אין הם נחשבים כמזוגים ואינם מצטרפים לזוגות. \u0003ור' יוחנן אמר: אפילו מים\u0004 מצטרפים למנין. \u0003אמר רב פפא: לא אמרן\u0004 \u0005[אמרנו]\u0006 דבר זה במים, \u0003אלא חמימי לגו קרירי, וקרירי לגו חמימי\u0004 \u0005[\u0006מים \u0005חמים בתוך קרים ו\u0006מים \u0005קרים בתוך חמים]\u0006 הם הנחשבים כמזוגים, \u0003אבל חמימי לגו חמימי, וקרירי לגו קרירי\u0004 \u0005[\u0006מים \u0005חמים בתוך חמים ו\u0006מים \u0005קרים בתוך קרים] —\u0006 \u0003לא\u0004 נחשבים כמזוגים לדעת הכל.","כיון שדובר בסגולות שונות ובחשש כשפים מביאים עוד דברים בנושא זה. \u0003אמר ריש לקיש: ארבעה דברים העושה אותן דמו בראשו ומתחייב בנפשו\u0004 מחמת רוח רעה השורה עליו. \u0003אלו הן: הנפנה\u0004 לצרכיו במקום ש\u0003בין דקל לכותל והעובר בין שני דקלים, והשותה מים שאולין, והעובר על מים שפוכין, ואפילו שפכתו אשתו בפניו.\u0004","ומבארים: \u0003הנפנה בין דקל לכותל — לא אמרן אלא דלית ליה\u0004 \u0005[שאין לו]\u0006 ביניהם מקום מעבר ברוחב \u0003ארבע אמות, אבל\u0004 אם \u0003אית ליה\u0004 \u0005[יש לו]\u0006 \u0003ארבע אמות לית לן בה\u0004 \u0005[אין לנו בה]\u0006 חשש, שהרי יש למזיקים די מקום לעבור בו ואין הוא פוגע במקום המעבר שלהם. וגם \u0003כי לית ליה\u0004 \u0005[כאשר אין לו]\u0006 שטח של \u0003ארבע אמות, לא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא דליכא\u0004 \u0005[שאין]\u0006 למזיקים \u0003דירכא אחרינא\u0004 \u0005[דרך אחרת]\u0006 אלא זו, \u0003אבל\u0004 אם \u0003איכא דירכא אחרינא\u0004 \u0005[יש\u0006 להם \u0005דרך אחרת]\u0006 \u0003— לית לן בה\u0004 \u0005[אין לנו בה]\u0006 כל חשש.","\u0003והעובר בין שני דקלים לא אמרן\u0004 \u0005[אמרנו]\u0006 חשש זה \u0003אלא דלא פסקינהו\u0004 \u0005[שלא פסקתם,\u0006 עברה ביניהם\u0005]\u0006 \u0003רשות הרבים. אבל\u0004 אם \u0003פסקינהו\u0004 \u0005[פסקתם,\u0006 עברה ביניהם\u0005]\u0006 \u0003רשות הרבים — לית לן בה\u0004 \u0005[אין לנו בה]\u0006 חשש, שהרי במקום שיש רבים אינם רשאים להזיק כלל. ו\u0003השותה מים שאולין לא אמרן\u0004 \u0005[לא אמרנו]\u0006 ששורה עליהם רוח רעה \u0003אלא דשיילינהו\u0004 \u0005[ששאל אותם]\u0006 \u0003קטן, אבל\u0004 אם שאל אותם \u0003גדול — לית לן בה\u0004 \u0005[אין לנו בה]\u0006 חשש.","\u0003ואפילו שיילינהו\u0004 \u0005[שאל אותם]\u0006 \u0003קטן, נמי לא אמרן\u0004 \u0005[גם כן לא אמרנו]\u0006 \u0003אלא\u0004 כששואל אותם \u0003בשדה,\u0004 ש\u0003לא שכיחי\u0004 [\u0005מצויים]\u0006 מים, \u0003אבל בעיר דשכיחי\u0004 \u0005[ש\u0006המים \u0005מצויים]\u0006 \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 חשש. \u0003ואפילו בשדה נמי לא אמרן\u0004 \u0005[גם כן לא אמרנו]\u0006 \u0003אלא מיא\u0004 \u0005[\u0006ששאל \u0005מים],\u0006 \u0003אבל חמרא ושיכרא\u0004 \u0005[יין ושיכר] —\u0006 \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 חשש.","\u0003והעובר על מים שפוכין — לא אמרן\u0004 \u0005[אמרנו]\u0006 חשש בזה, \u0003אלא\u0004 ש\u0003לא אפסקינהו בעפרא\u0004 \u0005[פסקן,\u0006 פיזר עליהן, \u0005בעפר]\u0006 \u0003ולא תף בהו רוקא\u0004 \u0005[ירק בהם רוק]\u0006 \u0003אבל אפסקינהו בעפרא\u0004 \u0005[הפסיק אותם בעפר]\u0006 \u0003או תף בהו רוקא\u0004 \u0005[ירק בהם רוק] —\u0006 \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 חשש. \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 חשש זה \u0003אלא\u0004 כש\u0003לא עבר עלייהו שימשא\u0004 \u0005[עליהם השמש]\u0006 כלומר בלילה, \u0003ולא עבר עלייהו שיתין ניגרי\u0004 \u0005[עליהן שישים פסיעות]\u0006 של אנשים שעברו במקום, \u0003אבל\u0004 אם \u0003עבר עלייהו שימשא ועבר עלייהו שיתין ניגרי\u0004 \u0005[עליהם השמש ועברו עליהם שישים פסיעות]\u0006 — \u0003לית לן בה\u0004 \u0005[אין לנו בכך]\u0006 חשש. \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 חשש זה \u0003אלא\u0004 כש\u0003לא רכיב חמרא\u0004 \u0005[רוכב על החמור]\u0006 \u0003ולא סיים מסני\u0004 \u0005[נועל מנעלים]\u0006 \u0003אבל רכיב חמרא וסיים מסני — לית לן בה\u0004 \u0005[רוכב על חמור או נועל מנעלים אין לנו בה]\u0006 חשש.","ומעירים: \u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 שאמרנו שמבטלים את החשש הם דווקא \u0003היכא דליכא למיחש\u0004 \u0005[מקום שאין לחשוש\u0006 בו\u0005]\u0006 \u0003לכשפים\u0004 שמישהו מעונין לעשות לו מתוך כוונה תחילה, \u0003אבל היכא דאיכא למיחש\u0004 \u0005[במקום שיש לחשוש]\u0006 \u0003לכשפים, אף על גב דאיכא כל הני — חיישינן\u0004 \u0005[אף על פי שיש\u0006 את \u0005כל אלה חוששים אנו].\u0006 כ\u0003ההוא גברא דרכיב חמרא וסיים מסני, וגמוד מסאניה וצוו כרעיה\u0004 \u0005[כמו\u0006 המעשה \u0005באדם אחד שרכב על חמור והיה נעול מנעלים\u0006 ועבר על אותם המים \u0005ונתכווצו המנעלים ויבשו רגליו].\u0006","ועוד בענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שלשה אין ממצעין\u0004 שמקפידים שלא ימצאו בין שני אנשים ההולכים בדרך ואף \u0003לא מתמצעין\u0004 שאין הולכים בין שנים מהם. \u0003ואלו הן: הכלב והדקל והאשה. ויש אומרים: אף החזיר, ויש אומרים: אף הנחש,\u0004 שכל אלה קשים לכשפים.","ושואלים: \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003ממצעין מאי תקנתיה\u0004 \u0005[מה תקנתו]\u0006 כדי שלא ינזק? \u0003אמר רב פפא: נפתח\u0004 \u0005[שיפתח]\u0006 בפסוק המתחיל במילה \u0003\"אל\" ונפסיק\u0004 \u0005[ויגמור]\u0006 בפסוק המסיים במילה \u0003\"אל\"\u0004 — \"אל מוציאם ממצרים... כי לא נחש ביעקב ולא קסם בישראל כעת יאמר ליעקב וישראל מה פעל אל\" (במדבר כג, כב — כג), שיש בתוכנו משום ביטול הכשפים,","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003נפתח\u0004 \u0005[שיפתח]\u0006 בפסוק המתחיל במילה \u0003\"לא\" ונפסיק\u0004 \u0005[ויגמור]\u0006 באותו פסוק המסתיים במילה \u0003\"לא\"\u0004 — \"לא איש אל ויכזב ובן אדם ויתנחם ההוא אמר ולא יעשה ודבר ולא יקימנה\" (במדבר כג, יט).","וכן, \u0003הני בי תרי דמצעא להו אשה נדה\u0004 \u0005[אותם שנים שממוצעת,\u0006 עוברת, ביניהם \u0005אשה נדה],\u0006 \u0003אם\u0004 ב\u0003תחלת נדתה היא — הורגת,\u0004 כלומר, גורמת שייהרג \u0003אחד מהן, אם\u0004 ב\u0003סוף נדתה היא\u0004 אינה הורגת, אבל \u0003מריבה עושה ביניהן. מאי תקנתיה? נפתח ב\"אל\" ונפסיק ב\"אל\"\u0004 כאמור.","ועוד: \u0003הני תרי נשי דיתבן בפרשת דרכים, חדא בהאי גיסא דשבילא וחדא באידך גיסא, ומכוונן אפייהו להדדי — ודאי בכשפים עסיקן\u0004 \u0005[אותן שתי נשים היושבות בפרשת דרכים, אחת בצד זה של השביל ואחת בצד זה ומכוונות פניהן זו לזו ודאי בכשפים הן עוסקות].\u0006 \u0003מאי תקנתיה\u0004 \u0005[מה תקנתו]\u0006 של עובר הדרך? \u0003אי איכא דירכא אחרינא\u0004 \u0005[אם יש דרך אחרת] —\u0006 \u0003ליזיל בה\u0004 \u0005[שילך בה].\u0006 \u0003ואי ליכא דירכא אחרינא\u0004 \u0005[ואם אין דרך אחרת],\u0006 \u0003אי איכא איניש אחרינא בהדיה\u0004 \u0005[אם יש אדם אחר עמו]\u0006 \u0003— נינקטו לידייהו בהדי הדדי וניחלפו\u0004 \u0005[שיחזיקו לידיהם ביחד ויחלפו]\u0006 זה עם זה. \u0003ואי ליכא איניש אחרינא\u0004 \u0005[ואם אין אדם אחר]\u0006 \u0003נימא הכי\u0004 \u0005[שיאמר כך]:\u0006 \u0003\"אגרת אזלת אסיא בלוסיא,\u0004 שהם שמות שדים שעוסקות עימם נשים, \u0003מתקטלא בחיק קבל\u0004 \u0005[נהרגים על ידי החיצים]\u0006\u0003\".\u0004","ועוד נאמר בענין זה: \u0003האי מאן דפגע באיתתא בעידנא דסלקא\u0004 \u0005[מי שפוגש אשה בזמן שהיא עולה]\u0006 \u0003מטבילת מצוה\u0004 שטובלת לאחר זמן נדתה, \u0003אי איהו קדים ומשמש — אחדא ליה לדידיה רוח זנונים\u0004 \u0005[אם הוא מקדים ומשמש\u0006 מטתו עם אשה \u0005אוחזת אותו רוח זנונים],\u0006 \u0003אי איהי קדמה ומשמשה — אחדא לה לדידה רוח זנונים\u0004 \u0005[אם היא מקדימה ומשמשת\u0006 מטתה \u0005אוחזת אותה רוח זנונים].\u0006 \u0003מאי תקנתיה\u0004 \u0005[מה תהא תקנתו]?\u0006 \u0003לימא הכי\u0004 \u0005[שיאמר כך]:\u0006 \u0003\"שפך בוז על נדיבים ויתעם בתהו לא דרך\"\u0004 (תהילים קז, מ).","\u0003אמר רב יצחק מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"גם כי אלך בגיא צלמות לא אירא רע כי אתה עמדי\"\u0004 (תהילים כג, ד), כוונתו: \u0003זה הישן בצל דקל יחידי\u0004 שאין דקל אחר סמוך לו, \u0003ובצל לבנה,\u0004 שאף שהוא נמצא במצב מסוכן בכל זאת כיון שבוטח בה' איננו חושש. ומסייגים: \u0003ובצל דקל יחידי, לא אמרן אלא דלא נפיל טולא דחבריה עילויה\u0004 \u0005[אין אנו אומרים\u0006 זאת \u0005אלא כשלא נפל צל\u0006 דקל \u0005חבירו עליו]\u0006 \u0003אבל נפל טולא דחבריה עילויה\u0004 \u0005[אבל נפל צל\u0006 דקל \u0005חבירו עליו] —\u0006 \u0003לית לן בה\u0004 \u0005[אין לנו בה]\u0006 חשש.","ושואלים: \u0003אלא הא דתניא\u0004 \u0005[זה ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003הישן בצל דקל יחידי בחצר, והישן בצל לבנה דמו בראשו היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005הדבר]?\u0006 \u0003אי לימא דלא נפל טולא דחבריה עילויה —\u0004 \u0005[אם תאמר שלא נפל צל חברו עליו],\u0006 אם כן \u0003אפילו בשדה נמי\u0004 \u0005[אפילו בשדה גם כן]\u0006 ניזוק? \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]:\u0006 ש\u0003בחצר — אף על גב דנפיל טולא דחבריה עילויה\u0004 \u0005[אף על פי שנפל צל חברו עליו]\u0006 מסוכן הוא?! ומסכמים: \u0003שמע מינה\u0004 \u0005[\u0006אכן אפשר \u0005ללמוד מכאן]\u0006 שכן הוא.","\u0003ובצילה של לבנה — לא אמרן\u0004 שהדבר מסוכן \u0003אלא\u0004 בתחילת החודש שאז הלבנה זורחת במזרח ולכך צילה \u0003במערבה\u0004 \u0005[במערב],\u0006 \u0003אבל\u0004 בסוף החודש כשהלבנה זורחת במערב ולכך צילה \u0003במדינחא\u0004 \u0005[למזרח]\u0006 \u0003— לית לן בה\u0004 \u0005[אין לנו בכך]\u0006 חשש."],["עוד נאמר בענין חשש היזק: \u0003האי מאן דמפני אגירדא דדיקלא\u0004 \u0005[מי שנפנה\u0006 לצרכיו \u0005על גדם של דקל] —\u0006 \u0003אחדא ליה לדידיה רוח פלגא\u0004 \u0005[אוחזת אותו רוח מחלה].\u0006 \u0003והאי מאן דמצלי רישיה אגירדא דדיקלא\u0004 \u0005[מי שמניח ראשו על גדם של דקל]\u0006 \u0003— אחדא ליה רוח צרדא\u0004 \u0005[אוחזת אותו רוח של כאב חצי הראש]\u0006 (מיגרנה). \u0003האי מאן דפסעי אדיקלא\u0004 \u0005[מי שפוסע על דקל],\u0006 \u0003אי מיקטל\u0004 \u0005[אם נקצץ\u0006 הדקל\u0005]\u0006 — \u0003קטיל\u0004 \u0005[יהרג].\u0006 \u0003אי איעקר\u0004 \u0005[אם נעקר\u0006 הדקל\u0005]\u0006 \u0003—\u0004 הרי גם הוא \u0003מיעקר ומיית\u0004 \u0005[יעקר וימות].\u0006 ומעירים: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים באופן ש\u0003לא מנח כרעיה עילויה\u0004 \u0005[מניח רגליו עליו],\u0006 \u0003אבל\u0004 אם \u0003מנח כרעיה עילויה —\u0004 \u0005[מניח רגליו עליו]\u0006 \u0003לית לן בה\u0004 \u0005[אין לנו בה]\u0006 חשש.","עוד אמרו בענין הצל: \u0003חמשה\u0004 מיני \u0003טולי הוי\u0004 \u0005[צל\u0006 מסוכנים \u0005הם]:\u0006 \u0003טולא דדיקלא יחידא\u0004 \u0005[צל דקל יחיד],\u0006 \u0003טולא דכנדא\u0004 \u0005[צל\u0006 האילן הקרוי \u0005כנדא],\u0006 \u0003טולא דפרחא\u0004 \u0005[צל הצלף],\u0006 \u0003טולא\u0004 \u0005[צל]\u0006 האילן ששמו \u0003זרדתא. איכא דאמרי\u0004 \u0005[יש אומרים]:\u0006 \u0003אף טולא דארבא, וטולא דערבתא\u0004 \u0005[צל של אניה וצל של ערבה].\u0006 \u0003כללא דמילתא\u0004 \u0005[כללו של דבר]:\u0006 \u0003כל\u0004 אילן \u0003דנפיש ענפיה\u0004 \u0005[שמרובים ענפיו] —\u0006 \u0003קשי טוליה\u0004 \u0005[קשה\u0006 מסוכן להיות ב\u0005צילו],\u0006","\u0003וכל\u0004 אילן \u0003דקשי סילויה\u0004 \u0005[שקשה העץ שלו] —\u0006 \u0003קשי טוליה\u0004 \u0005[קשה הצל שלו],\u0006 \u0003לבר\u0004 \u0005[מחוץ]\u0006 לעץ הקרוי \u0003מכרו משא, אף על גב דקשי סילויה לא קשי טוליה\u0004 \u0005[אף על פי שקשה עצו לא קשה צלו],\u0006 \u0003דאמרה לה שידא לברה\u0004 \u0005[שאמרה לה השידה לבנה]\u0006 \u0003פירחי נפשיך מכרו משא, דאיהו הוא דקטיל לאבוך, וקטיל לדידיה\u0004 \u0005[עזבי את\u0006 העץ \u0005כרו משא משום שהוא זה שהרג את אביך והרג את עצמו]\u0006 שאילן זה מזיק לשדים. \u0003אמר רב אשי: חזינא לרב כהנא דפריש מכולהו טולי\u0004 \u0005[ראיתי את רב כהנא שהיה פורש מכל\u0006 מיני \u0005צל].\u0006","ומעירים: \u0003בי פרחי\u0004 \u0005[\u0006מזיקים הנמצאים \u0005ליד הצלף]\u0006 נקראים — \u0003רוחי. דבי זרדתא\u0004 \u0005[\u0006אלה \u0005שליד הזרדים]\u0006 קרואים \u0003— שידא\u0004 \u0005[שדים]\u0006 \u0003דבי איגרי\u0004 \u0005[\u0006אלה המצויים \u0005בגגות]\u0006 קרויים — \u0003רישפי\u0004 \u0005[רשפים].\u0006 ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[\u0006למה, \u0005מה יוצא מכאן,\u0006 למעשה\u0005]?\u0006 \u0003—\u0004 לענין \u0003קמיעא\u0004 \u0005[קמיע]\u0006 אם כותבים קמיע למי שניזוק באחד מהם צריך לדעת מה שם המזיק שהזיקו.","ומעירים: \u0003דבי פרחי —\u0004 \u0005[\u0006המזיק שנמצא \u0005ליד הצלף]\u0006 הוא \u0003בריה שאין לה עינים. למאי נפקא מינה —\u0004 \u0005[למה\u0006, מה \u0005יוצא מכאן\u0006 למעשה\u0005]\u0006 — לענין \u0003לגזוזי לה\u0004 \u0005[בריחה ממנה].\u0006 מסופר: \u0003זימנא חדא הוה אזיל צורבא מרבנן לאפנויי לבי פרחי\u0004 \u0005[פעם אחת הלך תלמיד חכם\u0006 אחד \u0005להפנות\u0006 לצרכיו \u0005ליד הצלף]\u0006 \u0003שמע דקא אתא עילויה, וגזי לה\u0004 \u0005[שמע\u0006 שהמזיק \u0005בא עליו וברח ממנו].\u0006 \u0003כי אזלא\u0004 \u0005[כאשר הלכה\u0006 הרוח הרעה\u0005]\u0006 \u0003חבקיה לדיקלא\u0004 \u0005[החזיק בדקל]\u0006 ונתקל בו המזיק \u0005—\u0006 \u0003צווח דיקלא\u0004 \u0005[יבש הדקל]\u0006 \u0003ופקעה היא\u0004 המזקת.","\u0003פרחא דבי זרדתא\u0004 \u0005[\u0006אותם \u0005המזיקים\u0006 הנמצאים \u0005בזרדים] —\u0006 קרויים \u0003שידי\u0004 \u0005[שדים]\u0006 ומעירים: \u0003הא זרדתא דסמיכה למתא\u0004 \u0005[אותו זרד שסמוך לעיר] —\u0006 \u0003לא פחתא משיתין שידי\u0004 \u0005[אינו\u0006 מכיל \u0005פחות מששים שדים].\u0006 ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא\u0006 מסיפור \u0005זה]?\u0006 ומשיבים: \u0003למיכתב לה קמיעא\u0004 \u0005[לכתוב לה קמיע\u0006 למספר זה\u0005].\u0006","כמסופר: \u0003ההוא בר קשא דמתא דאזיל וקאי גבי זרדתא, דהוה סמיך למתא\u0004 \u0005[אותו מושל העיר שהיה הולך ועומד ליד\u0006 אילן \u0005הזרדתא שהיה סמוך לעיר],\u0006 \u0003עלו ביה שיתין שידי ואיסתכן\u0004 \u0005[עלו עליו ששים שדים והסתכן].\u0006 \u0003אתא לההוא מרבנן דלא ידע דזרדתא דשיתין שידי היא, כתב לה קמיע לחדא שידא\u0004 \u0005[בא לתלמיד חכם\u0006 אחד \u0005שלא ידע שזרדתא\u0006 כזו \u0005של ששים שדים היא, וכתב לו קמיע לשד אחד].\u0006 אותו אדם \u0003שמע דתלו חינגא בגויה, וקא משרו הכי\u0004 \u0005[כאילו עושים חגיגה בתוכו ושרים\u0006 השדים \u0005כך]:\u0006 \u0003סודריה דמר כי צורבא מרבנן\u0004 \u0005[סודרו של אדוני כמו של תלמיד חכם],\u0006 \u0003בדיקנא ביה במר דלא ידע\u0004 \u0005[בדקנו את אדוני ואינו יודע]\u0006 להגיד \u0003\"ברוך\"\u0004 ברכה על לבישת הסודר, שהיו השדים מלעיגים שתלמיד חכם זה אינו יודע כיצד לכתוב בקמיע. \u0003אתא ההוא מרבנן דידע דזרדתא שיתין שידי הוה\u0004 \u0005[בא אחד החכמים שידע שזרדתא היא\u0006 בת \u0005ששים שדים]\u0006 ו\u0003כתב לה קמיעא דשיתין שידי\u0004 \u0005[קמיע של ששים שדים],\u0006 \u0003שמע דקא אמרו\u0004 \u0005[שמע שאומרים]:\u0006 \u0003פנו מנייכו מהכא\u0004 \u0005[פנו את חפציכם מכאן].\u0006","ועוד בעניני מזיקים: \u0003קטב מרירי,\u0004 הנזכר במקרא — \u0003תרי קטבי הוו\u0004 \u0005[שני\u0006 מיני \u0005קטב היו],\u0006 \u0003חד מקמי טיהרא, וחד מבתר טיהרא\u0004 \u0005[אחד\u0006 הבא \u0005לפני הצהרים ואחד אחר הצהרים]\u0006 \u0003דמקמי טיהרא\u0004 \u0005[זה שלפני צהרים] —\u0006 \u0003\"קטב מרירי\" שמו ומיחזי בי כדא דכמכא והדר ביה בחשא\u0004 \u0005[והוא נראה בכד של כותח\u0006 שהולך \u0005ומתגלגל בתוכו].\u0006 ואילו של \u0003בתר טיהרא — \"קטב ישוד צהרים\" שמו, ומיחזי בי קרנא דעיזא והדר ביה כנפיא\u0004 \u0005[ונראה בתוך קרן העז ומתגלגל בו כמו נפה].\u0006","מסופר: \u0003אביי הוה שקיל ואזיל\u0004 \u0005[היה הולך]\u0006 ברחוב, \u0003ואזיל\u0004 \u0005[והיה הולך]\u0006 \u0003רב פפא מימיניה\u0004 \u0005[מימינו]\u0006 \u0003ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע משמאליה\u0004 \u0005[משמאלו].\u0006 \u0003חזייה לההוא קטב מרירי דקא אתי לאפיה דשמאליה\u0004 \u0005[ראה את אותו קטב מרירי שהוא בא לפניו לצד שמאלו]\u0006 \u0003אהדרא\u0004 \u0005[החזיר]\u0006 \u0003לרב פפא לשמאליה\u0004 \u0005[לשמאלו],\u0006 \u0003ולרב הונא בריה דרב יהושע לימיניה\u0004 \u0005[לימינו]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא\u0004 לאביי: \u0003אנא מאי שנא\u0004 \u0005[אני במה שונה\u0006 אני\u0005]\u0006 ש\u0003לא חשש לי\u0004 רבי שאנזק? \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003את שעתא קיימת לך\u0004 \u0005[אתה השעה עומדת לך]\u0006 שעשיר ובן מזל אתה, ומן הסתם לך לא יזיקו.","ומעירים: \u0003מחד בתמוז עד שיתסר ביה\u0004 \u0005[מאחד בתמוז עד ששה עשר בו] —\u0006 \u0003ודאי שכיחי\u0004 \u0005[מצויים הם]\u0006 המזיקים הללו, \u0003מכאן ואילך — ספק שכיחי\u0004 \u0005[מצויים]\u0006 \u0003ספק לא שכיחי\u0004 \u0005[אינם מצויים].\u0006 \u0003ומשתכחי בטולי דחצבא דלא חצב גרמידא\u0004 \u0005[ונמצאים בצילו של חצב שלא גדל אמה]\u0006 \u0003ובטולי דצפרא ופניא דלא הוי גרמידא\u0004 \u0005[ובצל\u0006 חפצים בשעות \u0005בוקר וערב שלא היה\u0006 אורכו \u0005אמה]\u0006 \u0003ועיקר בטולי דבית הכסא\u0004 \u0005[ועיקרם בצל בית הכסא].\u0006","\u0003אמר רב יוסף: הני תלת מילי יהיב ארבונא לנהורא\u0004 \u0005[שלושה דברים אלה גורמים עוורון למאור\u0006 העינים\u0005]:\u0006 \u0003מן דסריק רישיה יבש\u0004 \u0005[מי שסורק את ראשו כשהוא יבש],\u0006 \u0003ומן דשתי טיף טיף\u0004 \u0005[ומי ששותה\u0006 מן היין \u0005המטפטף\u0006 מן החבית\u0005],\u0006 \u0003ומן דסיים מסני אדמייתניה כרעא\u0004 \u0005[ומי שנועל מנעלים כשרגליו לחות\u0006 לאחר רחיצתן\u0005].\u0006","אם דבר מאכל \u0003תלאי בביתא\u0004 \u0005[תלוי בביתו]\u0006 \u0003—\u0004 הרי זה \u0003קשי לעניותא\u0004 \u0005[קשה\u0006 כלומר שגורם \u0005לעניות].\u0006 \u0003כדאמרי אינשי\u0004 \u0005[כמו שאומרים בני אדם]\u0006 בפתגם מקובל: \u0003תלא סילתא\u0004 \u0005[תולה את הסל] —\u0006 \u0003תלא מזוניה\u0004 \u0005[תולה את מזונותיו],\u0006 כלומר, מאבד אותם. \u0003ולא אמרן אלא ריפתא\u0004 \u0005[ולא אמרנו\u0006 דבר זה \u0005אלא\u0006 שתולה \u0005לחם]\u0006 \u0003אבל\u0004 אם תולה \u0003בישרא וכוורי\u0004 \u0005[בשר ודגים]\u0006 \u0003— לית לן בה\u0004 \u0005[אין לנו בהם]\u0006 חשש, משום ש\u0003אורחיה היא\u0004 \u0005[דרכם היא]\u0006 שתולים אותם. \u0003פארי בביתא\u0004 \u0005[מורסן בבית]\u0006 \u0003— קשי לעניותא\u0004 \u0005[קשה לעניות].\u0006 \u0003נשורא בביתא\u0004 \u0005[פירורי\u0006 לחם \u0005בבית] —\u0006 \u0003קשי לעניותא\u0004 \u0005[קשים לעניות].\u0006 ואם היו אלה מפוזרים בבית \u0003בלילי שבתות ובלילי רביעית\u0004 שאז המזיקים מצויים בהם — \u0003שרו\u0004 \u0005[שורים]\u0006 ה\u0003מזיקין עילויה\u0004 \u0005[עליהם].\u0006","\u0003איסרא דמזוני נקיד שמיה\u0004 \u0005[השר\u0006 הממונה על \u0005המזונות נקיד שמו],\u0006 כלומר נקי ומקפיד על נקיות. \u0003איסרא דעניותא נבל שמיה\u0004 \u0005[שר\u0006 הממונה על \u0005העניות נבל שמו]\u0006 ולכן במקום שיש לכלוך השר הממונה על המזונות אינו מצוי ואילו שר העניות נהנה להיות בו. \u0003צעא אפומא דחצבא\u0004 \u0005[צלחת\u0006 שמניחים \u0005על פי הכד]\u0006 \u0003— קשי לעניותא\u0004 \u0005[קשה\u0006 ועלולה להביא \u0005עניות].\u0006 \u0003מאן דשתי מיא בצעי\u0004 \u0005[מי ששותה מים בצלחת]\u0006 \u0003— קשי לברוקתי\u0004 \u0005[קשה לכאב\u0006 העינים\u0005].\u0006 \u0003דאכיל תחלי ולא משי ידיה\u0004 \u0005[מי שאוכל שחליים ואינו נוטל ידיו] —\u0006 \u0003מפחיד תלתין יומין\u0004 \u0005[מפחד שלושים ימים].\u0006"],["\u0003דמסוכר ולא משי ידיה\u0004 \u0005[מי שמקיז דם ואינו נוטל ידיו] —\u0006 \u0003מפחיד שבעה יומי\u0004 \u0005[מפחד שבעה ימים].\u0006 מי \u0003דשקיל מזייה ולא משי ידיה\u0004 \u0005[שנוטל\u0006 גוזז \u0005את שערותיו ואינו נוטל ידיו]\u0006 — \u0003מפחיד תלתא יומי\u0004 \u0005[מפחד שלושה ימים].\u0006 מי \u0003דשקיל טופריה ולא משי ידיה\u0004 \u0005[שנוטל צפרניו ואינו רוחץ את ידיו]\u0006 \u0003— מפחיד חד יומא\u0004 \u0005[מפחד יום אחד]\u0006 \u0003ולא ידע מאי קא מפחיד\u0004 \u0005[ואינו יודע\u0006 מפני \u0005מה מפחד].\u0006 \u0003ידא אאוסיא\u0004 \u0005[יד על הנחיריים] —\u0006 הרי היא \u0003דרגא\u0004 (דרך) היא \u0003לפחדא\u0004 \u0005[ל\u0006הגיע לידי \u0005פחד].\u0006 \u0003ידא אפותא\u0004 \u0005[יד על המצח] —\u0006 \u0003דרגא\u0004 (דרך) היא \u0003לשינתא\u0004 \u0005[ל\u0006הגיע לידי \u0005שינה,\u0006 להרדם\u0005].\u0006","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 היו \u0003אוכלין ומשקין תחת המטה, אפילו\u0004 היו \u0003מחופין\u0004 \u0005[מכוסים]\u0006 \u0003בכלי ברזל — רוח רעה שורה עליהן. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003לא ישתה אדם מים לא בלילי רביעיות ולא בלילי שבתות, ואם שתה — דמו בראשו מפני\u0004 ה\u0003סכנה.\u0004 ומסבירים: \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 ה\u0003סכנה?\u0004 ומשיבים: \u0003רוח רעה\u0004 השולטת בימים אלה.","ושואלים: \u0003ואם צחי מאי תקנתיה\u0004 \u0005[ואם צמא מה תקנתו]\u0006 שיוכל לשתות? ומשיבים: \u0003לימא\u0004 \u0005[שיאמר]\u0006 \u0003שבעה קולות שאמר דוד על המים, והדר נישתי\u0004 \u0005[ואחר כך ישתה].\u0006 \u0003שנאמר\u0004 בכתוב: \u0003\"קול ה' על המים אל הכבוד הרעים ה' על מים רבים קול ה' בכח קול ה' בהדר קול ה' שבר ארזים וישבר ה' את ארזי הלבנון\u0004 וירקידם כמו עגל לבנון ושריון כמו בן ראמים \u0003קול ה' חצב להבות אש קול ה' יחיל מדבר יחיל ה' מדבר קדש קול ה' יחולל אילות ויחשף יערות ובהיכלו כלו אמר כבוד\"\u0004 (תהלים כט, ג-ט).","\u0003ואי לא\u0004 \u0005[ואם אינו\u0006 זוכר\u0005]\u0006 \u0003לימא הכי\u0004 \u0005[שיאמר כך]:\u0006 \u0003\"לול שפן אניגרון אנירדפין\u0004 (שהם שמות מזיקים) \u0003בין כוכבי יתיבנא, בין בליעי שמיני אזילנא\u0004 \u0005[בין הכוכבים אני יושב, בין\u0006 אנשים \u0005בלועים,\u0006 כחושים ו\u0005שמנים אני הולך]\u0006 בחרו מהם לכם את שתרצו והניחוני לנפשי \u0003\". ואי לא\u0004 \u0005[ואם אינו]\u0006 זוכר סגולה זו, \u0003אי איכא איניש בהדיה\u0004 \u0005[אם יש אדם עמו] —\u0006 \u0003ניתעריה\u0004 \u0005[יעירנו]\u0006 \u0003ולימא ליה\u0004 \u0005[ויאמר לו]:\u0006 \u0003\"פלניא בר פלנתא צחינא מייא\u0004 \u0005[פלוני בן פלונית צמא אני למים]\u0006 \u0003\"\u0004\u0003והדר נישתי\u0004 \u0005[ואחר כך ישתה].\u0006 \u0003ואי לא\u0004 כלומר אם אין אדם עמו — \u0003מקרקש נכתמא אחצבא והדר נישתי\u0004 \u0005[שיקיש במכסה על הכוס ואחר כך ישתה].\u0006 \u0003ואי לא\u0004 \u0005[ואם לא]\u0006 יכול — \u0003נישדי בה מידי, והדר נישתי\u0004 \u0005[שיזרוק בו\u0006 ביד \u0005דבר\u0006 מה \u0005ואחר כך ישתה].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003לא ישתה אדם מים לא מן הנהרות ולא מן האגמים בלילה, ואם שתה — דמו בראשו, מפני הסכנה.\u0004 ומסבירים: \u0003מאי סכנה? — סכנת שברירי\u0004 (סנוירים). ושואלים: \u0003ואי צחי מאי תקנתיה\u0004 \u0005[ואם צמא מה תקנתו]?\u0006 \u0003אי איכא איניש בהדיה\u0004 \u0005[אם יש אדם עמו] —\u0006 \u0003לימא ליה\u0004 \u0005[יאמר לו]:\u0006 \u0003\"פלניא בר פלנתא צחינא מיא\u0004 \u0005[פלוני בן פלונית צמא אני למים]\u0006 \u0003\". ואי לא\u0004 \u0005[ואם לא]\u0006 שאין אחר שם \u0005—\u0006 \u0003נימא איהו לנפשיה\u0004 \u0005[יאמר הוא לעצמו]:\u0006 \u0003\"פלניא, אמרה לי אימי איזדהר משברירי\u0004 \u0005[הזהר מסנוירים]\u0006 \u0003\"\u0004ויוסיף ויאמר: \u0003\"שברירי ברירי רירי ירי רי — צחינא מיא בכסי חיורי\u0004 \u0005[צמא אני למים בכוסות\u0006 חרס \u0005לבנות]\u0006","שוב חוזרים אנו למשנה שנאמר בה כי בפסח אין פוחתים מארבע כוסות \u0003ואפילו\u0004 כשצריכים לתת לעני \u0003מן התמחוי.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 מובן הוא, שאם מצות הפסח בכך יש לתת לו לפי הדין!","ומשיבים: \u0003לא נצרכא\u0004 משנה זו \u0003אלא אפילו\u0004 לשיטת \u0003ר' עקיבא,\u0004 ש\u0003אמר: עשה שבתך חול ואל תצטרך לבריות\u0004 כלומר שאם אין אדם יכול לכבד את השבת אם לא יזדקק לעזרה מן הבריות, מוטב שיעשה שבתו כחול ולא יצטרך לבריות — \u0003הכא משום פרסומי ניסא מודי\u0004 \u0005[כאן משום פרסום הנס מודה]\u0006 הוא שראוי לו לבקש עזרה מן הבריות ועליהם לתת לו את הדרוש לו.","ובענין זה \u0003תנא דבי אליהו\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו \u0005של אליהו]:\u0006 \u0003אף על פי שאמר ר' עקיבא עשה שבתך חול ואל תצטרך לבריות — אבל\u0004 בכל זאת \u0003עושה הוא דבר מועט בתוך ביתו\u0004 שיהא שינוי לכבוד שבת. ושואלים: \u0003מאי ניהו\u0004 \u0005[מהו\u0006 אותו\u0005]\u0006 שינוי? \u0003אמר רב פפא:\u0004 כגון \u0003כסא דהרסנא\u0004 \u0005[דגים קטנים מטוגנים].\u0006 \u0003כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005],\u0006 \u0003ר' יהודה בן תימא אומר: הוי עז כנמר וקל כנשר, רץ כצבי וגבור כארי לעשות רצון אביך שבשמים\u0004 וצריך להתאמץ יותר מן הרגיל כדי לעשות לשם מצוה.","כיון שהוזכר מאמר ר' עקיבא יעשה אדם שבתו חול ובלבד שלא יצטרך לבריות, מביאים את דבריו בשלימות. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שבעה דברים צוה ר' עקיבא את ר' יהושע בנו: בני, אל תשב בגובהה של עיר\u0004 שהוא מקום שעוברים ושבים שם בני אדם \u0003ותשנה\u0004 שמא יפסיקוך עוברים ושבים. \u0003ואל תדור בעיר שראשיה תלמידי חכמים\u0004 שמפני שטרודים בתורתם אינם יכולים לעסוק כראוי בצרכי הציבור.","\u0003ואל תכנס לביתך פתאום\u0004 מבלי להקיש בדלת, \u0003כל שכן לבית חבירך\u0004 שמא אין האנשים מוכנים לכך. \u0003ואל תמנע מנעלים מרגליך\u0004 שההולך ללא נעליים בזיון הוא לו. \u0003השכם ואכול, בקיץ מפני החמה\u0004 שטוב שתאכל לפני שיתחמם היום, \u0003ובחורף מפני הצינה\u0004 כדי שיהיה לך כוח לסבול אותה. \u0003ועשה שבתך חול ואל תצטרך לבריות. והוי משתדל,\u0004 כלומר מצטרף ומתחבר \u0003עם אדם שהשעה משחקת לו\u0004 שרואים שהוא מצליח במעשיו.","\u0003אמר רב פפא\u0004 בפירוש דבר זה: \u0003לא למיזבן מיניה ולא לזבוני ליה\u0004 \u0005[לא לקנות ממנו ולא למכור לו],\u0006 שהרי אם השעה משחקת לו אם עושים עימו עסק, בין שמוכרים לו או בין שקונים ממנו הרי הוא שירויח והסוחר עמו יפסיד, \u0003אלא למעבד שותפות בהדיה\u0004 \u0005[לעשות שותפות עמו].\u0006 \u0003והשתא\u0004 \u0005[ועכשיו]\u0006 ששמענו כבר מה ש\u0003אמר רב שמואל בר יצחק: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"מעשה ידיו ברכת\"\u0004 (איוב א, י) ופירש ש\u0003כל הנוטל פרוטה מאיוב מתברך,\u0004 אפילו נטל אותה בדרך מסחר, אם כן הרי שהעוסק עם מי שיש אצלו ברכה \u0003אפילו\u0004 רוצה \u0003למיזבן מיניה ולזבוני ליה שפיר דמי\u0004 \u0005[לקנות ממנו ולמכור לו יפה הדבר\u0006 ומועיל\u0005].\u0006","אגב דברים אלה מביאים עוד מדבריו של ר' עקיבא: \u0003חמשה דברים צוה ר' עקיבא את ר' שמעון בן יוחי כשהיה\u0004 ר' שמעון \u0003חבוש בבית האסורין.\u0004 תחילה \u0003אמר לו\u0004 ר' שמעון: \u0003רבי, למדני תורה, אמר\u0004 לו: \u0003איני מלמדך,\u0004 מפני הסכנה שבדבר. \u0003אמר לו\u0004 בהיתול: \u0003אם אין אתה מלמדני — אני אומר ליוחי אבא\u0004 (אבי) \u0003ומוסרך למלכות.\u0004 כלומר: וכי מה אוכל לעשות לך כדי לשכנע אותך בכך? הלא אתה כבר אסור בבית הסוהר. \u0003אמר לו: בני,\u0004 דע כי \u0003יותר ממה שהעגל רצה לינק פרה רוצה להניק,\u0004 אלא שחושש אני מן הסכנה. \u0003אמר לו: ומי בסכנה? והלא עגל בסכנה\u0004 שהרי אתה אסור כבר, ורק אני עשוי להסתכן.","\u0003אמר לו:\u0004 אם כן, אומר לך דברים אחדים: \u0003אם בקשת ליחנק — היתלה באילן גדול\u0004 שהוא משל לכך, שאם רוצה אתה לומר דבר שיתקבל על לב הבריות, אמור אותו בשם אדם גדול. \u0003וכשאתה מלמד את בנך — למדהו בספר מוגה,\u0004 ושואלים: \u0003מאי היא\u0004 \u0005[מה הוא\u0006 הדבר\u0005]\u0006 במה מדובר? \u0003אמר רבא: ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב משרשיא: בחדתא\u0004 \u0005[ב\u0006לימוד \u0005חדש],\u0006 כי \u0003שבשתא\u0004 \u0005[שגיאה]\u0006 \u0003כיון דעל\u0004 \u0005[שנכנסת]\u0006 \u0003— על\u0004 \u0005[נכנסת],\u0006 שאם בתחילת הלימוד הוא מתחיל בשגיאה תשאר השגיאה מושרשת אצלו לתמיד.","ועוד אמר לו: \u0003לא תבשל בקדירה שבישל בה חבירך.\u0004 ושואלים: \u0003מאי ניהו\u0004 \u0005[מה הוא\u0006 פירוש דבר \u0005זה] —\u0006 שנושא \u0003גרושה בחיי בעלה,\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003גרוש שנשא גרושה — ארבע דעות\u0004 (כעין ארבע אנשים) \u0003במטה\u0004 (בשעת תשמיש), שכן גם היא וגם הוא חושבים גם זה על זה, וגם על בני זוגם הקודמים ויש בכך סירכה של ממזרות. \u0003ואי בעית אימא: אפילו באלמנה\u0004 \u0005[ואם תרצה אמור אפילו באלמנה]\u0006 נכונה עצה זו, \u0003לפי\u0004"],["\u0003שאין כל אצבעות שוות\u0004 שאין תשמיש של זה נוח כשל ראשון ושמא תבוא לזלזל בו או לשונאו בשל כך.","עוד הוסיף ואמר לו: \u0003מצוה וגוף גדול\u0004 כלומר, דבר שיש בעשייתו גם משום מצוה וגם הנאה לגוף — זה מי ש\u0003אוכל פירות ולא שכר,\u0004 כלומר, מלוה לחבירו כסף ונוטל ממנו קרקע כמשכון ואוכל מפירותיה ומנכה דמי פירות אלה מן ההלואה, שבכך יש הנאה גם ללווה וגם למלוה. \u0003מצוה וגוף טהור\u0004 הוא מי ש\u0003נושא אשה\u0004 ועל ידי כך נשמר בטהרה \u0003ולו בנים\u0004 ומקיים מצות פריה ורביה.","כיון שעסקו בענין ציווי חכמים לבניהם או לתלמידיהם, הוסיפו עוד והביאו: \u0003ארבעה דברים צוה רבינו הקדוש את בניו: אל תדור בשכנציב\u0004 שבבבל \u0003משום דליצני הוו, ומשכו לך בליצנותא\u0004 \u0005[משום שליצנים הם, וימשכו אותך בליצנות]\u0006 ויבטלוך מתורה.","וכן \u0003אל תשב על מטת ארמית.\u0004 ונתפרשה עצה זו בכמה דרכים: \u0003איכא דאמרי\u0004 \u0005[יש אומרים]:\u0006 ש\u0003לא תיגני בלא קרית שמע\u0004 \u0005[אל\u0006 תשכב \u0005לישון בלא קריאת שמע]\u0006 שישראל הישן כך נוהג כגוי. \u0003ואיכא דאמרי\u0004 \u0005[ויש אומרים]:\u0006 ש\u0003לא תינסב גיורתא\u0004 \u0005[שלא תשא גיורת]\u0006 והוא הרמוז במלים \"מטה ארמית\" שהרי היתה פעם גויה.","\u0003ואיכא דאמרי\u0004 \u0005[ויש אומרים]:\u0006 מטת \u0003ארמאית\u0004 \u0005[גויה]\u0006 \u0003ממש ומשום מעשה\u0004 של \u0003רב פפא.\u0004 שפעם אחת נכנס ר' פפא לביתה של גויה כדי לגבות ממנה חובו ובקשה ממנו אותה גויה שישב על מטתה עד שתביא מעות, ונתברר שהיה תינוקה המת מוטל תחת המטה והעלילו עליו שהוא ישב עליו והרגו ונאלץ לברוח מחוץ לתחומי המדינה.","\u0003ואל תבריח עצמך מן המכס\u0004 ושלם למוכס, \u0003דילמא משכחו לך ושקלי מנך כל דאית לך\u0004 \u0005[שמא ימצאו אותך\u0006 שהברחת \u0005ויקחו ממך\u0006 כקנס \u0005כל\u0006 מה \u0005שיש לך].\u0006 \u0003ואל תעמוד בפני השור בשעה שעולה מן האגם, מפני שהשטן מרקד בין קרניו\u0004 כלומר השור מסוכן אז ביותר. \u0003אמר ר' שמואל:\u0004 מדובר \u0003בשור שחור, וביומי\u0004 \u0005[בימי,\u0006 בתקופת\u0005]\u0006 \u0003ניסן,\u0004 שאז יש לחשוש במיוחד לדבר.","באותו ענין עצמו \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב אושעיא: מרחיקין משור תם,\u0004 שהוא שור סתם שלא נגח מעודו או שלא נגח יותר מפעמיים — \u0003חמשים אמה\u0004 מתוך זהירות, ו\u0003משור מועד\u0004 שידוע שהוא נגחן — \u0003כמלא עיניו.\u0004","ובהפרזה \u0003תנא משמיה\u0004 \u0005[שנויה משמו]:\u0006 של \u0003ר' מאיר, ריש תורא בדיקולא\u0004 \u0005[ראשו של השור\u0006 עדיין בתוך \u0005הסל\u0006 שאוכל ממנו\u0005] —\u0006 \u0003סק לאיגרא, ושדי דרגא מתותך\u0004 \u0005[עלה לגג וזרוק את הסולם מתחתיך],\u0006 שלא יזיקך. ועוד בענין זה \u0003אמר רב: ניזהא דתורא\u0004 \u0005[האמירה\u0006 שאומרים \u0005לשור\u0006 להוליכו\u0005]\u0006 היא \u0005—\u0006 \u0003\"הן הן\". ניזהא דאריה\u0004 \u0005[האמירה לאריה]\u0006 היא — \u0003\"זה זה\". ניזהא דגמלא\u0004 \u0005[האמירה לגמל]\u0006 — \u0003\"דא דא\". ניזהא דארבא\u0004 \u0005[האמירה לספינה]\u0006 שאומרים לאנשים המושכים אותה לאורך הנהר באמצעות חבלים — \u0003\"הילני הייא הילא והילוק הוליא\".\u0004","\u0003אמר אביי: עור, דג וכוס חמין וביצים וכנים לבנים — כולן קשין לדבר אחר\u0004 (עשויים לגרום צרעת). ומפרשים: \u0003עור — מאן דגני אמשכא דצלא\u0004 \u0005[מי שישן על עור העבדן]\u0006 שאינו מעובד עדיין. \u0003דג\u0004 — הכוונה היא לדג \u0003שיבוטא ביומי\u0004 \u0005[בימי,\u0006 בתקופת\u0005]\u0006 \u0003ניסן. כוס\u0004 — הכוונה ל\u0003שיורי כסא דהרסנא\u0004 \u0005[\u0006שאוכל \u0005משיירי דגים מטוגנים].\u0006 \u0003חמין —\u0004 הכוונה ל\u0003חמימי דחמימי משדרו עילויה\u0004 \u0005[מים חמים\u0006 ביותר \u0005שהוא שופך על עצמו].\u0006 \u0003ביצים —\u0004 הכוונה ל\u0003מאן דמדרך אקליפים\u0004 \u0005[מי שדורך על קליפות].\u0006 \u0003כינים לבנים —\u0004 הכוונה ל\u0003מאן דמחוור לבושיה ולא נטיר ליה תמניא יומי, והדר לבוש לה בריין הנך כינים\u0004 \u0005[מי שמכבס את לבושו ואינו שומר אותו שמונה ימים, וחוזר ולובש אותו —\u0006 \u0005נבראות אותן הכינים]\u0006 \u0003וקשין\u0004 כולם \u0003לדבר אחר.\u0004","\u0003אמר רב פפא: ביתא דאית ביה שונרא — לא ניעול בה איניש בלא מסני\u0004 \u0005[בית שיש בו חתול לא יכנס בו אדם בלא נעליים].\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005] —\u0006 \u0003משום דשונרא קטיל לחיויא ואכיל ליה\u0004 \u0005[שהחתול הורג את הנחש ואוכל אותו]\u0006 \u0003ואית ביה בחיויא גרמי קטיני\u0004 \u0005[ויש בו בנחש עצמות קטנות],\u0006 \u0003ואי יתיב לה גרמא דחיויא אכרעיה\u0004 \u0005[ואם תשב לו עצם\u0006 קטנה \u0005של נחש ברגלו] —\u0006 \u0003לא נפיק ואסתכן ליה\u0004 \u0005[ לא תצא ויסתכן].\u0006 \u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 שכך אמר: \u0003ביתא דלית ביה שונרא\u0004 \u0005[בית שאין בו חתול] —\u0006 \u0003לא ניעול ביה איניש בהכרא\u0004 \u0005[לא יכנס בו אדם בחשיכה],\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 — \u0003דילמא מיכריך ביה חויא ולא ידע ומסתכן\u0004 \u0005[שמא יכרך בו הנחש ולא ידע ויסתכן]\u0006 והחתול צד נחשים ואוכלם.","\u0003שלשה דברים צוה ר' ישמעאל בר' יוסי את רבי:\u0004 (\u0003מק\"ש — מ\u0004ום, מ\u0003ק\u0004 ח, א \u0003ש\u0004תך, הם \u0003סימן\u0004 לציווים אלה), \u0003אל תעש מום בעצמך.\u0004 ושואלים: \u0003מאי היא\u0004 \u0005[מה\u0006 פירוש דבר \u0005זה]?\u0006 ומפרשים: \u0003לא תהוי לך דינא בהדי תלתא\u0004 \u0005[לא יהיה לך דין עם שלושה]\u0006 אנשים שהם יחד בעלי דברך, משום \u0003דחד הוי בעל דינך ותרי סהדי\u0004 \u0005[אחד יהיה בעל דינך ושנים\u0006 יהיו \u0005עדים]\u0006 ויעידו עליך מה שירצו. \u0003ואל תעמוד על המקח בשעה שאין לך דמים\u0004 אף כדי המחיר שאתה מציע, שיש בכך משום אונאה.","\u0003אשתך טבלה — אל תזקק לה לילה הראשונה\u0004 אלא המתן לילה נוסף. \u0003אמר רב:\u0004 ודבר אחרון זה מדובר דווקא \u0003בנדה דאורייתא\u0004 \u0005[שמן התורה],\u0006 שלפי דין התורה גם אם ראתה אשה דם כל שבעה ימים, אם פסקה מלראות אפילו ביום השביעי, הריהי טובלת בסוף היום השביעי ומשמשת מיד. וטעם האיסור: \u0003הואיל והוחזק מעין\u0004 (של דם) \u0003פתוח, דילמא\u0004 \u0005[שמא]\u0006 \u0003משכה זיבה\u0004 \u0005[נמשכת זיבת הדם]\u0006 לאחר מכן ותראה דם בשעת תשמיש. אבל לאחר שהחמירו וקיבלו על עצמן בנות ישראל לישב שבעה נקיים אפילו על טיפת דם כחרדל, לכך נהגו שתמנה אשה עוד שבעה נקיים ותטבול ונזקק אדם לאשתו בליל טבילתה ואינו חושש.","ועוד: \u0003שלשה דברים צוה ר' יוסי בר' יהודה את רבי: אל תצא יחידי בלילה, ואל תעמוד בפני הנר ערום, ואל תכנס למרחץ חדש, שמא תפחת\u0004 שהיו מסיקים את האש מתחת למרחץ ויש חשש שהמרחץ יתמוטט. ושואלים: \u0003עד כמה\u0004 הוא קרוי חדש? \u0003אמר ר' יהושע בן לוי: עד שנים עשר חדש.\u0004 אמרנו: \u0003ואל תעמוד בפני הנר ערום, דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003העומד בפני הנר ערום — הוי\u0004 \u0005[נעשה]\u0006 \u0003נכפה\u0004 (חולה בחולי הנפילה). \u0003והמשמש מטתו לאור הנר — הויין לו\u0004 \u0005[יהיו לו]\u0006 \u0003בנים נכפין.\u0004","בדומה לזה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המשמש מטתו על מטה שתינוק ישן עליה — אותו תינוק\u0004 יהיה \u0003נכפה. ולא אמרן אלא דלא הוי בר שתא\u0004 \u0005[ולא אמרנו\u0006 זאת \u0005אלא שאין\u0006 תינוק זה \u0005בן שנה],\u0006 \u0003אבל הוי בר שתא\u0004 \u0005[אבל היה בן שנתו] —\u0006 \u0003לית לן בה\u0004 \u0005[אין לנו בו]\u0006 חשש. \u0003ולא אמרן\u0004 \u0005[ולא אמרנו]\u0006 \u0003אלא דגני להדי כרעיה\u0004 \u0005[שישן\u0006 התינוק \u0005לצד רגליו],\u0006 \u0003אבל\u0004 אם \u0003גני להדי רישיה\u0004 \u0005[ישן לצד ראשו] —\u0006 \u0003לית לן בה\u0004 \u0005[אין לנו בה]\u0006 חשש. \u0003ולא אמרן\u0004 \u0005[ולא אמרנו]\u0006 \u0003אלא דלא מנח ידיה עילויה\u0004 \u0005[שאינו מניח ידו עליו]\u0006 באותה שעה, \u0003אבל\u0004 אם \u0003מנח ידיה עילויה\u0004 \u0005[מניח ידו עליו] —\u0006 \u0003לית לן בה\u0004 \u0005[אין לנו בו]\u0006 איסור.","ומה שאמר \u0003אל תצא יחידי בלילה, דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לא יצא\u0004 אדם כשהוא \u0003יחידי בלילה, לא בלילי רביעיות ולא בלילי שבתות, מפני\u0004 שהשידה \u0003אגרת בת מחלת, היא ושמונה עשרה רבוא של מלאכי חבלה יוצאין\u0004 אז, \u0003וכל אחד ואחד יש לו רשות לחבל בפני עצמו\u0004 ועל אחת כמה וכמה כשכולם כאחד.","ומסופר: \u0003מעיקרא הוו שכיחי כולי יומא\u0004 \u0005[מתחילה היו מצויים\u0006 אותם מזיקים \u0005בכל יום],\u0006 \u0003זמנא חדא\u0004 \u0005[פעם אחת]\u0006 \u0003פגעה\u0004 אותה שדה \u0003בר' חנינא בן דוסא אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003אי לאו דמכרזן עלך ברקיע\u0004 \u0005[אם לא שהיו מכריזים עליך ברקיע]:\u0006 \u0003\"הזהרו בחנינא ובתורתו\" —\u0004 הרי \u0003סכנתיך. אמר לה: אי חשיבנא ברקיע\u0004 \u0005[אם חשוב אני ברקיע],\u0006 אם כן \u0003גוזר אני עליך שלא תעבורי ביישוב לעולם. אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003במטותא מינך, שבק לי רווחא פורתא\u0004 \u0005[בבקשה ממך הנח לי רווח מועט].\u0006 \u0003שבק לה לילי שבתות ולילי רביעיות\u0004 \u0005[הניח לה לילי שבתות ולילי רביעי].\u0006","\u0003ותו\u0004 \u0005[ועוד]\u0006 מעשה: \u0003חדא זמנא פגעה ביה באביי\u0004 \u0005[פעם אחת פגשה אותו את אביי]\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003אי לאו דמכרזי עלך\u0004 \u0005[אם לא\u0006 אתה הוא \u0005שמכריזים עליך]\u0006 \u0003ברקיע: \"הזהרו בנחמני\"\u0004 הוא אביי \u0003ובתורתו — הוה סכנתיך\u0004 \u0005[הייתי מסכנת אותך].\u0006 \u0003אמר לה: אי חשיבנא\u0004 \u0005[אם חשוב אני]\u0006 \u0003ברקיע — גוזרני עלייכי\u0004 \u0005[גוזר אני עליך]\u0006 \u0003שלא תעבורי ביישוב לעולם.\u0004 ושואלים: \u0003הא קא חזינן דעברה\u0004 \u0005[הרי רואים,\u0006 יודעים \u0005אנו\u0006 שבכל זאת \u0005עוברים\u0006 המזיקים\u0005]?!\u0006 ומשיבים: \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003הני\u0004 \u0005[אלה]\u0006 המזיקים"],["\u0003גזייתא נינהו דשמטי סוסיא ואתו דברי להו\u0004 \u0005[מן הסמטאות הם,\u0006 מן השבילים הסמוכים לישוב הוא \u0005שנשמטים סוסיהם\u0006 לתוך הישוב והם \u0005באים ומנהיגים אותם],\u0006 אבל כרגיל אינם מהלכים בישוב.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב לרב אסי: לא תדור במתא דלא צניף בה סוסיא ולא נבח בה כלבא\u0004 \u0005[אל תגור בעיר שלא צוהל בה סוס ולא נובח בה כלב],\u0006 ששניהם חשובים לצורך שמירה והגנה. \u0003ואל תדור בעיר דריש מתא אסיא\u0004 \u0005[שראש העיר רופא],\u0006 כיון שהוא עסוק בעבודתו אינו עוסק בצרכי העיר, \u0003ולא תנסיב תרתי\u0004 \u0005[ואל תשא שתי\u0006 נשים\u0005],\u0006 שעלולות להזיק לך בעצה משותפת. \u0003אי נסבת תרתי נסיב תלת\u0004 \u0005[\u0006ו\u0005אם\u0006 בכל זאת \u0005נשאת שתים שא שלישית],\u0006 שאף אם תגענה שתים מהן להסכמה שיש בה כדי להזיק לך, הרי השלישית תגלה את אוזניך ותינצל.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב לרב כהנא: הפוך בנבילתא ולא תיפוך במילי\u0004 \u0005[\u0006מוטב \u0005שתהפוך בנבילה ולא תהפוך בדברים],\u0006 לשנות מה שהבטחת. וכן: \u0003פשוט נבילתא בשוקא ושקיל אגרא, ולא תימא \"כהנא אנא, וגברא רבא אנא, וסניא בי מלתא\"\u0004 \u0005[פשוט\u0006 עור ה\u0005נבילה בשוק וקח שכר, ואל תאמר: \"כהן אני, ואדם גדול אני, ומאוס עלי הדבר\"],\u0006 כלומר, שיש לאדם לעסוק במלאכה, אפילו היא בזויה, ובלבד שלא יזדקק לבריות. ועוד: \u0003סלקת לאיגרא\u0004 \u0005[אם עולה אתה לגג]\u0006 \u0003— שירותך בהדך\u0004 \u0005[מזונך אתך],\u0006 שלעולם יהיו מזונותיו של אדם עמו אפילו יוצא לדרך קצרה. \u0003מאה קרי במתא בזוזא\u0004 \u0005[\u0006אם \u0005מאה דלעות בעיר\u0006 במחיר \u0005זוז]\u0006 \u0003— תותי כנפיך ניהוו\u0004 \u0005[תחת כנפיך יהיו],\u0006 ולא יזלזל בדבר מאכל אפילו כשהוא זול, אלא ידאג שתמיד יהיה לו מזונות בביתו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב לחייא בריה\u0004 \u0005[בנו]:\u0006 \u0003לא תשתי סמא\u0004 \u0005[אל\u0006 תתרגל \u0005לשתות סמי\u0006 רפואה\u0005],\u0006 שמא תעשה שתייתך להרגל, שאינך יכול לסור ממנו. \u0003ולא תשוור ניגרא\u0004 \u0005[ואל תקפוץ\u0006 מעבר \u0005לתעלה]\u0006 שלא תתאמץ לפסוע פסיעה גסה שעלולה היא לפגוע בבריאותך. \u0003ולא תעקר ככא\u0004 \u0005[ואל תעקור שן]\u0006 אלא רפאנה ככל האפשר. \u0003ולא תקנא בחיויא\u0004 \u0005[ואל תתגרה בנחש]\u0006 המצוי בביתך, להשתדל להורגו ולהבריחו, \u0003ולא תקנא בארמאה\u0004 \u0005[ואל תתגרה בגוי],\u0006 משום סכנה.","ומעין זה: \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שלשה אין מתקנאין בהן\u0004 כלומר מוטב שלא לעשות קטטה עמם. \u0003ואלו הן: גוי קטן, ונחש קטן, ותלמיד\u0004 חכם \u0003קטן, מאי טעמא\u0004 \u0005[מה טעם] —\u0006 \u0003דמלכותייהו אחורי אודנייהו קאי\u0004 \u0005[שמלכותם אחרי אזניהם עומדת],\u0006 כלומר, בזמן מסויים יגדלו ויתחזקו ואז יתנקמו על שהציק להם תחילה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב לאיבו בריה\u0004 \u0005[בנו]:\u0006 \u0003טרחי בך בשמעתא ולא מסתייע מילתא\u0004 \u0005[טרחתי בך\u0006 בלימוד \u0005ההלכה ולא הצליח הדבר],\u0006 שלא נעשית גדול בתורה. \u0003תא אגמרך מילי דעלמא\u0004 \u0005[בוא ואלמדך דברי,\u0006 דרכי, \u0005העולם].\u0006 \u0003אדחלא אכרעיך\u0004 \u0005[בעוד חול\u0006 הדרך \u0005על רגליך],\u0006 כלומר, מיד בבואך מן הדרך \u0005—\u0006 \u0003זבינך זבין\u0004 \u0005[\u0006את \u0005סחורתך מכור]\u0006 ואל תמתין, שמא ירד המחיר. וכן: \u0003כל מילי זבין ותחרט\u0004 \u0005[על כל דבר שתמכור\u0006 תוכל \u0005להתחרט\u0006 מסיבה כלשהי\u0005] —\u0006 \u0003בר מחמרא דזבין ולא תחרט\u0004 \u0005[חוץ מיין שתמכור ולא תתחרט],\u0006 שהרי עלול הוא להחמיץ ולהפסד לגמרי ויתכן שבמכירתך הצלת את ממונך.","ועוד: \u0003שרי כיסיך, פתח שקיך\u0004 \u0005[\u0006קודם \u0005התר את כיסך\u0006 לקבל את כסף התמורה ורק אחר כך \u0005פתח את שקך\u0006 לתת סחורה תמורתו\u0005],\u0006 ובכך תהיה בטוח בקבלת התמורה. \u0003קבא מארעא ולא כורא מאיגרא\u0004 \u0005[\u0006טוב להרויח \u0005קב\u0006 אחד \u0005מהקרקע ולא כור\u0006 שמרובה פי מאה ושמונים \u0005מהגג]\u0006 כלומר, עדיף שתרויח מעט ממסחר במקום קרוב ובטוח מאשר תתאווה לריווח מרובה במקום רחוק שאינו בטוח.","\u0003תמרא בחלוזך\u0004 \u0005[\u0006אם יש \u0005תמרים במחסנך] —\u0006 \u0003לבית סודנא רהיט\u0004 \u0005[אל בית עושה\u0006 ה\u0005שיכר תרוץ]\u0006 למכרם לו, ואל תעכבם אצלך, שבתוך כך עלולים הם להפסד. ושואלים: \u0003ועד כמה,\u0004 עד איזו כמות של תמרים יכול אדם לשמור בידו בלא למוכרם? \u0003אמר רבא: עד תלתא סאה\u0004 \u0005[עד שלוש סאין].\u0006 \u0003אמר רב פפא: אי לא דרמאי שכרא לא איעתרי\u0004 \u0005[אם לא שהייתי מטיל,\u0006 יצרן, \u0005שיכר, לא הייתי מתעשר].\u0006 \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003רב חסדא: אי לא דרמאי שכרא לא איעתרי\u0004 \u0005[אם לא שהייתי מטיל\u0006 מייצר \u0005שיכר לא הייתי מתעשר].\u0006 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש השם \u0003\"סודנא\"\u0004 שקוראים לעושה השיכר? \u0003אמר רב חסדא: סוד נאה, וגמילות חסדים\u0004 עצה טובה היא זו להרויח כספים, והיא דרך לגמילות חסדים. ועוד עצות בדרכי החיים.","\u0003אמר רב פפא: כל אגב\u0004 \u0005[כל\u0006 דבר שהוא בקנין \u0005אגב]\u0006 וכן כל שטר קנין או התחייבות אחר, אף שלפי הדין שלך הוא — עדיין \u0003גביא בעי\u0004 \u0005[\u0006עדיין \u0005צריך גבייה].\u0006 \u0003כל אשראי\u0004 שנותנים סחורה בהלוואה — \u0003ספק אתי ספק לא אתי\u0004 \u0005[ספק יבוא ספק לא יבוא].\u0006 \u0003ודאתי\u0004 \u0005[והבא] —\u0006 \u0003מעות רעות נינהו\u0004 \u0005[כסף רע הם]\u0006 שיש טורח בגבייתו ואינו מגיע בזמנו.","\u0003שלשה דברים אמר ר' יוחנן משום אנשי ירושלים: כשאתה יוצא למלחמה — אל תצא בראשונה, אלא תצא באחרונה, כדי\u0004 שאם ינוצחו במלחמה ותצטרך לנוס על נפשך \u0003שתכנס בראשונה\u0004 לעיר. \u0003ועשה שבתך חול ואל תצטרך לבריות, והוי משתדל,\u0004 כלומר מצטרף ומתחבר \u0003עם מי שהשעה משחקת לו\u0004 שרואים שהוא מצליח במעשיו.","\u0003אמר רב: שלשה דברים אמר ר' יהושע בן לוי משום אנשי ירושלים: אל תרבה בגנות\u0004 לעשות דברים במקומות גלויים \u0003משום מעשה שהיה\u0004 בדוד ובת שבע. \u0003בתך בגרה — שחרר\u0004 אפילו \u0003עבדך\u0004 הכנעני \u0003ותן לה\u0004 כבעל ואל תניח לבתך הבוגרת לחפש בעל לעצמה. \u0003והוי זהיר באשתך מחתנה הראשון\u0004 שהיא מחבבתו ביותר. \u0003מאי טעמא\u0004 \u0005[מה טעמו\u0006 של דבר\u0005]?\u0006 \u0003רב חסדא אמר: משום ערוה, רב כהנא אמר: משום ממון\u0004 שעלולה לתת לו את ממונך ולהפסידך. ומעירים: \u0003הא והא איתנהו\u0004 \u0005[זה וזה ישנם]\u0006 עלולים להיות, ומוטב שיזהר.","\u0003אמר ר' יוחנן: שלשה\u0004 הם \u0003מנוחלי העולם הבא. אלו הן: הדר בארץ ישראל, והמגדל בניו לתלמוד תורה, והמבדיל על היין במוצאי שבתות.\u0004 ושואלים: \u0003מאי היא\u0004 \u0005[מה הוא\u0006 מה חשיבותו\u0005]\u0006 של זה המבדיל על היין? ומשיבים: \u0003דמשייר מקידושא לאבדלתא\u0004 \u0005[שמשייר מן הקידוש להבדלה]\u0006 שיש לו רק מעט בביתו, ואינו שותה כל השבת אלא משיירו לצורך מצוה.","\u0003אמר ר' יוחנן: שלשה מכריז עליהן הקדוש ברוך הוא בכל יום\u0004 משום שהם נדירים וחשובים, \u0003על רווק הדר בכרך ואינו חוטא\u0004 בנשים, \u0003ועל עני המחזיר אבידה לבעליה\u0004 אף כי הוא דחוק בממון, \u0003ועל עשיר המעשר פירותיו בצינעה\u0004 ואינו מפרסם מעשיו. מסופר: \u0003רב ספרא רווק הדר בכרך הוה\u0004 \u0005[היה]\u0006"],["\u0003תני תנא קמיה דרבא ורב ספרא\u0004 \u0005[שנה התנא\u0006 את הברייתא הזו \u0005לפני רבא ורב ספרא],\u0006 \u0003צהבו\u0004 (האירו) \u0003פניו\u0004 של \u0003רב ספרא\u0004 משמחה שהוא נמנה בין אלו שהקדוש ברוך הוא מכריז עליהם. \u0003אמר לו רבא: לאו כגון מר\u0004 \u0005[לא כמו אדוני]\u0006 לא לאדם כמותך התכוונו, \u0003אלא כגון רב חנינא ורב אושעיא, דהוו אושכפי בארעא דישראל\u0004 \u0005[שהיו סנדלרים בארץ ישראל],\u0006 \u0003והוו יתבי בשוקא דזונות, ועבדי להו מסאני לזונות ועיילי להו\u0004 \u0005[והיו יושבים בשוק של הזונות ועושים מנעלים לזונות\u0006 והזונות \u0005נכנסות אליהם]\u0006 \u0003אינהו מסתכלי בהו ואינהו לא מדלן עינייהו לאיסתכולי בהו\u0004 \u0005[שהן,\u0006 הזונות, \u0005היו מסתכלות בהם, והם,\u0006 החכמים, \u0005לא היו מרימים את עיניהם להסתכל בהן]\u0006 ומתוך קדושתם היתה \u0003מומתייהו הכי\u0004 \u0005[\u0006היתה \u0005שבועתן כך]:\u0006 \u0003בחייהן רבנן קדישי דבארעא דישראל\u0004 \u0005[בחיי החכמים הקדושים שבארץ ישראל],\u0006 ועל אנשים כגון אלה אמרו שמכריזים עליהם בשמים.","ובדומה לכך: \u0003שלשה הקדוש ברוך הוא אוהבן: מי שאינו כועס, ומי שאינו משתכר, ומי שאינו מעמיד על מדותיו,\u0004 כלומר אינו מקפיד על שלו. \u0003שלשה הקדוש ברוך הוא שונאן: המדבר אחד בפה ואחד בלב\u0004 (שהוא צבוע), \u0003והיודע עדות בחבירו ואינו מעיד לו, והרואה דבר ערוה\u0004 (חטא) \u0003בחבירו ומעיד בו יחידי,\u0004 שאין לכך משמעות לענין הדין אלא רק הוצאת שם רע.","\u0003כי הא דטוביה חטא, ואתא זיגוד לחודיה ואסהיד ביה קמיה\u0004 \u0005[כמו אותו\u0006 מעשה \u0005שטוביה חטא\u0006 בערוה, \u0005ובא זיגוד לבדו והעיד בו לפני]\u0006 \u0003רב פפא. נגדיה\u0004 \u0005[\u0006ציוה רב פפא \u0005להכות את]\u0006 \u0003זיגוד אמר ליה\u0004 \u0005[לו]\u0006 זיגוד דבר שנעשה לפתגם עממי: \u0003טוביה\u0004 הוא ש\u0003חטא וזיגוד מינגד\u0004 \u0005[\u0006הוא ש\u0005מוכה]?!\u0006 \u0003אמר ליה\u0004 \u0005[לו] :\u0006 \u0003אין\u0004 \u0005[כן],\u0006 כך צריך להיות, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לא יקום עד אחד באיש\"\u0004 (דברים יט, טו) \u0003ואת לחודך אסהדת ביה\u0004 \u0005[ואתה לבדך העדת בו]\u0006 אם כן אין זו עדות, אלא \u0003שם רע בעלמא קא מפקת ביה\u0004 \u0005[בלבד\u0006 הוא ש\u0005הוצאת עליו].\u0006","\u0003אמר רב שמואל בר רב יצחק אמר רב:\u0004 אף על פי שאינו יכול להעיד בו, מכל מקום, אם רואה דבר שחטא בו חבירו \u0003מותר לשנאתו. שנאמר: \"כי תראה חמור שנאך רובץ תחת משאו\"\u0004 (שמות כג, ה). ומעתה נברר: \u0003מאי \"שונא\"\u0004 זה שנאמר בכתוב? \u0003אילימא שונא\u0004 \u0005[אם תאמר שהשונא\u0006 הוא\u0005]\u0006 \u0003גוי, והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שונא שאמרו — שונא\u0004 שהוא \u0003ישראל ולא שונא גוי.\u0004","\u0003אלא פשיטא\u0004 \u0005[פשוט,\u0006 ברור\u0005]\u0006 שמדובר כאן ב\u0003שונא ישראל\u0004 ולכאורה \u0003ומי שריא למסניה\u0004 \u0005[והאם מותר לשנוא\u0006 אותו\u0005]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"לא תשנא את אחיך בלבבך\"\u0004 (ויקרא יט, יז), הרי שאסור לשנוא את חבירו. \u0003אלא\u0004 תאמר שהכוונה \u0003דאיכא סהדי דעביד איסורא\u0004 \u0005[שיש עדים שעשה איסור],\u0006 בכך הרי \u0003כולי עלמא נמי מיסני סני ליה\u0004 \u0005[כל העולם גם כן\u0006 צריכים \u0005לשנוא אותו],\u0006 אם כן \u0003מאי שנא האי\u0004 \u0005[במה שונה זה]\u0006 שהוא נקרא שונאך שלך? \u0003אלא לאו כי האי גוונא, דחזיא ביה איהו דבר ערוה\u0004 \u0005[האם לא, כגון זה שהוא ראה בו דבר ערוה]\u0006 ויכול לשונאו על רשעותו, אף שהאחרים מתוך שאינם יודעים ממעשיו הרעים אסורים בשנאתו.","\u0003רב נחמן בר יצחק אמר:\u0004 דבר זה אינו רק היתר אלא \u0003מצוה לשנאתו. שנאמר: \"יראת ה' שנאת רע\"\u0004 (משלי ח, יג). \u0003אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי מהו למימרא ליה לרביה למשנייה\u0004 \u0005[האם מותר\u0006 לאדם שראה בחבירו שחטא \u0005לומר לרבו\u0006 שגם הוא \u0005ישנא אותו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003אי ידע דמהימן לרביה כבי תרי\u0004 \u0005[אם יודע\u0006 אותו תלמיד \u0005שהוא נאמן על רבו כשניים]\u0006 ויש בכך תועלת — \u0003לימא ליה,\u0004 \u0005[שיאמר לו],\u0006 \u0003ואי לא\u0004 \u0005[ואם לא] —\u0006 \u0003לא לימא ליה\u0004 \u0005[שלא יאמר לו].\u0006","ועוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שלשה חייהן אינם חיים\u0004 משום שתמיד הם חיים בצער: \u0003הרחמנין, והרתחנין, ואניני הדעת\u0004 (המפונקים שנפשם קצה בדברים). \u0003ואמר רב יוסף: כולהו איתנהו בי\u0004 \u0005[כולם ישנם בי].\u0006","ועוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שלשה שונאין זה את זה, אלו הן: הכלבים, והתרנגולין, והחברין\u0004 (כת המכשפים הפרסית). \u0003ויש אומרים: אף הזונות. ויש אומרים: אף תלמידי חכמים שבבבל\u0004 שונאים זה את זה.","בדומה לזה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שלשה אוהבין זה את זה, אלו הן: הגרים, ועבדים, ועורבין.\u0004","\u0003ארבעה אין הדעת סובלתן\u0004 שהם מרגיזים כל אדם ו\u0003אלו הן: דל גאה, ועשיר מכחש\u0004 בתביעה שתובעים ממנו כדי להרויח ממון, \u0003וזקן מנאף, ופרנס המתגאה על הציבור בחנם. ויש אומרים: אף המגרש את אשתו פעם ראשונה ושניה ומחזירה\u0004 שצריך היה להחליט אם רצונו בה, או אין רצונו בה.","ושואלים: \u0003ותנא קמא\u0004 שלא מנה דבר זה מה טעמו? ומשיבים: \u0003זימנא\u0004 \u0005[פעמים]\u0006 ש\u0003כתובתה מרובה\u0004 וכיון שלא הצליח לשלם כתובתה חייב להחזירה. \u0003אי נמי\u0004 \u0005[או גם כן]:\u0006 \u0003יש לו בנים הימנה ולא מצי מגרש לה\u0004 \u0005[ואינו יכול לגרש אותה],\u0006 שאין לו מי שיטפל בילדים.","ועוד אמרו: \u0003חמשה דברים צוה כנען את בניו,\u0004 כלומר, ודבר זה נראה כמחייב את כל העבדים שבעולם ועל כל אדם להזהר מלעשות כן: \u0003אהבו זה את זה, ואהבו את הגזל, ואהבו את הזמה, ושנאו את אדוניכם, ואל תדברו אמת.\u0004","עוד אמרו: \u0003ששה דברים נאמרים בסוס: אוהב את הזנות, ואוהב את המלחמה, ורוחו גסה, ומואס את השינה, ואוכל הרבה ומוציא קמעה. ויש אומרים: אף מבקש להרוג בעליו במלחמה\u0004 משום שפורץ תמיד לתוך הקרב.","עוד אמרו: \u0003שבעה\u0004 דינם כ\u0003מנודין לשמים\u0004 ולמרות שלא נידו אותם בבית דין — מקפידים עליהם מן השמים, \u0003אלו הן: יהודי שאין לו אשה, ושיש לו אשה ואין לו בנים, ומי שיש לו בנים ואין מגדלן לתלמוד תורה, ומי שאין לו תפילין בראשו ותפילין בזרועו וציצית בבגדו ומזוזה בפתחו והמונע מנעלים מרגליו. ויש אומרים: אף מי שאין מיסב בחבורה\u0004 היושבת לסעודה \u0003של מצוה\u0004 ואינו רוצה להיות במחיצתם.","\u0003אמר רבה בר בר חנה אמר ר' שמואל בר מרתא אמר רב משום\u0004 (משמו) של \u0003ר' יוסי איש הוצל: מניין שאין שואלין בכלדיים\u0004 (חכמי המזלות), \u0003שנאמר: \"תמים תהיה עם ה' אלהיך\"\u0004 (דברים יח, יג) שצריך האדם להיות בטוח בגורלו מאת ה' ואינו צריך לנחש את העתיד לבוא.","\u0003ומניין היודע בחבירו שהוא גדול ממנו אפילו בדבר אחד שחייב לנהוג בו כבוד\u0004 משום כך בלבד, \u0003שנאמר: \"כל קבל די רוח יתירא בה ומלכא עשית להקמותה על כל מלכותא\"\u0004 \u0005[מפני הרוח יתירא בו עשה המלך להקימו על כל המלכות]\u0006 (דניאל ו, ד), ללמדנו שמי שיש לו יתרון רוח, שצריך לכבדו על כך.","ועוד אמרו משמו: \u0003היושבת על דם טהור\u0004 שכל דם שרואה האשה תוך ארבעים יום ללידתה זכר או שמונים יום לנקבה — הריהו טהור, ואם עברו אותם ימים והריהי עומדת בלילה שלאחריהם — \u0003אסורה לשמש\u0004 שמא תראה דם ואותו דם נחשב כדם נדה לכל דבריו. ושואלים: \u0003עד כמה\u0004 תוקפו של איסור זה? \u0003אמר רב: עונה\u0004 כלומר יום או לילה אחד, זהו שיעור הזמן להמתין בו.","כיון שהוזכר ר' יוסי איש הוצל מעירים: \u0003תנא, הוא יוסף איש הוצל, הוא יוסף הבבלי\u0004 שנזכר במקומות אחרים, \u0003הוא\u0004 המכונה \u0003איסי בן גור אריה, הוא איסי בן יהודה, הוא איסי בן גמליאל, הוא איסי בן מהללאל. ומה שמו\u0004 האמיתי? — \u0003איסי בן עקביה שמו.\u0004 ובדומה לזה על חכם אחר \u0003הוא ר' יצחק בן טבלא הוא ר' יצחק בן חקלא, הוא ר' יצחק בן אלעא\u0004 כלומר חכם אחד הוא ויש לו כינויים שונים. הוא"],["\u0003ר' יצחק בן אחא דשמעתא\u0004 \u0005[ש\u0006עוסק \u0005בהלכה],\u0006 כלומר, סתם ר' יצחק המוזכר בעניני הלכה — הוא ר' יצחק בן אחא. וכן \u0003הוא ר' יצחק בן פנחס דאגדתא\u0004 \u0005[ש\u0006עוסק \u0005באגדה],\u0006 שסתם ר' יצחק שבעניני אגדה — ר' יצחק בן פנחס הוא. \u0003וסימניך\u0004 לזכור שמותיהם — הביטוי: \u0003\"שמעו נא אחיי ורעיי\"\u0004 ונזכור אם כן שר' יצחק בן אחא (אחי) הוא זה שעוסק בשמעתא (שמעו).","\u0003אמר רבה בר בר חנה אמר ר' יוחנן משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יהודה בר אילעי: אכול בצל ושב בצל,\u0004 כלומר אכול מאכל זול ובמקום נוח, \u0003ולא תיכול\u0004 \u0005[תאכל]\u0006 \u0003אווזין ותרנגולין\u0004 שהם מהמאכלים היקרים \u0003ויהא לבך רודף עליך\u0004 (אחריך) מחמת תאווה ומחמת חוסר כל. \u0003פחות ממיכלך וממשתיך\u0004 \u0005[ממאכלך וממשתך]\u0006 \u0003ותוסיף על דירתך\u0004 שראוי לאדם להוציא יותר על דירה מאשר על דברי מאכל.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003עולא\u0004 מארץ ישראל לבבל \u0003אמר: מתלא מתלין במערבא\u0004 \u0005[משל מושלים בארץ ישראל]\u0006 \u0003דאכיל אליתא\u0004 \u0005[האוכל אליה\u0006 שמנה\u0005] —\u0006 \u0003טשי בעליתא\u0004 \u0005[מתחבא בעליה],\u0006 מפני הנושים הרודפים אחריו, מתוך שהם חושבים שהוא עשיר. \u0003דאכיל קקולי\u0004 \u0005[האוכל ירקות] —\u0006 \u0003אקיקלי דמתא שכיב\u0004 \u0005[על אשפות העיר שוכב],\u0006 כלומר יושב בראש חוצות ואיננו מתיירא מאחרים.","במשנה ממשיכים לתאר את סדר ליל הפסח. \u0003מזגו לו\u0004 לעורך את הסדר \u0003כוס ראשון. בית שמאי אומרים: מברך על היום\u0004 (קידוש של החג) \u0003ואחר כך מברך על היין\u0004 (\"בורא פרי הגפן\") \u0003ובית הלל אומרים: מברך על היין ואחר כך מברך על היום.\u0004","בתוספתא נתבררה והובהרה מחלוקת זו, וכן שנינו: \u0003תנו רבנן, \u0004אלו הם \u0003דברים שבין בית שמאי ובית הלל\u0004 בהלכות \u0003סעודה. בית שמאי אומרים: מברך על היום ואחר כך מברך על היין, מפני שהיום גורם\u0004 כלומר הקידוש \u0003גורם ליין שיבא\u0004 ולולא זה יתכן שלא היו שותים יין, ועוד טעם ו\u0003כבר קידש היום\u0004 תחילה \u0003ועדין יין לא בא.\u0004","\u0003ובית הלל אומרים: מברך על היין ואחר כך מברך על היום — מפני שהיין גורם לקידוש שתאמר\u0004 שהרי אין אומרים קדוש ללא יין או פת משמע שהיין הוא עיקר. \u0003דבר אחר — ברכת היין תדירה\u0004 היא \u0003וברכת היום אינה תדירה\u0004 ולפי הכלל המקובל בכל מקום \u0003תדיר ושאינו תדיר\u0004 \u0003תדיר קודם.\u0004 ומסכמים כי \u0003הילכתא\u0004 \u0005[הלכה]\u0006 \u0003כדברי בית הלל.\u0004","בבירור דברי תוספתא זו שואלים: \u0003מאי\u0004 \u0005[מה\u0006 טיבו של\u0005]\u0006 \u0003דבר אחר?\u0004 כלומר, לשם מה אומרים בית הלל גם טעם אחר ומדוע לא הסתפקו בטעם הראשון? ומסבירים: \u0003וכי תימא התם תרתי והכא חדא\u0004 \u0005[ואם תאמר שם\u0006 בדברי בית שמאי \u0005שני\u0006 נמוקים \u0005וכאן אחד]\u0006 שהרי בית שמאי טוענים שהיין תלוי בקידוש, ושזמן הקידוש קודם לכן הוסיפו גם בית הלל טעם אחר ואם כן \u0003הכא נמי תרתי נינהו\u0004 \u0005[כאן גם כן שני\u0006 נמוקים \u0005הם]\u0006 והשני הוא: \u0003תדיר ושאינו תדיר\u0004 — \u0003תדיר קודם.\u0004","נאמר שם \u0003והלכה כדברי בית הלל\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 ברור\u0005]\u0006 שכן הוא, \u0003דהא נפיק בת קול\u0004 \u0005[שהרי יצאה בת קול]\u0006 ואמרה שהלכה כבית הלל בכל מחלוקותיהם עם בית שמאי, ומה טעם לפסיקה מיוחדת כאן? ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שברייתא זו נשנתה \u0003קודם בת קול\u0004 והיה צורך לפסוק הלכה בכל מקרה לחוד","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 אפילו \u0003לאחר בת קול,\u0004 אלא כשיטת \u0003ר' יהושע, דאמר: אין משגיחין בבת קול\u0004 ואין פוסקים הלכה לפיה, ולכן היה צורך לפסוק כאן הלכה כבית הלל.","\u0003הביאו לפניו\u0004 הירקות קודם הסעודה העיקרית אם לא היו לפניו ירקות אחרים \u0003מטבל בחזרת\u0004 כלומר מטבל החזרת כדי שתהא טעימה \u0003עד שמגיע לפרפרת הפת\u0004 כלומר למרור שאוכל לשם מצוה אחר אכילת המצה. \u0003הביאו לפניו מצה וחזרת וחרוסת\u0004 ולפחות \u0003שני תבשילין\u0004 מפני כבוד החג. ומעירים שכן נהגו בחרוסת \u0003אף על פי שאין חרוסת מצוה,\u0004 אלא מנהג בלבד. \u0003ר' אליעזר בן צדוק אומר:\u0004 חרוסת \u0003מצוה\u0004 היא. \u0003ובמקדש\u0004 כשהיה קיים והיו מקריבים בו פסחיהם \u0003היו מביאין לפניו גופו\u0004 של קרבן ה\u0003פסח.\u0004"],["\u0003אמר ריש לקיש זאת אומרת\u0004 מסדר הדברים האמור במשנה כי \u0003מצו‍ת צריכות כוונה\u0004 כלומר, צריך אדם להתכוון בשעת עשיית המצוה שהוא עושה בכך את אותה מצוה ויוצא בכך ידי חובתו. ומכאן הראיה: \u0003כיון\u0004 שאת החזרת בפעם הזו ש\u0003לא בעידן חיובא דמרור הוא דאכיל ליה\u0004 \u0005[בזמן חיובו של המרור הוא שאוכל אותה],\u0006 אלא רק על ידי ברכת \u0003\"בורא פרי האדמה\" הוא דאכיל ליה\u0004 \u0005[שאוכל אותה].\u0006 \u0003ודילמא\u0004 \u0005[ושמא]\u0006 \u0003לא איכוון\u0004 \u0005[התכוון]\u0006 \u0003ל\u0004צאת ידי חובת \u0003מרור, הלכך בעי למהדר לאטבולי\u0004 \u0005[לכן צריך לחזור ולהטבילו]\u0006 \u0003לשם מרור. דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך\u0006 לומר\u0005]\u0006 כי \u0003מצוה לא בעיא\u0004 \u0005[צריכה]\u0006 \u0003כוונה,\u0004 אם כן \u0003למה לך תרי טיבולי\u0004 \u0005[שני טיבולים]?\u0006 \u0003והא טביל ליה חדא זימנא\u0004 \u0005[והרי\u0006 כבר \u0005טבל פעם אחת]!\u0006","ודוחים: \u0003ממאי\u0004 \u0005[ממה]\u0006 אתה מוכיח זאת? \u0003דילמא\u0004 \u0005[שמא]\u0006 תאמר: \u0003לעולם מצו‍ת אין צריכות כוונה. ודקאמרת\u0004 \u0005[ומה שאמרת]\u0006 \u0003תרי טיבולי\u0004 \u0005[שני טיבולים]\u0006 \u0003למה לי?\u0004 יש להשיב: \u0003כי היכי דליהוי היכירא\u0004 \u0005[כדי שיהיה היכר]\u0006 שבפסח \u0003לתינוקות,\u0004 לכך נוהגים במנהגים שונים ומוזרים כדי שישאלו התינוקות מה נשתנה ובכלל זה אף הטיבול הנוסף.","\u0003וכי תימא\u0004 \u0005[אם תאמר]:\u0006 אם הטעם רק משום היכר \u0003אם כן לישמעינן\u0004 \u0005[שישמיענו\u0006 במשנה הלכה זו\u0005]\u0006 גם ב\u0003שאר ירקות\u0004 ולא באכילת חזרת שלפני ושאחרי אכילת מצה? יש לומר כי אילו \u0003אשמעינן\u0004 \u0005[היה משמיע לנו]\u0006 \u0003שאר ירקות, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003היכא דאיכא\u0004 \u0005[מקום שיש]\u0006 \u0003שאר ירקות הוא דבעינן תרי טיבולי\u0004 \u0005[הוא שאנו צריכים\u0006 בו \u0005שני טיבולים]\u0006 לירקות האחרים וגם במיוחד למרור, \u0003אבל\u0004 אם היתה לו \u0003חזרת לחודא\u0004 \u0005[לבדה]\u0006 \u0003לא בעי תרי טיבולי\u0004 \u0005[אינו צריך שני טיבולים]\u0006 ודיו בפעם אחת, לכן \u0003קמשמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003אפילו\u0004 אם יש לו \u0003חזרת\u0004 בלבד \u0003בעינן תרי טיבולי\u0004 \u0005[צריכים אנו שני טיבולים],\u0006 \u0003כי היכי דליהוי ביה היכירא לתינוקות\u0004 \u0005[כדי שיהיה בה היכר לתינוקות].\u0006","\u0003ועוד תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אכלן\u0004 את הירקות הללו של הפסח \u0003דמאי\u0004 (שלא ידוע אם התעשרו כבר), כגון שקנה את הירקות מעם הארץ — \u0003יצא. אכלן בלא מתכוין — יצא. אכלן לחצאין\u0004 תחילה חצי זית למרור והפסיק ואחר כך אכל חצי זית נוסף, גם אז — \u0003יצא.\u0004","\u0003ובלבד שלא ישהא בין אכילה של\u0004 חצי כזית אחד \u0003לחבירתה יותר מכדי\u0004 הזמן המספיק \u0003לאכילת פרס\u0004 (חצי ככר לחם) שאז שוב אין אכילות מצטרפות. ומכאן מוכח שאף אם אכלן בלא כוונה יוצא, וקשה אם כן לריש לקיש!","ומשיבים: \u0003תנאי היא\u0004 \u0005[\u0006מחלוקת \u0005תנאים היא]\u0006 בענין זה. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יוסי אומר: אף על פי שטיבל\u0004 לפני האוכל \u0003בחזרת מצוה להביא לפניו חזרת וחרוסת ושני תבשילין,\u0004 ולכאורה הטעם בזה הוא שמשום שלא כיוון באכילה הראשונה לכך צריך להביא לפניו פעם נוספת ובאכילה זו יכוון לשם מצוה.","ומקשים: \u0003ואכתי\u0004 \u0005[ועדיין]\u0006 גם לאחר הבאת מקור זה \u0003ממאי\u0004 \u0005[ממה]\u0006 אתה מסיק שר' יוסי סבור כן מפני שלדעתו מצוות צריכות כוונה? \u0003דילמא קסבר\u0004 \u0005[שמא סבר]\u0006 \u0003ר' יוסי מצו‍ת אין צריכות כוונה, והאי דבעינן תרי טיבולי כי היכי דתיהוי היכירא לתינוקות\u0004 \u0005[ומה שאנו צריכים שני טיבולים כדי שיהיה היכר לתינוקות].\u0006 טענה זו דוחים: \u0003אם כן\u0004 הוא \u0003מאי\u0004 \u0005[מה\u0006 לשון\u0005]\u0006 \u0003\"מצוה\"\u0004 יש בדבר זה שאמר כאן ר' יוסי, שהרי בהיכר לתינוקות עצמו אין משום מצוה, אלא ודאי המצוה היא מצות אכילת מרור עצמה ולכן צריך לחזור ולאכול מפני שמצוות צריכות כוונה.","שואלים: \u0003מאי\u0004 \u0005[מה\u0006 הם\u0005]\u0006 \u0003שני תבשילין\u0004 שהוזכרו במשנה? \u0003אמר רב הונא:\u0004 כגון \u0003סילקא וארוזא\u0004 \u0005[תרד ואורז].\u0006 מסופר: \u0003רבא הוה מיהדר אסילקא וארוזא\u0004 \u0005[היה מחזר על תרד ואורז]\u0006 לאכלם בליל פסח \u0003הואיל ונפיק מפומיה\u0004 \u0005[ויצא מפיו]\u0006 של \u0003רב הונא\u0004 ואף שידע שלא התכון רב הונא דווקא לירקות אלה, מכל מקום רצה לקיים כלשון הרב בדיוק.","\u0003אמר רב אשי: שמע מינה\u0004 \u0005[למד ממנה]\u0006 מדברי \u0003רב הונא\u0004 גם הלכה אחרת בדרך אגב, כי \u0003לית דחייש להא\u0004 \u0005[אין מי שחושש ל\u0006דבר \u0005זה]\u0006 שאמר \u0003ר' יוחנן בן נורי. דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יוחנן בן נורי אומר: אורז מין דגן הוא\u0004 לכל דבר \u0003וחייבין על חימוצו כרת\u0004 בפסח \u0003ואדם יוצא בו ידי חובתו\u0004 משום מצה אם שמרו מחימוץ \u0003בפסח.\u0004 ולכן משמיע לנו רב הונא שאין חוששים לכך.","\u0003חזקיה אמר:\u0004 שני תבשילין אלה הם \u0003אפילו דג וביצה\u0004 שהיו מורחים \u0003עליו\u0004 לצורך טיגונו. ואילו \u0003רב יוסף אמר: צריך שני מיני בשר\u0004 היו מביאים לפניו בליל הפסח, \u0003אחד זכר\u0004 לקרבן ה\u0003פסח, ואחד זכר\u0004 לקרבן \u0003חגיגה\u0004 הנאכלת עם הפסח. \u0003רבינא אמר: אפילו גרמא ובישולא\u0004 \u0005[\u0006חתיכת בשר שעל \u0005העצם\u0006 ורוטב \u0005שנתבשלה\u0006 בו\u0005],\u0006 הרי הם נחשבים כשני תבשילין.","לענין דין ירקות מבררים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 ברור לנו\u0005],\u0006 \u0003היכא דאיכא\u0004 \u0005[היכן שיש]\u0006 \u0003שאר ירקות\u0004 חוץ ממרור \u0003מברך\u0004 בטיבול ראשון \u0003אשאר ירקות \"בורא פרי האדמה\"\u0004 ומכווין לפטור בברכה זו אף את המרור שייאכל מאוחר יותר \u0003ואכיל\u0004 \u0005[ואוכל]\u0006 מהם, \u0003והדר\u0004 \u0005[ואחר כך]\u0006 בטיבול שני \u0003מברך\u0004 על החזרת \u0003\"על אכילת מרור\" ואכיל\u0004 \u0005[ואוכל]\u0006 ממנו.","אולם \u0003היכא דליכא אלא חסא מאי\u0004 \u0005[היכן שאין אלא חזרת מה\u0006 דינו\u0005]?\u0006 כיצד ומתי עליו לברך? \u0003אמר רב הונא: מברך מעיקרא אמרור\u0004 \u0005[מברך מתחילה על המרור]\u0006 \u0003\"בורא פרי האדמה\" ואכיל\u0004 \u0005[ואוכל]\u0006 \u0003ולבסוף\u0004 לאחר המצה \u0003מברך עליה\u0004 \u0005[עליו]\u0006 \u0003\"על אכילת מרור\" ואכיל\u0004 \u0005[ואוכל].\u0006"],["\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 על דעה זו \u0003רב חסדא:\u0004 יכול אתה לומר ש\u0003לאחר שמילא כריסו הימנו\u0004 ואכל בלא ברכה \u0003חוזר ומברך עליה\u0004 בפעם השניה בברכה זו? \u0003אלא אמר רב חסדא: מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003מברך עליה\u0004 \u0005[עליו]\u0006 \u0003\"בורא פרי האדמה\" ו\"על אכילת מרור\" ואכיל\u0004 \u0005[ואוכל],\u0006 \u0003ולבסוף אכיל\u0004 \u0005[אוכל]\u0006 \u0003אכילת חסא בלא ברכה.\u0004","ומעירים: \u0003בסורא עבדי\u0004 \u0005[עושים]\u0006 כשיטת \u0003רב הונא. ורב ששת בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע עביד\u0004 \u0005[היה עושה]\u0006 כשיטת \u0003רב חסדא.\u0004 ומסכמים: \u0003והלכתא כוותיה\u0004 \u0005[והלכה כשיטתו]\u0006 של \u0003רב חסדא.\u0004 מסופר: כי \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא\u0004 היה \u0003מהדר\u0004 \u0005[מחזר]\u0006 על \u0003שאר ירקות\u0004 לפסח כדי \u0003לאפוקי נפשיה מפלוגתא\u0004 \u0005[להוציא עצמו מן המחלוקת]\u0006 שיוכל לברך תחילה \"בורא פרי האדמה\" בלבד ואחר כך \"על אכילת מרור\" ויצא ידי חובה לכל הדעות.","\u0003אמר רבינא: אמר לי רב משרשיא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נתן, הכי אמר\u0004 \u0005[כך אמר]\u0006 \u0003הלל משמיה דגמרא\u0004 \u0005[משם המסורת]:\u0006 \u0003לא ניכרוך איניש מצה ומרור בהדי הדדי וניכול\u0004 \u0005[אל יכרוך אדם מצה ומרור יחד ויאכל],\u0006 \u0003משום דסבירא לן\u0004 \u0005[שאנו סבורים]\u0006 להלכה כי \u0003מצה בזמן הזה\u0004 לאחר חורבן הבית \u0003דאורייתא\u0004 \u0005[שמן התורה]\u0006 מצותה, ואילו אכילת \u0003מרור דרבנן\u0004 \u0005[ש\u0006מדברי \u0005סופרים]\u0006 בלבד היא, כאשר אין אוכלים גם קרבן פסח, ו\u0003אתי\u0004 \u0005[יבוא]\u0006 ה\u0003מרור\u0004 שהוא מצוה \u0003דרבנן\u0004 \u0005[ש\u0006מדברי \u0005סופרים]\u0006 בלבד \u0003ומבטיל ליה\u0004 \u0005[ומבטל אותו]\u0006 את טעמה וממשה של מצות אכילת \u0003מצה\u0004 שהיא \u0003דאורייתא\u0004 \u0005[שמן התורה].\u0006","\u0003ואפילו ל\u0004שיטת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר: מצו‍ת אין מבטלות זו את זו, הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים \u0003דאורייתא בדאורייתא\u0004 \u0005[\u0006מצוה אחת \u0005שמן התורה\u0006 במצוה אחרת \u0005שמן התורה]\u0006 \u0003או דרבנן בדרבנן\u0004 \u0005[\u0006מצוה אחת \u0005ש\u0006מדברי \u0005סופרים\u0006 במצוה אחרת \u0005ש\u0006מדברי \u0005סופרים],\u0006 \u0003אבל\u0004 קיום שתי מצוות \u0003דאורייתא ודרבנן\u0004 \u0005[\u0006מצוה \u0005שמן התורה וש\u0006מדברי \u0005סופרים]\u0006 — \u0003אתי דרבנן ומבטיל ליה לדאורייתא\u0004 \u0005[באה\u0006 מצוה \u0005ש\u0006מדברי \u0005סופרים ומבטלת\u0006 את זו \u0005שמן התורה].\u0006","ושואלים: \u0003מאן תנא דשמעת ליה\u0004 \u0005[מי הוא התנא ששמעת אותו\u0006 אומר\u0005]\u0006 כי \u0003מצו‍ת אין מבטלות זו את זו?\u0004 הרי \u0003הלל היא. דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]\u0006 \u0003אמרו עליו על הלל שהיה כורכן\u0004 את המצה והמרור \u0003בבת אחת ואוכלן.\u0004 והמקור לכך, מתוך \u0003שנאמר: \"על מצות ומררים יאכלהו\"\u0004 (במדבר ט, יא), כלומר יחד.","\u0003אמר ר' יוחנן: חולקין עליו חביריו על הלל\u0004 ואין הכל מסכימים לדעתו. \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא אחרת\u0005]\u0006 : \u0003יכול יהא כורכן בבת אחת ואוכלן כדרך שהלל אוכלן, תלמוד לומר: \"על מצות ומררים יאכלהו\" — אפילו זה\u0004 המצה \u0003בפני עצמו וזה\u0004 המרור \u0003בפני עצמו. מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 על הוכחה זו \u0003רב אשי: אי הכי\u0004 \u0005[אם כך]\u0006 שחכמים חולקים על הלל ואומרים כי מצוות מבטלות זו את זו, \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 לשון \u0003אפילו?\u0004 שמלשון זו משמע שאינם באים לפסול את דרכו של הלל אלא לומר שגם בלא כריכה יוצא.","\u0003אלא אמר רב אשי: האי תנא הכי קתני\u0004 \u0005[תנא זה כך שנה]\u0006 כך יש להבין את דבריו: \u0003יכול לא יצא בהו\u0004 \u0005[בהם]\u0006 \u0003ידי חובתו אלא אם כן כורכן בבת אחת ואוכלן כדרך שהלל\u0004 היה \u0003אוכלן\u0004 ולא באופן אחר — \u0003תלמוד לומר: \"על מצות ומררים יאכלהו\" — אפילו זה בפני עצמו וזה בפני עצמו,\u0004 ואין חובה לנהוג כהלל.","ומעירים: \u0003השתא דלא איתמר הלכתא לא כהלל ולא כרבנן\u0004 \u0005[עכשיו שלא נאמרה הלכה לא כהלל ולא כחכמים],\u0006 כך יש לעשות: \u0003מברך על אכילת מצה ואכיל\u0004 \u0005[ואוכל\u0006 ממנה\u0005]\u0006 לצאת ידי חובת מצה, \u0003והדר\u0004 \u0005[ואחר כך]\u0006 \u0003מברך \"על אכילת מרור\" ואכיל\u0004 \u0005[ואוכל\u0006 ממנו\u0005]\u0006 \u0003והדר אכיל מצה וחסא בהדי הדדי\u0004 \u0005[ואחר כך אוכל מצה וחזרת ביחד]\u0006 \u0003בלא ברכה זכר למקדש,\u0004 כשם שהיה עושה \u0003הלל\u0004 בזמן שבית המקדש היה קיים ואכל מצות ומרורים עם קרבן הפסח.","\u0003אמר ר' אלעזר אמר רב אושעיא: כל\u0004 דבר \u0003שטיבולו במשקה\u0004 שנאכל אגב טבילתו במשקה כלשהו — \u0003צריך נטילת ידים\u0004 לפניו. שמצות נטילת ידים היתה משום גדר טהרה, שלא יבוא אדם לטמא מאכלי תרומה, שכיון שהידים חזקתן טמאות (כדין שני לטומאה) הרי הן מטמאות את המשקה, וכלל הוא שהמשקה שנטמא הופך תמיד להיות ראשון לטומאה וחוזר ומטמא את האוכל שטיבולו בו. \u0003אמר רב פפא: שמע מינה\u0004 \u0005[למד ממנה]\u0006 מהלכה זו המצריכה נטילת ידים, כי \u0003האי חסא\u0004 \u0005[חזרת זו]\u0006 של פסח"],["\u0003צריך לשקועיה\u0004 \u0005[לשקע אותה]\u0006 \u0003בחרוסת משום קפא\u0004 (מרירות וארס) שיש בחזרת. \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר כי \u0003לא צריך לשקועיה\u0004 \u0005[אין צריך לשקעה\u0006 היטב\u0005]\u0006 אם כן \u0003נטילת ידים\u0004 לאכילת מרור \u0003למה לי? הא\u0004 \u0005[הרי]\u0006 \u0003לא נגע\u0004 בידיו במשקה וממילא לא טימאהו! ודוחים: \u0003ודילמא לעולם אימא לך\u0004 \u0005[ושמא לעולם אומר לך]:\u0006 \u0003לא צריך לשקועיה\u0004 \u0005[אין צריך\u0006 מן הדין \u0005לשקעו]\u0006 \u0003וקפא מריחא מיית\u0004 \u0005[והארס מן הריח הוא מת\u0006 ובטל\u0005].\u0006 \u0003אלא למה לי\u0004 בכל זאת \u0003נטילת ידים\u0004 לפני כן — \u0003דילמא משקעו ליה\u0004 \u0005[שמא ישקעו אותו]\u0006 ולכך יש צורך בנטילת ידים כדי שלא להגיע לידי טומאה.","\u0003ואמר רב פפא: לא נישהי איניש מרור בחרוסת\u0004 \u0005[אל ישהה אדם מרור\u0006 בתוך \u0005החרוסת]\u0006 \u0003דילמא אגב חלייה דתבלין מבטיל לה למרוריה\u0004 \u0005[שמא אגב מתיקותו של התבלין מבטל את מרירותו]\u0006 \u0003ובעינן\u0004 \u0005[וצריכים אנו]\u0006 שיהיה בו \u0003טעם מרור וליכא\u0004 \u0005[ואין\u0006 כאן\u0005].\u0006 מסופר: \u0003אדבריה\u0004 \u0005[הרשהו]\u0006 \u0003רב חסדא לרבנא עוקבא\u0004 שידרוש, \u0003ודרש: נטל ידיו\u0004 לפני \u0003טיבול ראשון נוטל ידיו\u0004 אף \u0003בטיבול שני.\u0004","\u0003אמרוה רבנן קמיה\u0004 \u0005[אמרו חכמים\u0006 את ההלכה הזו \u0005לפני]\u0006 \u0003רב פפא\u0004 והוסיפו: \u0003הא בעלמא איתמר\u0004 \u0005[\u0006הלכה \u0005זו בכלל נאמרה]\u0006 ולאו דווקא בפסח, אלא בכל מקרה שהוא מטביל פעמיים. \u0003דאי סלקא דעתך הכא איתמר\u0004 \u0005[שאם עולה על דעתך שכאן\u0006 דווקא לענין פסח \u0005נאמרה],\u0006 אם כן \u0003למה לי נטילת ידים תרי זימני\u0004 \u0005[שתי פעמים]?\u0006 \u0003הא משא ליה ידיה חדא זימנא\u0004 \u0005[הרי כבר נטל את ידיו פעם אחת]\u0006 וכיון שידע שצריך לטבל שנית — ודאי ישמור ידיו מטומאה ולא יצטרך לנטילה שניה! מה שאין כן בשאר טיבולים כשאינו יודע מראש שיחזור ויטבול.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב פפא: אדרבה, הכא איתמר\u0004 \u0005[להפך כאן\u0006 דווקא לענין פסח \u0005נאמר\u0006 הדבר\u0005],\u0006 \u0003דאי סלקא דעתך בעלמא איתמר\u0004 \u0005[שאם עולה על דעתך\u0006 לומר \u0005שבכלל נאמר],\u0006 אם כן \u0003למה לי תרי טיבולי\u0004 \u0005[שני טיבולים]?\u0006 שכרגיל אדם מטבל בפעם אחת, לפני או בתוך סעודתו.","ומקשים: \u0003אלא מאי\u0004 \u0005[מה]\u0006 רוצה אתה לומר כי \u0003הכא איתמר\u0004 \u0005[כאן\u0006 דווקא לענין פסח \u0005נאמר],\u0006 אם כן \u0003נטילת ידים תרי זימני\u0004 \u0005[שתי פעמים]\u0006 \u0003למה לי? הא משא ליה ידיה חדא זימנא\u0004 \u0005[הרי\u0006 כבר \u0005נטל את ידיו פעם אחת]!\u0006 \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003כיון דבעי למימר אגדתא והלילא\u0004 \u0005[שצריך לומר\u0006 את \u0005ההגדה וההלל]\u0006 באמצע, אחר טיבול ראשון, \u0003דילמא אסוחי אסחיה לדעתיה\u0004 \u0005[שמא הסיח את דעתו]\u0006 משמירת ידיו \u0003ונגע\u0004 בדבר המטמא.","\u0003אמר רבא:\u0004 מי ש\u0003בלע מצה\u0004 בלא ללעוס אותה — \u0003יצא\u0004 ידי חובת אכילת מצה, שעיקר המצוה הוא שתאכל. \u0003בלע מרור\u0004 בלא לעיסה — \u0003לא יצא,\u0004 שאין הוא מרגיש כלל טעם מרור. ואם \u0003בלע מצה ומרור\u0004 יחד, \u0003ידי מצה — יצא, ידי\u0004 אכילת \u0003מרור — לא יצא.\u0004 אבל אם \u0003כרכן\u0004 את המצה והמרור \u0003בסיב\u0004 שהוא כעין רשת דקה הצומחת סביב הדקל \u0003ובלען — אף ידי מצה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא יצא,\u0004 שבליעה שאינה נוגעת כלל בחיך אינה נחשבת כאכילה כלל.","\u0003אמר רב שימי בר אשי:\u0004 צריך שתהא \u0003מצה לפני כל אחד ואחד\u0004 מן המסובין לסדר, שהיו יושבים על ספות וכל אחד היה מיסב לפני שולחן נפרד, וכן צריך שיהיה \u0003מרור לפני כל אחד ואחד, וחרוסת לפני כל אחד ואחד.\u0004 אבל \u0003אין עוקרין את השלחן\u0004 לפני האוכל בתוך הסדר \u0003אלא\u0004 מ\u0003לפני מי שאומר הגדה\u0004 בלבד ולא מלפני כולם.","\u0003רב הונא אומר: כולהו נמי\u0004 \u0005[כל\u0006 הדברים, מצה מרור, וחרוסת, \u0005גם כן]\u0006 צריך שיהיו \u0003לפני מי שאומר הגדה.\u0004 וכשיגיע זמן אכילתם יקבלו השאר ממנו. ומעירים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 כשיטת \u0003רב הונא.\u0004","שואלים: \u0003למה עוקרין את השולחן? אמרי דבי\u0004 \u0005[אומרים\u0006 חכמי \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי: כדי שיכירו תינוקות\u0004 בזרות שבדבר \u0003וישאלו\u0004 \"מה נשתנה הלילה הזה\". מסופר: \u0003אביי הוה יתיב קמיה\u0004 \u0005[היה יושב לפני]\u0006 \u0003רבה\u0004 בעודו תינוק, \u0003חזא דקא מדלי תכא מקמיה\u0004 \u0005[ראה שעוקרים את השולחן מלפניו],\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 לאלה שעשו זאת: \u0003עדיין לא קא אכלינן\u0004 \u0005[אכלנו],\u0006 \u0003אתו קא מעקרי תכא מיקמן\u0004 \u0005[ואתם נוטלים את השולחן מלפנינו]?!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה: פטרתן\u0004 \u0005[פטרתנו]\u0006 \u0003מלומר \"מה נשתנה\"\u0004 שהרי כבר שאלת על השינוי שאתה רואה היום.","\u0003אמר שמואל: \"לחם עני\"\u0004 שנאמר במקרא, כוונתו — \u0003לחם שעונין עליו דברים\u0004 כלומר שאומרים עליו את דברי ההגדה. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003\"לחם עני\" — לחם שעונין עליו דברים הרבה. דבר אחר: \"לחם עני\" \"עני\" כתיב\u0004 \u0005[נאמר],\u0006 ועני משמעותו — דלות, ונלמד מכאן \u0003מה עני שדרכו בפרוסה\u0004 משום שאין לו תמיד פת שלמה"],["\u0003אף כאן\u0004 באכילת מצה יש להשתמש דווקא \u0003בפרוסה. דבר אחר: מה דרכו של עני\u0004 ש\u0003הוא מסיק\u0004 את התנור \u0003ואשתו\u0004 היא ש\u0003אופה,\u0004 כדי להזדרז לגמור האפיה לפני שיכלו העצים המעטים שבידו ויתקרר התנור, \u0003אף כאן\u0004 באפיית המצה \u0003נמי\u0004 \u0005[גם כן]\u0006 — \u0003הוא מסיק ואשתו אופה\u0004 כדי שלא יחמיץ, ולכן המצה קרויה \"לחם עוני\".","במשנה נאמר שהיו מביאין לפניו חרוסת \u0003אף על פי שאין חרוסת מצוה.\u0004 ושואלים: \u0003ואי\u0004 \u0005[ואם]\u0006 היא \u0003לא מצוה,\u0004 אם כן \u0003משום מאי מייתי לה\u0004 \u0005[מה מביאים אותה]?\u0006 \u0003אמר ר' אמי: משום קפא\u0004 (הארס) שבמרור, שהחרוסת מבטלת את נזקו. \u0003אמר רב אסי\u0004 אגב דברים אלה: התרופה למי שאכל \u0003קפא דחסא\u0004 \u0005[לארס שבחזרת] —\u0006 \u0003חמא\u0004 \u0005[\u0006לאכול \u0005צנון].\u0006 \u0003קפא דחמא\u0004 \u0005[לארס שבצנון]\u0006 \u0003— כרתי\u0004 \u0005[כרישין].\u0006 \u0003קפא דכרתי\u0004 \u0005[לארס שבכרישין] —\u0006 \u0003חמימי\u0004 \u0005[\u0006מים \u0005חמים].\u0006 \u0003קפא דכולהו — חמימי\u0004 \u0005[ארס של כל\u0006 הירקות נרפא על ידי מים \u0005חמים].\u0006 ומעירים: \u0003אדהכי והכי\u0004 \u0005[בין כך ובין כך]\u0006 עד שמביאים לו את התרופה, \u0003נימא הכי\u0004 \u0005[שיאמר כך],\u0006 לחש לסגולה: \u0003\"קפא קפא, דכירנא לך ולשב בנתיך ולתמני כלתך\u0004 \u0005[ארס ארס, זוכר אני אותך ואת שבע בנותיך ואת שמונה כלותיך]\u0006 \u0003\".\u0004","במשנה נאמר ש\u0003ר' אלעזר בר' צדוק אומר\u0004 שחרוסת \u0003מצוה\u0004 היא. שואלים: \u0003מאי\u0004 \u0005[מה]\u0006 עניינה של \u0003מצוה\u0004 זו? ומשיבים: \u0003ר' לוי אומר: זכר לתפוח\u0004 שהוא אחד ממרכיבי החרוסת, שנאמר: \"מי זאת עולה מן המדבר מתרפקת על דודה תחת התפוח עוררתיך\" (שיר השירים ח, ה), שנדרש כרמז לכנסת ישראל בצאתה ממצרים. \u0003ור' יוחנן אומר: זכר לטיט,\u0004 שהיו ישראל משועבדים במצרים בעבודה בו. \u0003אמר אביי: הלכך\u0004 \u0005[לכן]\u0006 כדי לצאת ידי שתי הדעות \u0003צריך לקהוייה וצריך לסמוכיה\u0004 \u0005[צריך\u0006 לעשותה \u0005חמוצה וצריך\u0006 לעשותה \u0005סמיכה].\u0006 \u0003לקהוייה\u0004 \u0005[ל\u0006עשותה \u0005חמוצה]\u0006 — \u0003זכר לתפוח, וצריך לסמוכיה\u0004 \u0005[ל\u0006עשותה \u0005סמיכה]\u0006 — \u0003זכר לטיט,\u0004 שהוא סמיך.","\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוחנן: תבלין\u0004 ששמים בחרוסת \u0003זכר לתבן\u0004 שהיו עובדים בו אבותינו, \u0003חרוסת\u0004 עצמה \u0003זכר לטיט. אמר ר' אלעזר בר' צדוק: כך היו אומרים תגרי חרך\u0004 (חנונים זעירים) \u0003שבירושלים\u0004 כשהיו מוכרים את החרוסת \u0003בואו וטלו לכם תבלין למצוה.\u0004","\u0003מזגו לו כוס שני וכאן הבן שואל\u0004 את \u0003אביו\u0004 את השאלות על השינוי במנהגי ליל פסח. \u0003ואם אין דעת בבן\u0004 לשאול מעצמו \u0003אביו מלמדו\u0004 בעל פה.","וכך הוא נוסח השאלות: \u0003מה נשתנה הלילה הזה מכל הלילות שבכל הלילות אנו אוכלין חמץ ומצה,\u0004 כפי רצוננו, ואילו \u0003הלילה הזה כולו מצה.\u0004 ועוד: \u0003שבכל הלילות אנו אוכלין שאר ירקות,\u0004 ואילו \u0003הלילה הזה\u0004 אוכלים \u0003מרור.\u0004 ובזמן שבית המקדש קיים היה שואל: \u0003שבכל הלילות אנו אוכלין בשר צלי\u0004 או \u0003שלוק\u0004 (מבושל הרבה), או \u0003מבושל\u0004 כפי רצונינו, ואילו \u0003הלילה הזה כולו\u0004 בשר \u0003צלי\u0004 של פסח. \u0003שבכל הלילות\u0004 אין \u0003אנו\u0004 חייבים \u0003לטבל\u0004 במשקה את הירק הנאכל בסעודה \u0003אפילו פעם אחת,\u0004 ואילו \u0003הלילה הזה\u0004 צריך טיבול \u0003שתי פעמים.\u0004","\u0003ולפי דעתו\u0004 ויכלתו \u0003של\u0004 ה\u0003בן אביו מלמדו\u0004 את כל הקושיות או רק את חלק מהן. ומכאן עונה לו האב, ובאופן כללי \u0003מתחיל בגנות\u0004 בדבר שיש בו משום גינוי לישראל \u0003ומסיים בשבח. ודורש\u0004 את הקטע ש\u0003מ\"ארמי אובד אבי\"\u0004 (דברים כו, ה-ט) שאומרים בשעת הבאת בכורים, \u0003עד שיגמור\u0004 לדרוש את \u0003כל הפרשה כולה.\u0004","\u0003תנו רבנן\u0004 \u0005[ שנו חכמים ]:\u0006 אם \u0003חכם בנו\u0004 ויודע לשאול — \u0003שואלו\u0004 בנו, \u0003ואם אינו חכם — אשתו שואלתו, ואם לאו,\u0004 שאף אשתו אינה יכולה לשאול או שאין לו אשה — \u0003הוא שואל לעצמו, ואפילו\u0004 ישבו יחד \u0003שני תלמידי חכמים שיודעין בהלכות הפסח\u0004 ואין עימם אחר שיכול לשאול — הריהם \u0003שואלין זה לזה.\u0004","במשנה נאמר, שאחת השאלות היתה \u0003מה נשתנה הלילה הזה מכל הלילות, שבכל הלילות אנו מטבילין פעם אחת הלילה הזה שתי פעמים. מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רבא\u0004 על לשון המשנה: \u0003אטו כל יומא לא סגיא דלא מטבלא חדא זימנא\u0004 \u0005[וכי בכל יום לא די שאין אנו\u0006 חייבים להיות \u0005מטבילין פעם אחת]?\u0006 ומלשון המשנה משמע כי בכל יום מטבילים לפחות פעם אחת! \u0003אלא אמר רבא, הכי קתני\u0004 \u0005[כך שנה],\u0006 כך יש לשנות: \u0003שבכל הלילות אין אנו חייבין לטבל אפילו פעם אחת,\u0004 ואילו \u0003הלילה הזה\u0004 חובה להטביל \u0003שתי פעמים.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רב ספרא\u0004 על נוסחה זו: \u0003חיובא לדרדקי?!\u0004 \u0005[חובה לצורך התינוקות]?!\u0006 שהרי כבר אמרנו שהטיבול פעמיים נעשה רק כדי לעורר את התינוקות לשאול וכיצד אפשר לקרוא לדבר מעין זה בלשון \"חייבים\"? \u0003אלא אמר רב ספרא, הכי קתני\u0004 \u0005[כך שנה],\u0006 כך יש לשנות: \u0003אין אנו מטבילין,\u0004 כלומר אין אנו נוהגים בכך \u0003אפילו פעם אחת,\u0004 ואילו \u0003הלילה הזה\u0004 חובה להטביל \u0003שתי פעמים,\u0004 ולשון זו כוללת רשות ומנהג כאחד.","שנינו במשנה שהאב בדברי תשובתו \u0003מתחיל בגנות ומסיים בשבח.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003בגנות\u0004 שנאמר כאן? \u0003רב אמר:\u0004 מתחיל \u0003\"מתחלה עובדי עבודה זרה היו אבותינו\"\u0004 ומסיים בדברי שבח. \u0003ושמואל אמר:\u0004 גנות שמתחילים בה היא \u0003\"עבדים היינו\".\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן לדרו עבדיה\u0004 \u0005[עבדו]:\u0006 \u0003עבדא דמפיק ליה מריה לחירות ויהיב ליה כספא ודהבא מאי בעי למימר ליה\u0004 \u0005[עבד שמוציא אותו אדונו לחירות ונותן לו כסף וזהב מה הוא צריך לומר לו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בעי לאודויי ולשבוחי\u0004 \u0005[צריך להודות ולשבח]\u0006 לאדונו, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 אם כן \u0003פטרתן\u0004 \u0005[פטרתנו]\u0006 \u0003מלומר \"מה נשתנה\"\u0004 שהרי העלית את עיקר עניינו של חג הפסח, \u0003ופתח ואמר\u0004 מיד \u0003\"עבדים היינו\".\u0004","\u0003רבן גמליאל היה אומר: כל שלא אמר\u0004"],["\u0003שלשה דברים אלו בפסח לא יצא ידי חובתו, ואלו הן: פסח, מצה, ומרור,\u0004 וכשהוא מזכיר את אלה הריהו מסביר: \u0003פסח\u0004 מביאים על \u0003שום שפסח המקום\u0004 (ה') \u0003על בתי אבותינו במצרים, שנאמר: \"ואמרתם זבח פסח הוא לה' אשר פסח\u0004 על בתי בני ישראל במצרים בנגפו את מצרים ואת בתינו הציל\u0003\"\u0004 (שמות יב, כז).","\u0003מצה\u0004 לזכרון — \u0003על שום שנגאלו אבותינו ממצרים, שנאמר: \"ויאפו את הבצק אשר הוציאו ממצרים\u0004 עוגות מצות כי לא חמץ כי גורשו ממצרים ולא יכלו להתמהמה וגם צדה לא עשו להם\u0003\"\u0004 (שמות יב, לט). \u0003מרור\u0004 לזכרון — \u0003על שום שמררו המצריים את חיי אבותינו במצרים, שנאמר: \"וימררו את חייהם\u0004 בעבודה קשה בחומר ובלבנים ובכל עבודה בשדה, את כל עבודתם אשר עבדו בהם בפרך\u0003\"\u0004 (שמות א, יד).","ועוד אמרו: \u0003בכל דור ודור חייב אדם לראות את עצמו כאילו הוא\u0004 עצמו \u0003יצא ממצרים, שנאמר: \"והגדת לבנך ביום ההוא לאמר בעבור זה עשה ה' לי בצאתי ממצרים\"\u0004 (שמות יג, ח), ובכל הדורות אומר אדם בלשון \"עשה ה' לי\" ולא אומר בלשון \"לאבותי\".","\u0003לפיכך אנחנו חייבים להודות להלל לשבח לפאר לרומם להדר לברך לעלה ולקלס למי שעשה לאבותינו ולנו את כל הנסים האלו הוציאנו מעבדות לחרות מיגון לשמחה ומאבל ליום טוב ומאפלה לאור גדול ומשעבוד לגאולה ונאמר לפניו הללויה.\u0004 ואז אומר את ההלל שאומרים בכל ימי שמחה.","כיון שאין גומרים את אמירת ההלל לפני הסעודה, אלא רק מקצתו, שואלים: \u0003עד היכן הוא אומר? בית שמאי אומרים: עד\u0004 \"מושיבי עקרת הבית \u0003אם הבנים שמחה\u0004 הללויה\" (תהילים קיג, ט). \u0003ובית הלל אומרים: עד \"\u0004ההופכי הצור אגם מים \u0003חלמיש למעינו מים\"\u0004 (תהילים קיד, ח). \u0003וחותם\u0004 בברכה שהיא מענין \u0003גאולה. ר' טרפון אומר:\u0004 אמנם מברך \u0003אשר גאלנו וגאל את אבותינו ממצרים\u0004 אבל \u0003לא היה חותם\u0004 \"ברוך אתה ה'\".","\u0003ר' עקיבא אומר\u0004 בסגנון זה: \u0003כן ה' אלוהינו ואלהי אבותינו יגיענו למועדים ולרגלים הבאים לקראתנו לשלום שמחים בבנין עירך וששים בעבודתך ונאכל שם מן הפסחים ומן הזבחים וכו' עד ברוך אתה ה' גאל ישראל.\u0004","\u0003אמר רבא:\u0004 כשמזכיר יציאת מצרים \u0003צריך שיאמר: \"ואותנו הוציא משם\".\u0004 ועוד \u0003אמר רבא:\u0004 כשמזכיר \u0003מצה\u0004 בדבריו לזכרון ואומר \"מצה זו שאנו אוכלים\" — \u0003צריך להגביה\u0004 אותה ולהראותה למסובין, וכן כשמזכיר ענין ה\u0003מרור צריך להגביה\u0004 אותו. אבל \u0003בשר\u0004 שאוכל בזמן הזה \u0003אין צריך להגביה. ולא עוד אלא\u0004 שאם מגביה את הבשר הריהו \u0003נראה כאוכל קדשים בחוץ\u0004 שמבינים מדבריו שזהו זבח פסח, ונראה כאילו שחט כבש לקרבן הפסח מחוץ לבית המקדש.","\u0003אמר רב אחא בר יעקב: סומא\u0004 (עיור) \u0003פטור מלומר הגדה\u0004 וראיה לדבר \u0003כתיב הכא\u0004 \u0005[כתוב כאן]\u0006 בענין הפסח: \"והגדת לבנך ביום ההוא לאמר \u0003בעבור זה\u0004 עשה ה' לי בצאתי ממצרים\" (שמות יג, ח) \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בענין בן סורר ומורה, שההורים אומרים: \u0003\"בננו זה\u0004 סורר ומורה איננו שומע בקולנו זולל וסובא\u0003\"\u0004 (דברים כא, כ) ונלמד בגזירה שוה \"זה\" \"זה\": \u0003מה להלן\u0004 בענין בן סורר ומורה דרשו חכמים שהוא \u0003פרט לסומא,\u0004 שאם היה אחד ההורים סומא ואיננו יכול לומר \"בננו זה\" (שהרי איננו יכול להראות עליו), אין מקיימים דין זה, \u0003אף כאן\u0004 בענין אמירת הגדה של פסח \u0003פרט לסומא.\u0004","ומקשים: \u0003איני\u0004 \u0005[וכי כן הוא]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003מרימר: שאלתינהו לרבנן דבי\u0004 \u0005[שאלתי את החכמים מבית\u0006 מדרשו\u0005]\u0006 של \u0003רב יוסף\u0004 שהיה עיור: \u0003מאן דאמר אגדתא בי\u0004 \u0005[מי הוא\u0006 זה \u0005שאמר את ההגדה בביתו]\u0006 של \u0003רב יוסף אמרו\u0004 לו: \u0003רב יוסף\u0004 עצמו אמר. וכן שאל: \u0003מאן\u0004 \u0005[מי]\u0006 הוא זה ש\u0003אמר אגדתא בי\u0004 \u0005[\u0006את \u0005ההגדה\u0006 ב\u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003רב ששת\u0004 שאף הוא היה עיור? \u0003אמרו\u0004 לו: \u0003רב ששת\u0004 עצמו אמר. הרי שאף הסומא חייב באמירת ההגדה! ומשיבים: \u0003קסברי רבנן\u0004 \u0005[סבורים\u0006 היו \u0005חכמים\u0006 אלה, ר' יוסף ור' ששת\u0005]\u0006 כי אכילת \u0003מצה בזמן הזה\u0004 ואמירת ההגדה הצמודה לה היא רק \u0003דרבנן\u0004 \u0005[\u0006מדברי \u0005סופרים ],\u0006 ומשום כך אין מקום להגבלה זו.","ושואלים: האם \u0003מכלל\u0004 דברים אלו יש ללמוד ש\u0003רב אחא בר יעקב\u0004 האומר שהסומא פטור מאמירת ההגדה \u0003סבר\u0004 כי \u0003מצה בזמן הזה דאורייתא\u0004 \u0005[מן התורה\u0006 היא\u0005]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 יודעים אנו כי \u0003רב אחא בר יעקב הוא\u0004 ש\u0003אמר\u0004 (להלן פסחים קכ, א): \u0003מצה בזמן הזה דרבנן\u0004 \u0005[\u0006מדברי \u0005סופרים]\u0006 דווקא, ואם כן יש לכאורה סתירה בדבריו! ומשיבים: \u0003קסבר\u0004 \u0005[סבר]\u0006 רב אחא בר יעקב \u0003כל דתקון רבנן\u0004 \u0005[שתיקנו חכמים]\u0006 בגזירותיהם, בתקנותיהם\u0005,\u0006 \u0003כעין דאורייתא תיקון\u0004 \u0005[\u0006הכתוב \u0005שבתורה תיקנו].\u0006 ולכן אף שמצה בזמן הזה ואמירת ההגדה הצמודה אינם אלא מדברי סופרים, מכל מקום כל חומרות וסייגי התורה חלים בהם, ולכך הסומא פטור מאמירת ההגדה.","ושואלים: על פי טעם זה \u0003לרב ששת ולרב יוסף נמי\u0004 \u0005[גם כן]\u0006 יש להתחשב בנימוק זה, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003ודאי\u0004 ש\u0003כל דתקון רבנן\u0004 \u0005[שתיקנו חכמים],\u0006 \u0003כעין דאורייתא תיקון\u0004 \u0005[\u0006הכתוב \u0005שבתורה תיקנו]?\u0006","ודוחים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]?!\u0006 \u0003בשלמא התם\u0004 \u0005[נניח שם]\u0006 בענין בן סורר ומורה \u0003מדהוה ליה למיכתב\u0004 \u0005[מכיון שהיה לו לכתוב]\u0006 \u0003\"בננו הוא\", וכתיב\u0004 \u0005[ונאמר]\u0006 במקרא \u0003\"בננו זה\", שמע מינה\u0004 \u0005[למד מכאן]\u0006 שבא הדבר ללמד שהם צריכים להצביע עליו באצבע, ומכאן למדים: \u0003פרט לסומין הוא דאתא\u0004 \u0005[שבא]\u0006 הדיוק שבכתוב. \u0003אבל הכא אי לאו\u0004 \u0005[כאן אם לא]\u0006 היה נאמר \u0003\"בעבור זה\" מאי\u0004 \u0005[מה]\u0006 היה יכול \u0003לכתוב? אלא\u0004 \"בעבור זה\" משמעו: \u0003בעבור מצה ומרור הוא דאתא\u0004","שנינו במשנה: \u0003לפיכך אנחנו חייבין:\u0004"],["כיון שהוזכר במשנה שאומרים: \"ונאמר לפניו הללויה\" דנים במשמעות מילה זו. \u0003אמר רב חסדא אמר ר' יוחנן:\u0004 המילה \u0003\"הללויה\",\u0004 והמילה \u0003\"כסיה\",\u0004 וכן המילה \u0003\"ידידיה\" —\u0004 מילה \u0003אחת הן,\u0004 ואין לראותן כצירוף שתי מילים כגון הללו-יה. \u0003רב אמר: \"כסיה\" ו\"מרחביה\" —\u0004 מילה \u0003אחת הן. רבה אמר: \"מרחביה\" בלבד\u0004 היא מילה אחת והשאר — שתים.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 השאלה\u0005]:\u0006 \u0003\"מרחב יה\" ל\u0004שיטת \u0003רב חסדא מאי\u0004 \u0005[מה]\u0006 דינה האם מונה הוא אותה כשתי מילים או כמילה אחת? שהרי לא הזכירה בדבריו. ומשיבים: \u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה ואין ניתן לפותרה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 השאלה\u0005]\u0006 השם \u0003\"ידידיה\"\u0004 לשיטת \u0003רב\u0004 שלא הזכיר אותו, \u0003מאי\u0004 \u0005[מה\u0006 דינה\u0005]?\u0006 ומשיבים: \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 פתרון לכך ממה ש\u0003אמר רב\u0004 במפורש: \u0003\"ידידיה\" נחלק לשנים\u0004 והוא שני שמות, \u0003לפיכך ידיד\u0004 הוא מילת \u0003חול\u0004 כשאר מילים. \u0003יה\u0004 הוא שם \u0003קודש\u0004 וצריך לנהוג בו קדושה כשאר השמות הקדושים.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 השאלה\u0005]\u0006 \u0003\"הללויה\"\u0004 לשיטת \u0003רב מאי\u0004 \u0005[מה\u0006 דינה\u0005]\u0006 האם מלה אחת היא או שתים? ומשיבים: \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 פתרון לכך ממה ש\u0003אמר רב: חזינא תילי דבי חביבא דכתיב בהו\u0004 \u0005[ראיתי את התהילים של בית דודי\u0006 ר' חייא \u0005שנאמר בהם]\u0006 \u0003\"הללו\" בחד גיסא\u0004 \u0005[בצד אחד],\u0006 כלומר, בסוף שורה אחת \u0003ו\"יה\" בחד גיסא\u0004 \u0005[בצד אחד],\u0006 כלומר: בתחילת השורה שלאחריה, ומשמע שמילה זו חלוקה לשתים.","ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה\u0006 דעה זו\u0005]\u0006 על שיטת \u0003ר' יהושע בן לוי.\u0004 ש\u0003אמר ר' יהושע בן לוי: מאי\u0004 \u0005[מה\u0006 משמע\u0005]\u0006 \u0003\"הללויה\" — הללוהו בהלולים הרבה\u0004 ויה שבסיומה הוא לשון הפלגה, ולא שם שמים.","ומעירים: \u0003ופליגא דידיה אדידיה\u0004 \u0005[וחלוקה\u0006 אמרתו זו \u0005של\u0006 ר' יהושע בן לוי \u0005על\u0006 אמרה אחרת \u0005שלו]\u0006 ש\u0003אמר ר' יהושע בן לוי: בעשרה מאמרות\u0004 (לשונות) \u0003של שבח נאמר ספר תהלים:\u0004 בלשון \u0003\"ניצוח\", ב\"נגון\", ב\"משכיל\", ב\"מזמור\", ב\"שיר\", ב\"אשרי\", ב\"תהלה, ב\"תפלה\", ב\"הודאה\", ב\"הללויה\".\u0004 והוא מוסיף: \u0003גדול מכולן \"הללויה\" שכולל שם\u0004 שמים \u0003ושבח בבת אחת.\u0004 משמע שאף הוא סבור ש\"הללויה\" הריהו צירוף של שתי מילים ואחת מהן היא שם.","\u0003אמר רב יהודה אמר שמואל: שיר שבתורה,\u0004 (שירת הים. שמות טו, יט) \u0003משה וישראל אמרוהו בשעה שעלו מן הים.\u0004 ושואלים: \u0003והלל זה\u0004 האמור בתהילים (פרקים קיג - קיח) \u0003מי אמרו?\u0004 ומשיבים: \u0003נביאים שביניהן תקנו להן לישראל שיהו אומרים אותו על כל פרק ופרק,\u0004 כל זמן שיש בו מקום להלל \u0003ועל כל צרה וצרה שלא תבא עליהן\u0004 הרי הם אומרים דברי בקשה שבהלל. \u0003ולכשנגאלין אומרים אותו על גאולתן\u0004 שהרי יש נוסח ההלל גם פסוקי בקשה וגם הודאה על הגאולה.","\u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 \u0003היה רבי מאיר אומר: כל תושבחות האמורות בספר תהלים כלן דוד אמרן שנאמר: \"כלו תפלות דוד בן ישי\"\u0004 (תהלים עב, כ) \u0003אל תיקרי \"כלו\" אלא \"כל אלו\",\u0004 כלומר כל האמור בתהלים תפילות דוד בן ישי הוא.","ומבררים: ולשיטות אחרות \u0003הלל זה מי אמרו?\u0004 ומשיבים: \u0003ר' יוסי אומר: אלעזר בני אומר\u0004 כי \u0003משה וישראל אמרוהו בשעה שעלו מן הים. וחלוקין עליו חביריו לומר שדוד\u0004 המלך הוא ש\u0003אמרו. ונראין דבריו\u0004 של בני אלעזר יותר \u0003מדבריהן.\u0004 והטעם הוא: \u0003אפשר ישראל שחטו את פסחיהן ונטלו לולביהן\u0004 במשך כל אותם הדורות \u0003ולא אמרו שירה?!\u0004 אלא ודאי אמרו שירה וכיון שנוהגים לומר בזמן זה את שירת ההלל ודאי תקנה עתיקה היא לומר הלל זה.","\u0003דבר אחר:\u0004 וכי אפשר ש\u0003פסלו של מיכה עומד בבכי\u0004 כלומר, פסלו של מיכה עומד בזמן דוד \u0003וישראל אומרים את ההלל\u0004 ומזמרים לפניו (ובכי לשון סגי נהור הוא, שלא להזכיר גנות ישראל. גאונים) ואומרים \"כמוהם יהיו עושיהם\", כאשר הפסל נעבד עדיין? אלא ודאי קדום הוא ההלל והוא מימי שירת הים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003כל שירות ותושבחות שאמר דוד בספר תהלים — ר' אליעזר אומר: כנגד עצמו אמרן\u0004 והן תפילות היחיד ואחר כך נמסרו לצבור. \u0003ר' יהושע אומר: כנגד ציבור אמרן\u0004 מתחילה, ואפילו אלה הכתובות על עצמו התכוון בהם לכל העם כולו. \u0003וחכמים אומרים: יש מהן כנגד ציבור ויש מהן כנגד עצמו.\u0004 וכך יש לחלק: \u0003האמורות בלשון יחיד — כנגד עצמו, האמורות בלשון רבים — כנגד ציבור.\u0004","כל מקום שמתחיל בלשון \u0003\"ניצוח\" ו\"ניגון\"\u0004 (\"למנצח בנגינות\") — כוונתו היא שמזמור זה יתקיים \u0003לעתיד לבא.\u0004 ואם המזמור מתחיל בלשון \u0003\"משכיל\"\u0004 — כוונתו שאמרו \u0003על ידי תורגמן,\u0004 שנאמר לרבים כעין דרשה. שהוא אמרו כדרשן הדורש בלחש, והמתורגמן אמרו ופירשו ברבים. ואם נאמר בתחילת המזמור \u0003\"לדוד מזמור\" — מלמד ששרתה עליו שכינה\u0004 תחילה \u0003ואחר כך אמר שירה.\u0004 ואולם במקומות שנאמר \u0003\"מזמור לדוד\" — מלמד שאמר שירה\u0004 תחילה \u0003ואחר כך שרתה עליו שכינה.\u0004","ודרך אגב בא הדבר \u0003ללמדך שאין השכינה שורה, לא מתוך עצלות ולא מתוך עצבות ולא מתוך שחוק ולא מתוך קלות ראש, ולא מתוך דברים בטלים, אלא מתוך דבר שמחה של מצוה.\u0004 וכן תחילה אמר דוד מזמור לה' מתוך שמחה ואחר כך זכה להשראת השכינה. וכעין זה \u0003שנאמר\u0004 באלישע: \u0003\"ועתה קחו לי מנגן והיה כנגן המנגן ותהי עליו יד ה'\"\u0004 (מלכים ב' ג, טו).","\u0003אמר רב יהודה אמר רב: וכן\u0004 היא הדרך גם \u0003לדבר הלכה,\u0004 שראוי להקדים לו שמחה של מצוה. \u0003אמר רב נחמן: וכן לחלום טוב,\u0004 שאם רוצה אדם שיחלום חלום טוב, מוטב שילך לישון מתוך שמחה של מצוה.","ושואלים: \u0003איני\u0004 \u0005[וכי כן הוא]?!\u0006 וכי בשמחה יש ללמוד? והרי \u0003אמר רב גידל אמר רב: כל תלמיד היושב לפני רבו ואין שפתותיו נוטפות מר\u0004 מרירות ודרך ארץ \u0003תכוינה, שנאמר: \"שפתותיו שושנים נטפות מור עבר\"\u0004 (שיה\"ש ה, יג) וכך דורשים: \u0003אל תקרי \"שושנים\" אלא \"ששונים\",\u0004 כלומר: השפתים השונות, וכן \u0003אל תקרי \"מור עבר\" אלא \"מר עבר\",\u0004 שלפני הלימוד צריך שתהא מרירות עוברת בשפתים.","ומשיבים: \u0003לא קשיא\u0004 \u0005[קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שצריך להיות בשמחה של מצוה — \u0003ברבה\u0004 \u0005[ברב],\u0006 \u0003הא\u0004 \u0005[\u0006ו\u0005זה]\u0006 שצריך להיות בכובד ראש ומרירות \u0005—\u0006 \u0003בתלמידא\u0004 \u0005[בתלמיד].\u0006","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003הא והא ברבה\u0004 \u0005[זה וזה\u0006 מדובר \u0005ברב].\u0006 \u0003ולא קשיא\u0004 \u0005[קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שצריך להיות בשמחה \u0003—\u0004 מדובר \u0003מקמי\u0004 \u0005[לפני]\u0006 ש\u0003פתח\u0004 בדברי הלכה, \u0003והא\u0004 \u0005[זה]\u0006 שאמרנו שצריך להיות במרירות \u0003—\u0004 מדובר \u0003לבתר\u0004 \u0005[לאחר]\u0006 ש\u0003פתח,\u0004 שאז צריך להיות בכובד ראש. כפי המסופר: \u0003כי הא\u0004 \u0005[כפי\u0006 שנהג\u0005]\u0006 \u0003רבא, מיקמי\u0004 \u0005[לפני]\u0006 ש\u0003פתח להו לרבנן\u0004 \u0005[להם לחכמים\u0006 בדבריו\u0005]\u0006 \u0003אמר מילתא דבדיחותא ובדחו רבנן\u0004 \u0005[דבר בדיחה והתבדחו החכמים],\u0006 \u0003ולבסוף יתיב באימתא\u0004 \u0005[ישב באימה],\u0006 \u0003ופתח בשמעתא\u0004 \u0005[ב\u0006דבר \u0005הלכה].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הלל זה מי אמרו? ר' אליעזר אומר משה וישראל אמרוהו בשעה שעמדו על הים. הם אמרו: \"לא לנו ה' לא לנו\u0004 כי לשמך תן כבוד\u0003\"\u0004 (תהלים קטו, א), \u0003משיבה רוח הקודש ואמרה להן: \"למעני למעני אעשה\"\u0004 (ישעיה מח, יא). \u0003ר' יהודה אומר: יהושע וישראל אמרוהו, בשעה שעמדו עליהן מלכי כנען\u0004 וניצחום. \u0003הם אמרו: \"לא לנו\" ומשיבה\u0004 רוח הקודש: \"למעני\".","\u0003ר' אליעזר המודעי אומר: דבורה וברק אמרוהו. בשעה שעמד עליהם סיסרא הם אמרו: \"לא לנו\" ורוח הקודש משיבה ואומרת להם: \"למעני למעני אעשה\", ר' אלעזר בן עזריה אומר: חזקיה וסייעתו אמרוהו בשעה שעמד עליהם סנחריב. הם אמרו \"לא לנו\" ומשיבה\u0004 רוח הקודש: \"למעני\" \u0003וכו'. ר' עקיבא אומר: חנניה מישאל ועזריה אמרוהו, בשעה שעמד עליהם סנחריב הם אמרו \"לא לנו\" ומשיבה\u0004 רוח הקודש: \"למעני\" \u0003וכו'. ר' יוסי הגלילי אומר מרדכי ואסתר אמרוהו בשעה שעמד עליהם המן הרשע הם אמרו \"לא לנו\" ומשיבה\u0004 רוח הקודש: \"למעני\" וכו'.","\u0003וחכמים אומרים\u0004 לא לתאריך מסויים ולמאורע מסיוים ניתקן, אלא \u0003נביאים שביניהן תיקנו להם לישראל שיהו אומרים אותו על כל פרק ופרק ועל כל צרה וצרה שלא תבא עליהם לישראל, ולכשנגאלין אומרים אותו\u0004 את ההלל \u0003על גאולתן,\u0004 בתור דברי תודה.","ועוד בענין הללויה, \u0003אמר רב חסדא: \"הללויה\"\u0004 האמור בפסוק האחרון שבכמה פרקי תהלים — \u0003סוף פירקא\u0004 \u0005[סוף הפרק]\u0006 הוא, המילה האחרונה בו. \u0003רבה בר רב הונא אמר: \"הללויה\" — ריש פירקא\u0004 \u0005[תחילת הפרק]\u0006 ויש להבינו כפתיחה לפרק הבא. \u0003אמר רב חסדא: חזינא להו לתילי דבי\u0004 \u0005[ראיתי\u0006 את ספר \u0005התהילים של\u0006 בית מדרשו\u0005]\u0006 של \u0003רב חנין בר רב דכתיב בהו\u0004 \u0005[שנאמר בהם]\u0006 \u0003\"הללויה\" באמצע פירקא\u0004 \u0005[הפרק],\u0006 כלומר בין פרק לפרק ולא בסוף ולא בתחילה. \u0003אלמא מספקא ליה\u0004 \u0005[מכאן שהיה מסופק לו]\u0006 לאן שייכת המילה.","\u0003אמר רב חנין בר אבא: הכל מודים\u0004 בפסוק כגון \u0003\"תהלת ה' ידבר פי ויברך כל בשר שם קדשו לעולם ועד\"\u0004 (תהילים קמה, כא) כי \u0003\"הללויה\" דבתריה\u0004 \u0005[שאחריו]\u0006 (בתהילים קמו, א) — \u0003ריש פירקא\u0004 \u0005[ראש הפרק]\u0006 הוא ולא סופו. וכן: \u0003\"רשע יראה וכעס שניו יחרק ונמס תאות רשעים תאבד\"\u0004 (תהילים קיב, י), \u0003\"הללויה\" דבתריה\u0004 \u0005[שאחריו]\u0006 (תהילים קיג, א) — \u0003ריש פירקא\u0004 \u0005[ראש הפרק]\u0006 הוא. וכן: \u0003\"שעומדים בבית ה'\"\u0004 (תהילים קלה, ב) \u0003\"הללויה\" דבתריה\u0004 \u0005[שאחריו] —\u0006 \u0003ריש פירקא\u0004 (תהילים קלה, ג) \u0005[ראש פרק]\u0006 הוא.","\u0003קראי\u0004 (החכמים הבקיאים במקרא) \u0003מוסיפין אף את אלו: \"מנחל בדרך ישתה על כן ירים ראש\"\u0004 (תהילים קי, ז) \u0003הללויה דבתריה\u0004 \u0005[שאחריו]\u0006 (תהילים קיא, א) \u0005—\u0006 \u0003ריש פירקא\u0004 \u0005[ראש פרק]\u0006 הוא. וכן: \u0003\"ראשית חכמה יראת ה' שכל טוב לכל עשיהם\u0004 תהלתו עומדת לעד\u0003\"\u0004 (תהילים קיא, י) \u0003\"הללויה\" דבתריה\u0004 \u0005[שאחריו]\u0006 (תהילים קיב, א) \u0005—\u0006 \u0003ריש פירקא\u0004 \u0005[ראש פרק]\u0006 הוא.","ומציעים: \u0003נימא כתנאי\u0004 \u0005[האם\u0006 אפשר \u0005לומר\u0006 שיש כאן מחלוקת \u0005תנאים]\u0006 ששנינו במשנתנו: \u0003עד היכן הוא אומר\u0004 בהלל בתחילת סדר ליל פסח, \u0003בית שמאי אומרים: עד \"אם הבנים שמחה\"\u0004 (תהילים קיג, ט) \u0003ובית הלל אומרים: עד \"חלמיש למעינו מים\"\u0004 (תהילים קיד, ח). \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת],\u0006 \u0003עד היכן הוא אומר? בית שמאי אומרים: עד \"בצאת ישראל ממצרים\"\u0004 (תהילים קיד, א) שהוא ראשית הפרק מיד אחר \"אם הבנים שמחה הללויה\". \u0003ובית הלל אומרים: עד \"לא לנו ה' לא לנו\"\u0004 (תהילים קטו, א), שהוא מיד לאחר \"חלמיש למעינו מים\"."],["\u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא בזה נחלקו]\u0006 שתי ברייתות אלו: \u0003למאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 שצריך לומר \u0003עד \"אם הבנים שמחה\" — סבר\u0004 כי \u0003\"הללויה\"\u0004 שנאמר אחריו הריהו \u0003ריש פירקא\u0004 \u0005[תחילת הפרק],\u0006 \u0003ומאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 שצריך לומר \u0003עד \"בצאת ישראל\" סבר\u0004 כי \u0003\"הללויה\" סוף פירקא\u0004 \u0005[סוף הפרק]\u0006 הקודם ולא נחלקו אלא במילה \"הללויה\" אם לאמרה בשלב זה או עם חידוש אמירת ההלל לאחר הסעודה.","ודוחים: אין להוכיח מכאן, \u0003רב חסדא מתרץ לטעמיה\u0004 \u0005[מיישב\u0006 את ההבדל בין הברייתות \u0005לשיטתו],\u0006 \u0003דכולי עלמא סברי\u0004 \u0005[שהכל סבורים]:\u0006 כי \u0003\"הללויה\" סוף פירקא\u0004 \u0005[הפרק]\u0006 הוא ואילו \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 שצריך לומר \u0003עד \"בצאת ישראל\" — שפיר\u0004 \u0005[יפה],\u0006 שהרי הוא מתחיל מן הפסוק הבא, \u0003ומאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 שצריך לומר \u0003עד \"אם הבנים שמחה\"\u0004 כוונתו היתה \u0003עד ועד בכלל,\u0004 ויגמור כל הפסוק ו\"הללויה\" בכללו.","ומקשים: \u0003ונימא\u0004 \u0005[\u0006אם כן \u0005שיאמר]\u0006 התנא \u0003עד \"הללויה\"! וכי תימא\u0004 \u0005[ואם תאמר]\u0006 ש\u0003לא ידעינן הי\u0004 \u0005[יודעים אנו איזו]\u0006 \u0003\"הללויה\"\u0004 כוונתו \u0003ונימא\u0004 \u0005[ושיאמר]\u0006 \u0003\"הללויה\" של \"אם הבנים שמחה\"?\u0004 ומעירים: אכן \u0003קשיא\u0004 \u0005[קשה\u0006 הדבר\u0005]\u0006 לשיטת רב חסדא.","וכן \u0003רבה בר רב הונא מתרץ לטעמיה\u0004 \u0005[מיישב\u0006 את סתירת הברייתות \u0005לטעמו,\u0006 לשיטתו\u0005]:\u0006 \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003\"הללויה\" — ריש פירקא\u0004 \u0005[תחילת הפרק]\u0006 הוא, \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 שצריך לומר \u0003עד \"אם הבנים שמחה\" — שפיר\u0004 \u0005[יפה],\u0006 \u0003ומאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 שצריך לומר \u0003עד \"בצאת ישראל\", סבר\u0004 כי מה שאנו אומרים \"עד\" כוונתו \u0003עד ולא עד בכלל\u0004 ולא מסיימים ב\"הללויה\" שלאחר \"אם הבנים\".","ומקשים אף לשיטתו: \u0003ונימא\u0004 \u0005[ושיאמר]\u0006 שאומרים \u0003עד \"הללויה\", וכי תימא דלא ידעינן הי\u0004 \u0005[ואם תאמר שאיננו יודעים באיזה]\u0006 \u0003\"הללויה\"\u0004 מדובר \u0003ונימא\u0004 \u0005[שיאמר]\u0006 \u0003עד \"הללויה\" ש\"בצאת ישראל\"?\u0004 ומסכמים: כי גם לשיטה זו אכן \u0003קשיא\u0004 \u0005[קשה\u0006 הדבר\u0005].\u0006","שנינו במשנה כי \u0003חותם בגאולה.\u0004 אגב מחלוקת זו בנוסח חתימת הברכה, \u0003אמר רבא:\u0004 בסוף \u0003קריאת שמע\u0004 ובסוף \u0003הלל\u0004 של פסח — לשון חתימת הברכה היא \u0003\"גאל ישראל\",\u0004 שהיא לשון עבר. \u0003דצלותא\u0004 \u0005[ש\u0006בתוך \u0005התפילה\u0006 שמונה עשרה\u0005]\u0006 — החתימה היא \u0003\"גואל ישראל\",\u0004 בלשון הווה. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 השינוי\u0005]\u0006 — כי בתפילה \u0003רחמי נינהו\u0004 \u0005[בקשה היא]\u0006 ולכן מזכירים גאולה שבכל עת, שציפייתנו ובקשתנו בתפילתנו לגאולה.","וכן בדומה לזה \u0003אמר ר' זירא: דקידושא\u0004 \u0005[\u0006הנוסח \u0005בקידוש]\u0006 הוא — \u0003\"אשר קדשנו במצותיו וצונו\",\u0004 בלשון עבר, אבל \u0003דצלותא\u0004 \u0005[\u0006הנוסח \u0005שבתפילה\u0006 הוא\u0005]\u0006 \u0003\"קדשנו במצותיך\"\u0004 — לשון עתיד. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 ההבדל\u0005],\u0006 כי בתפילה \u0003דרחמי נינהו\u0004 \u0005[ש\u0006לשון בקשת \u0005רחמים הם]\u0006 וצריך לבקש על העתיד.","\u0003אמר רב אחא בר יעקב: וצריך שיזכיר יציאת מצרים בקידוש היום\u0004 של שבת, אף שהשבת אינה קשורה ישירות ביציאת מצרים. וראיה לדבר: \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בפסח: \u0003\"למען תזכר את יום\u0004 צאתך מארץ מצרים כל ימי חייך\u0003\"\u0004 (דברים טז, ג), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בשבת \u0003\"זכור את יום השבת לקדשו\"\u0004 (שמות כ, ח) ולומדים גזירה שוה \"יום\" \"יום\". שאף בשבת יש להזכיר יציאת מצרים.","ועוד בנוסחות התפילות, \u0003אמר רבה בר שילא: דצלותא\u0004 \u0005[\u0006אותה \u0005תפילה]\u0006 שמדברים בה על כינון מלכות ישראל, חותמים בה: \u0003\"מצמיח קרן ישועה\", דאפטרתא\u0004 \u0005[\u0006זו שאומרים \u0005ב\u0006ברכות \u0005ההפטרה],\u0006 מסיימים בה: \u0003\"מגן דוד\".\u0004","ומעירים אגב כך על הכתוב שהבטיח ה' לדוד על ידי נתן הנביא: \u0003\"ועשיתי לך שם גדול כשם הגדלים\u0004 אשר בארץ\u0003\"\u0004 (שמואל ב' ז, ט). \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף: זהו\u0004 כוונת \"כשם הגדולים\", \u0003שאומרים \"מגן דוד\"\u0004 כדרך שאומרים על גדול האבות \"מגן אברהם\".","\u0003אמר ר' שמעון בן לקיש:\u0004 בברכת ה' לאברהם נאמר: \"ואעשך לגוי גדול ואברכך ואגדלה שמך והיה ברכה\" (בראשית יב, ב) ויש להבין: \u0003\"ואעשך לגוי גדול\" — זהו שאומרים\u0004 בתפילה \u0003\"אלהי אברהם\", \"ואברכך\" — זהו שאומרים \"אלהי יצחק\",\u0004 שיש בכך ברכה לאב שבנו זוכה לשם עולם. \u0003ו\"אגדלה שמך\" — זהו שאומרים \"אלהי יעקב\".\u0004","\u0003יכול יהו חותמין\u0004 את הברכה \u0003בכולן\u0004 בכל שמות האבות? \u0003תלמוד לומר\u0004 בסוף הכתוב: \u0003\"והיה ברכה\"\u0004 כלומר: אתה תהיה ברכה, \u0003בך חותמין ואין חותמין בכולן,\u0004 שאומרים \"מגן אברהם\".","\u0003אמר רבא: אשכחתינא לסבי דפומבדיתא דיתבי וקאמרי\u0004 \u0005[מצאתי את זקני פומבדיתא שיושבים ואומרים]:\u0006 \u0003בשבתא, בין בצלותא בין בקידושא\u0004 \u0005[בשבת, בין בתפילה בין בקידוש]\u0006 אומרים: \u0003\"מקדש השבת\". ביומא טבא, בין בצלותא ובין בקידושא\u0004 \u0005[ביום טוב, בין בתפילה בין בקידוש]\u0006 אומרים: \u0003\"מקדש ישראל והזמנים\". ואמינא להו אנא\u0004 \u0005[ואמרתי להם אני]:\u0006 \u0003אדרבה\u0004 \u0005[להפך],\u0006 \u0003דצלותא\u0004 \u0005[\u0006זה \u0005שבתפילה]\u0006 \u0003בין בשבתא בין ביומא טבא\u0004 \u0005[בין בשבת\u0006 ו\u0005בין ביום טוב]\u0006 צריך לומר: \u0003\"מקדש ישראל\",\u0004 ואילו \u0003בקידושא דשבתא\u0004 \u0005[בקידוש של שבת]\u0006 צריך לומר: \u0003\"מקדש השבת\".\u0004 ובקידוש של \u0003יומא טבא\u0004 \u0005[יום טוב]\u0006 צריך לומר: \u0003\"מקדש ישראל והזמנים\".\u0004","ואמר להם: \u0003ואנא אמינא טעמא דידי וטעמא דידכו\u0004 \u0005[ואני אומר את הטעם שלי ואת הטעם שלכם].\u0006 \u0003טעמא דידכו\u0004 \u0005[הטעם שלכם]\u0006 הוא: כי \u0003שבת קביעא וקיימא\u0004 \u0005[\u0006שהיא \u0005קבועה ועומדת]\u0006 ותמיד חלה ביום השביעי, לכן יש לומר \u0003בין בצלותא ובין בקידושא\u0004 \u0005[בין בתפילה ובין בקידוש]\u0006 \u0003\"מקדש השבת\",\u0004 שהרי ה' הוא מקדשה בקביעות, ואינה צריכה לקידוש על ידי בית דין. ואולם, \u0003יומא טבא\u0004 \u0005[יום טוב],\u0006 ש\u0003ישראל הוא דקבעי ליה\u0004 \u0005[שקובעים אותו],\u0006 שכן בית דין של ישראל הם \u0003דקמעברי ירחי וקבעי לשני\u0004 \u0005[שמעברים את החודשים וקובעים את השנים] —\u0006 לכן אומרים \u0003\"מקדש ישראל והזמנים\".\u0004","זהו הטעם שלכם, אבל \u0003טעמא דידי\u0004 \u0005[טעמי שלי]:\u0006 \u0003צלותא\u0004 \u0005[תפילה]\u0006 שב\u0003רבים איתא\u0004 \u0005[ישנה]\u0006 — אומרים בה: \u0003\"מקדש ישראל\",\u0004 משום כבוד ישראל המתפללים. \u0003קידוש\u0004 ש\u0003ביחיד איתא\u0004 \u0005[ישנו]\u0006 לכן \u0003בשבת\u0004 אומרים: \u0003\"מקדש השבת\",\u0004 ואילו \u0003ביום טוב\u0004 אומרים: \u0003\"מקדש ישראל והזמנים\".\u0004","את טעמו זו של רבא דוחים: \u0003ולא היא\u0004 (ואינו כן), שכן \u0003צלותא\u0004 \u0005[תפילה]\u0006 \u0003ביחיד מי ליתיה\u0004 \u0005[האם אין]?\u0006 \u0003וקידושא\u0004 \u0005[וקידוש]\u0006 \u0003ברבים מי ליתיה\u0004 \u0005[האם אין]?\u0006 ואם כן אין משמעות לחלוקה זו. \u0003ורבא סבר: זיל בתר\u0004 \u0005[לך אחר]\u0006 ה\u0003עיקר,\u0004 ובעיקר הדברים תפילה היא תפילת הרבים, והקידוש נאמר על ידי יחיד.","מסופר: \u0003עולא בר רב נחית קמיה\u0004 \u0005[ירד\u0006 לפני התיבה \u0005בפני]\u0006 \u0003רבא, אמר\u0004 את נוסח התפילה \u0003כסבי\u0004 \u0005[כזקני]\u0006 \u0003פומבדיתא, ולא אמר ליה\u0004 \u0005[לו]\u0006 רבא \u0003ולא מידי\u0004 \u0005[דבר].\u0006 \u0003אלמא: הדר ביה\u0004 \u0005[מכאן שחזר בו]\u0006 \u0003רבא\u0004 משיטתו וקיבל את דעתם. וכן מסופר: \u0003רב נתן אבוה\u0004 \u0005[אביו]\u0006 של \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נתן נחית קמיה\u0004 \u0005[ירד\u0006 לפני התיבה \u0005לפני]\u0006 \u0003רב פפא, אמר כסבי דפומבדיתא\u0004 \u0005[כזקני פומבדיתא]\u0006 ובנוסחם, \u0003ושבחיה\u0004 \u0005[ושיבחו]\u0006 \u0003רב פפא,\u0004 שעשה כדין.","\u0003אמר רבינא: אנא איקלע\u0004 \u0005[אני הזדמנתי]\u0006 \u0003לסורא קמיה\u0004 \u0005[לפני]\u0006 \u0003מרימר ונחית קמיה שלוחא דציבורא\u0004 \u0005[וירד\u0006 לפני התיבה \u0005לפניו שליח הציבור]\u0006 \u0003ואמר כ\u0004נוסח \u0003סבי דפומבדיתא\u0004 \u0005[זקני פומבדיתא],\u0006 \u0003והוו משתקי ליה כולי עלמא\u0004 \u0005[והיו משתקים אותו הכל]\u0006 שהיה נוסח זה חדש עבורם, \u0003אמר להו\u0004 \u0005[להם]\u0006 מרימר: \u0003שבקוהו\u0004 \u0005[הניחו לו]\u0006 שכן \u0003הילכתא כסבי דפומבדיתא\u0004 \u0005[הלכה כזקני פומבדיתא]\u0006 \u0003ולא הוו משתקו ליה\u0004 \u0005[היו משתקים אותו]\u0006 עוד והניחו לו לסיים בנוסח זה.","\u0003מזגו לו כוס שלישי\u0004 של יין \u0003מברך על מזונו\u0004 (ברכת המזון) על כוס זו. מזגו לו כוס \u0003רביעי גומר עליו את\u0004 ה\u0003הלל\u0004 שאת חלקו הראשון כבר אמר לפני הסעודה. \u0003ואומר עליו\u0004 בסוף ההלל \u0003את ברכת השיר. בין הכוסות הללו\u0004 שקבעו חכמים, \u0003אם רוצה לשתות\u0004 עוד — \u0003ישתה,\u0004 אולם \u0003בין\u0004 כוס \u0003שלישי לרביעי\u0004 — \u0003לא ישתה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חנן לרבא: שמע מינה\u0004 \u0005[למד ממנו]\u0006 כי \u0003ברכת המזון טעונה כוס\u0004 שהרי נאמר כאן שעם כוס שלישי מברך על מזונו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: אין מכאן ראיה, כי \u0003ארבע כסי\u0004 \u0005[כוסות]\u0006 \u0003תיקנו רבנן\u0004 \u0005[חכמים]\u0006 לשתות \u0003דרך חירות,\u0004 ואף שאכן לא נתקנו הכוסות מעיקרו לצורך זה, מכל מקום \u0003כל חד וחד נעביד ביה\u0004 \u0005[אחת ואחת\u0006 מהם ראוי שתהיה \u0005נעשית בו]\u0006 \u0003מצוה\u0004 שכיון שתיקנו חכמים ארבע כוסות אלו, הצמידו במידת האפשר לכל כוס מצוה מיוחדת. אבל ברכת המזון שבכל ימות השנה אכן אינה צריכה כוס.","במשנה שנינו כי כוס \u0003רביעי גומר עליו את ההלל ואומר עליו ברכת השיר.\u0004"],["שואלים: \u0003מאי\u0004 \u0005[מהי]\u0006 \u0003\"ברכת השיר\"\u0004 שנזכרה במשנה? \u0003רב יהודה אמר\u0004 שהיא הברכה המתחילה ב\u0003\"יהללוך ה' אלהינו\". ור' יוחנן אמר:\u0004 שאומרים אף \u0003\"נשמת כל חי\"\u0004 שהיא התפילה הנאמרת לאחר פסוקי דזמרה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: כוס \u0003רביעי גומר עליו את ההלל, ואומר הלל הגדול,\u0004 אלו \u0003דברי ר' טרפון. ויש אומרים:\u0004 אומר \u0003\"ה' רעי לא אחסר\"\u0004 (תהלים כג, א), על שם המזון שאכלו בסעודה.","ושואלים: \u0003מהיכן\u0004 מתחיל \u0003הלל הגדול\u0004 והיכן מסתיים? \u0003ר' יהודה אומר: מ\"הודו\"\u0004 (תהילים קלו, א) \u0003עד \"נהרות בבל\"\u0004 (תהילים קלז, א). \u0003ור' יוחנן אומר: מ\"שיר המעלות\"\u0004 (תהילים פרק קלד) \u0003עד \"נהרות בבל\". רב אחא בר יעקב אמר: מ\"כי יעקב בחר לו יה\"\u0004 (תהילים קלה, ד) \u0003עד \"נהרות בבל\".\u0004","שואלים: \u0003ולמה נקרא שמו\u0004 של פרק זה \u0003הלל הגדול? אמר ר' יוחנן: מפני שהקדוש ברוך הוא יושב ברומו של עולם ומחלק מזונות לכל בריה\u0004 והשבח שכל העולם כולו משבח לה' על חילוק מזונו, הוא הלל הגדול שנאמר בו \"נותן לחם לכל בשר\" (תהילים קלו, כה).","\u0003אמר ר' יהושע בן לוי: הני\u0004 \u0005[אותם]\u0006 \u0003עשרים וששה \"הודו\"\u0004 האמורים בהלל זה (תהילים פרק קלו), \u0003כנגד מי\u0004 הם — \u0003כנגד עשרים וששה דורות שברא הקדוש ברוך הוא בעולמו ולא נתן להם תורה.\u0004 כי לפי חשבון הדורות עשרה דורות הם מאדם עד נח, עשרה דורות מנח עד אברהם ועוד ששה דורות עד משה רבינו ומתן תורה (יצחק, יעקב, לוי, קהת, עמרם, משה) ודורות אלו שלא למדו תורה ולא קיימו מצוות בזכות מה חיו — משום \u0003שזן אותם\u0004 ה' \u0003בחסדו\u0004 בלבד, אף שלא היו ראויים לכך.","\u0003אמר רב חסדא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"הודו לה' כי טוב\"?\u0004 — כוונתו \u0003הודו לה' שגובה חובתו\u0004 (העונש על רשעתו וחטאתו) \u0003של אדם\u0004 על ידי \u0003טובתו\u0004 שמעניש כל אחד לפי ערכו. מ\u0003עשיר\u0004 נוטל כעונש את \u0003שורו, ואת\u0004 ה\u0003עני\u0004 מעניש בנטילת \u0003שיו,\u0004 את ה\u0003יתום\u0004 מעניש בנטילת \u0003ביצתו,\u0004 ואת ה\u0003אלמנה\u0004 מעניש בנטילת \u0003תרנגולתה —\u0004 כל אחד ואחד לפי יכולתו, ואינו מעניש אדם למעלה מיכולתו.","כיון שדובר בשבח מתן מזון לעולם מביאים מה ש \u0003אמר ר' יוחנן: קשין מזונותיו של אדם כפליים כיולדה\u0004 \u0005[יולדת],\u0006 ש\u0003אילו ביולדה כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"בעצב\u0004 תלדי בנים\u0003\"\u0004 (בראשית ג, טז) \u0003ובמזונות כתיב \"בעצבון\u0004 תאכלנה כל ימי חייך\u0003\"\u0004 (בראשית ג, יז) ולשון עצבון משמעה עצב גדול, כלומר יש יותר צער בחיפוש הפרנסה מבצער הלידה.","\u0003ואמר ר' יוחנן: קשין מזונותיו של אדם יותר מן הגאולה,\u0004 ש\u0003אילו בגאולה כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"המלאך הגאל אתי מכל רע\"\u0004 (בראשית מח, טז), שלענין הצלה מכל רע די ב\u0003מלאך בעלמא\u0004 \u0005[בלבד],\u0006 \u0003ואילו במזונות כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"האלהים הרעה אתי\u0004 מעודי עד היום הזה\u0003\"\u0004 (בראשית מח, טו), משמע שהפרנסה (\"רעיה\") אינה באה אלא מיד ה' יכול לעזור.","ועוד באותו ענין \u0003אמר ר' יהושע בן לוי: בשעה שאמר הקדוש ברוך הוא לאדם הראשון: \"וקוץ ודרדר תצמיח לך\u0004 ואכלת את עשב השדה\u0003\"\u0004 (בראשית, ג, יח) \u0003זלגו עיניו דמעות, אמר לפניו: רבונו של עולם,\u0004 אם כן \u0003אני וחמורי נאכל באבוס אחד\u0004 אותו מאכל? \u0003כיון שאמר לו: \"בזעת אפך תאכל לחם\"\u0004 (בראשית ג, יט) \u0003נתקררה דעתו,\u0004 שאם יעמול יזכה לאכילת לחם, שלא כחמורו.","\u0003אמר ר' שמעון בן לקיש: אשרינו אם עמדנו בראשונה,\u0004 כלומר, טוב היה לנו אילו היינו נשארים בגזירה הראשונה והיינו מסוגלים לאכול את עשב השדה. ועוד: \u0003ועדיין לא פלטינן מינה\u0004 \u0005[נצלנו ממנה]\u0006 מגזרה זו, \u0003דקא אכלינן עיסבי דדברא\u0004 \u0005[כשאנו אוכלין\u0006 מדי פעם \u0005את עשבי השדה],\u0006 שהרי אוכלים מיני ירקות ועלים.","\u0003אמר רב שיזבי משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' אלעזר בן עזריה: קשין מזונותיו של אדם כקריעת ים סוף, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"נתן לחם לכל בשר\u0004 כי לעולם חסדו\u0003\"\u0004 (תהלים קלו, כה) \u0003וסמיך ליה\u0004 \u0005[וסמוך לו]\u0006 הפסוק: \u0003\"לגזר ים סוף לגזרים\u0004 כי לעולם חסדו\u0003\"\u0004 (תהילים קלו, יג), משמע שכל השבחים האמורים שם שוים זה לזה בדברים מסויימים.","וכיוצא בזה \u0003אמר ר' אלעזר בן עזריה: קשין נקביו של אדם\u0004 כשנזקק להם ואינו יכול (כשאין עכול מזונו כראוי), \u0003כיום המיתה, וכקריעת ים סוף. שנאמר: \"מהר צעה להפתח\u0004 ולא ימות לשחת ולא יחסר לחמו\u0003\"\u0004 (ישעיה נא, יד), \"ו\"צועה\" משמעותו — סגור, הרי שפתיחת הנקבים היא כהצלה ממות (\"משחת\"). ועוד \u0003כתיב בתריה\u0004 \u0005[נאמר אחריו]:\u0006 \u0003\"רגע הים ויהמו גליו\"\u0004 (ישעיה נא, טו) והוא מפרש שמשוה את הדבר להשקטת (קריעת) מי ים סוף.","כיון שהובאו דברי ר' אלעזר בן עזריה שנמסרו על ידי האמוראים, מביאים עוד מדבריו \u0003ואמר רב ששת משום\u0004 (בשם) \u0003ר' אלעזר בן עזריה: כל המבזה את המועדות כאילו עובד עבודה זרה\u0004 ואף זה נלמד מסמיכות הכתובים \u0003שנאמר: \"אלהי מסכה לא תעשה לך\"\u0004 (שמות לד, יז) \u0003וכתיב בתריה\u0004 \u0005[ונאמר אחריו]:\u0006 \u0003\"את חג המצות תשמר\"\u0004 (שמות לד, יח), ללמדך שכל מי שאינו שומר את המועדים כהלכתם הרי זה כאילו עושה אלוהי מסכה.","\u0003ואמר רב ששת משום ר' אלעזר בן עזריה: כל המספר לשון הרע, וכל המקבל\u0004 (מאמין) ל\u0003לשון הרע\u0004 ששמע, \u0003וכל המעיד עדות שקר בחבירו — ראוי להשליכו לכלבים. שנאמר: \"\u0004ובשר בשדה טרפה לא תאכלו \u0003לכלב תשלכון אתו\"\u0004 (שמות כב, ל), \u0003וכתיב בתריה\u0004 \u0005[ונאמר אחריו]\u0006 בפסוק הבא: \u0003\"לא תשא שמע שוא\u0004 אל תשת ידך עם רשע להיות עד חמס\u0003\"\u0004 (שמות כג, א), הרי עדות שקר וקבלת (נשיאת) שמועת שוא, אמורה, ועוד \u0003קרי ביה\u0004 \u0005[קרא בו]\u0006 בפסוק זה גם \u0003\"לא תשיא\",\u0004 כלומר: אל תעשה ואל תספר לאחרים שמועת שוא.","שואלים: \u0003וכי מאחר דאיכא\u0004 \u0005[שיש]\u0006 \u0003הלל הגדול\u0004 שיש בו שבח כה גדול של \"נותן לחם לכל בשר\", אם כן, \u0003אנן מאי טעמא אמרינן האי\u0004 \u0005[אנו מה טעם אומרים\u0006 את ההלל \u0005הזה]\u0006 פרקי התהילים (קיג — קיח) שאומרים בכל שעת שמחה? ומשיבים: \u0003משום שיש בו\u0004 בהלל הרגיל \u0003חמשה דברים הללו:\u0004 זכר \u0003יציאת מצרים, וקריעת ים סוף, ומתן תורה, ותחית המתים, וחבלו של משיח\u0004 ומתוך כך חשיבותו.","ומסבירים: \u0003יציאת מצרים, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בצאת ישראל ממצרים\u0004 בית יעקב מעם לועז\u0003\"\u0004 (תהלים קיד, א). \u0003וקריעת ים סוף, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"הים ראה וינס\u0004 הירדן יסוב לאחור\u0003\"\u0004 (תהילים קיד, ג). \u0003מתן תורה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ההרים רקדו כאילים\"\u0004 (תהילים קיד, ד) וזהו התיאור המקובל בספרי נביאים למתן תורה, \u0003תחיית המתים, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אתהלך לפני ה'\u0004 בארצות החיים\u0003\"\u0004 (תהילים קטז, ט), הבא לאחר \"כי חילצת נפשי ממות\" ומתפרש שלאחר המוות באה התחיה בארצות החיים.","\u0003חבלו של משיח, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לא לנו ה' לא לנו\u0004 כי לשמך תן כבוד\u0003\"\u0004 (תהילים קטו, א). \u0003ואמר ר' יוחנן \"לא לנו ה' לא לנו\"\u0004 וכל הפרק כולו (\"למה יאמרו הגויים איה נא אלוהיהם\" וגו') — \u0003זו\u0004 תקופת \u0003שעבוד מלכיות\u0004 והפדות מהן. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ש\u0003אמר ר' יוחנן: \"לא לנו ה' לא לנו\" — זו מלחמת גוג ומגוג\u0004 שיבואו עלינו צרות ומלחמות רבות וננצל מהן.","\u0003רב נחמן בר יצחק אמר:\u0004 עוד טעם יש באמירת ההלל הזה שאנו אומרים, \u0003מפני שיש בו מילוט נפשות של צדיקים מגיהנם, שנאמר: \"אנה ה' מלטה נפשי\"\u0004 (תהילים קטז, ד). \u0003חזקיה אמר:\u0004 עוד טעם יש, \u0003מפני שיש בו\u0004 סיפור \u0003ירידתן של צדיקים,\u0004 חנניה מישאל ועזריה \u0003לכבשן האש ועלייתן ממנו\u0004 בנס.","\u0003ירידתן — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לא לנו ה' לא לנו\"\u0004 ודבר זה \u0003אמר חנניה, \"כי לשמך תן כבוד\" — אמר מישאל, \"על חסדך ועל אמתך\" — אמר עזריה. \"למה יאמרו הגוים\u0004 איה נא אלוהיהם \u0003\"\u0004\u0003אמרו כולן\u0004 כאחד.","וכן יש בו רמז ל\u0003עלייתן מכבשן האש, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"הללו את ה' כל גוים\u0004 שבחוהו כל האומים כי גבר עלינו חסדו ואמת ה' לעולם הללויה\u0003\"\u0004 (תהילים קיז, א— ב) ודבר זה \u0003אמר חנניה,\u0004 שיש בו סיפור שבח והודאה על הנס שנעשה להם לעיני כל הגוים. \u0003\"שבחוהו כל האמים\" — אמר מישאל, \"כי גבר עלינו חסדו\" — אמר עזריה, \"ואמת ה' לעולם הללויה\" — אמרו כולן.\u0004","\u0003ויש אומרים: \"ואמת ה' לעולם\"\u0004 המלאך \u0003גבריאל אמרו.\u0004 והמעשה כך היה: ש\u0003בשעה שהפיל נמרוד הרשע את אברהם אבינו לתוך כבשן האש אמר גבריאל לפני הקדוש ברוך הוא רבונו של עולם, ארד ואצנן\u0004 את הכבשן \u0003ואציל את הצדיק מכבשן האש. אמר לו הקדוש ברוך הוא: אני יחיד בעולמי והוא\u0004 אברהם עדיין \u0003יחיד בעולמו, נאה ליחיד להציל את היחיד\u0004 ולכן ירד ה' עצמו והצילו. \u0003ולפי שהקדוש ברוך הוא אינו מקפח שכר כל בריה\u0004 וכל מי שעשה או רצה לעשות מעשה טוב הקדוש ברוך הוא משלם שכרו, על כן \u0003אמר\u0004 לו לגבריאל: \u0003תזכה ותציל שלשה מבני בניו\u0004 באותו אופן.","\u0003דרש ר' שמעון השלוני: בשעה שהפיל נבוכדנצר הרשע את חנניה מישאל ועזריה לתוך כבשן האש עמד יורקמו שר הברד לפני הקדוש ברוך הוא, אמר לפניו: רבונו של עולם, ארד ואצנן את הכבשן ואציל לצדיקים הללו מכבשן האש. אמר לו גבריאל: אין גבורתו של הקדוש ברוך הוא בכך\u0004 כי \u0003אתה שר ברד והכל יודעין שהמים מכבין את האש\u0004 ואין זה נחשב כנס גדול כל כך \u0003אלא אני שר של אש ארד ואקרר מבפנים\u0004 את הכבשן"],["\u0003ואקדיח\u0004 (אחמם, אשרוף) \u0003מבחוץ\u0004 כדי לשרוף את הזורקים אותם לכבשן ועל ידי כך \u0003אעשה נס בתוך נס. אמר לו הקדוש ברוך הוא: רד! באותה שעה פתח גבריאל ואמר: \"ואמת ה' לעולם\"\u0004 (תהילים קיז, ב) שהרי קיים לו ה' את דבריו שהבטיח לו לפני יותר מאלף שנים.","\u0003ר' נתן אומר: \"ואמת ה' לעולם\" — דגים שבים אמרוהו,\u0004 ואותו מעשה יש להבינו \u0003כ\u0004פי שדרש \u0003רב הונא.\u0004 ש\u0003אמר רב הונא: ישראל שבאותו הדור\u0004 של יציאת מצרים \u0003מקטני אמנה היו,\u0004 וכפי ש\u0003דרש רבה בר מרי: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"וימרו על ים בים סוף\"\u0004 (תהלים קו, ז) — \u0003מלמד שהמרו ישראל\u0004 את פי משה \u0003באותה שעה, ואמרו:\u0004 שמא \u0003כשם שאנו עולין מצד אחד כך מצריים עולים מצד אחר\u0004 ואין לנו ישועה.","\u0003אמר לו הקדוש ברוך הוא לשר של ים: פלוט אותן\u0004 את מתי מצרים \u0003ליבשה! אמר לפניו: רבונו של עולם, כלום יש עבד שנותן לו רבו מתנה וחוזר ונוטל ממנו?\u0004 שהרי אותם אנשים שמתו יהיו מאכל לדגים ומתנה זו לדגים נטלת מהם? \u0003אמר לו: אתן לך אחד ומחצה שבהן\u0004 כלומר אף שאני נוטל ממך עתה אתן לך אחרים פי אחת ומחצה ממספר זה.","\u0003אמר לו: רבונו של עולם,\u0004 וכי \u0003יש עבד שתובע את רבו\u0004 על מתנה שהבטיח לו, ומי יערב לי? \u0003אמר לו: נחל קישון יהא לי ערב. מיד פלט אותן\u0004 הים \u0003ליבשה ובאו ישראל וראו אותן\u0004 שהם מתים. \u0003שנאמר: \"וירא ישראל את מצרים מת על שפת הים\"\u0004 (שמות יד, ל).","ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 וכיצד נתקיים \u0003אחד ומחצה שבהן?\u0004 ומשיבים: ש\u0003אילו בפרעה\u0004 נאמר: \u0003\"שש מאות רכב בחור\"\u0004 (שמות יד, ז) \u0003ואילו בסיסרא\u0004 נאמר: \u0003\"תשע מאות רכב ברזל\"\u0004 (שופטים ד, יג).","ומסופר: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003סיסרא\u0004 על ישראל, \u0003אתא עלייהו בדקרי דפרזלא\u0004 \u0005[בא עליהם בדקרים של ברזל],\u0006 \u0003הוציא הקדוש ברוך הוא עליהם כוכבים ממסילותם, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"מן שמים נלחמו הכוכבים\u0004 ממסילותם נלחמו עם סיסרא\u0003\"\u0004 (שופטים ה, כ) \u0003כיון דנחיתו\u0004 \u0005[שירדו]\u0006 \u0003כוכבי שמים עלייהו אקדירו הני דקרי דפרזלא\u0004 \u0005[עליהם התחממו אותם דקרי הברזל].\u0006 \u0003נחיתו לאקרורי למיסחי נפשייהו\u0004 \u0005[ירדו להתקרר, לרחוץ עצמם]\u0006 \u0003בנחל קישון,\u0004","\u0003אמר לו הקדוש ברוך הוא לנחל קישון: לך והשלם ערבונך\u0004 שערבת לשר של ים. \u0003מיד גרפם נחל קישון והשליכן לים, שנאמר: \"נחל קישון גרפם נחל קדומים\"\u0004 (שופטים ה, כא) \u0003מאי\u0004 \u0005[מה]\u0006 משמעו של \u0003\"נחל קדומים\" —\u0004 הכוונה ל\u0003נחל שנעשה ערב מקדם. באותה שעה פתחו דגים שבים ואמרו: \"ואמת ה' לעולם\"\u0004 כלומר: קיים ה' את הבטחתו שהבטיח מאז.","בהמשך לדברים שנאמרו במדרשי הכתובים שבהלל מביאים מה ש \u0003אמר ר' שמעון בן לקיש: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"מושיבי עקרת הבית\u0004 אם הבנים שמחה הללויה\u0003\"\u0004 (תהילים קיג, ט) \u0003אמרה כנסת ישראל\u0004 כלומר גדולי ישראל \u0003לפני הקדוש ברוך הוא: רבונו של עולם, שמוני\u0004 (החשיבוני) \u0003בניך\u0004 מרוב חטאיהם \u0003כחולדה זו הדרה בעיקרי בתים\u0004 שאינה חשובה, ומוצאת לה מקום בקושי בבית.","ועוד בכתובים אלה \u0003דרש רבא מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"אהבתי כי ישמע ה'\u0004 את קולי תחנוני\u0003\"\u0004 (תהילים קטז, א) \u0003אמרה כנסת ישראל: רבונו של עולם אימת אני אהובה לפניך\u0004 ויודעת שאני אהובה — \u0003בזמן שתשמע קול תחנוני. \"דלתי ולי יהושיע\"\u0004 (תהילים קטז, ו), \u0003אמרה כנסת ישראל לפני הקדוש ברוך הוא: רבונו של עולם, אף על פי שדלה אני במצות\u0004 שאיני מקיימתן כראוי מכל מקום \u0003לך אני,\u0004 ולכן \u0003לי נאה להושיע.\u0004","\u0003אמר רב כהנא: כשחלה ר' ישמעאל בר' יוסי שלח לו רבי: אמור לנו שנים ושלשה דברים שאמרת לנו משום\u0004 (משמו) של \u0003אביך.\u0004","\u0003שלח לו: כך אמר אבא, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"הללו את ה' כל גוים\u0004 שבחוהו כל האומים כי גבר עלינו חסדו ואמת ד' לעולם הללויה\u0003\"\u0004 (תהלים קיז, א-ב) ולכאורה השאלה היא \u0003אומות העולם מאי עבידתייהו\u0004 \u0005[מה מעשיהם]\u0006 לשבח בהלל זה של יציאת מצרים? אלא \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003\"הללו את ה' כל גוים\" —\u0004 על \u0003גבורות ונפלאות דעביד בהדייהו\u0004 \u0005[שעשה\u0006 ה' \u0005עמם]\u0006 שהפליא לעשות לעיניהם, \u0003כל שכן אנו\u0004 צריכים לשבח ולהודות ש\u0003גבר עלינו חסדו\u0004 ולנו נעשו הטובות.","\u0003ועוד\u0004 נאמר \u0003חדא\u0004 \u0005[אחד]\u0006 שלח לו ר' ישמעאל לרבי בשם אביו: \u0003עתידה מצרים שתביא דורון למשיח\u0004 בתוך כל האומות העתידות לבוא לפניו, כאמור \"מהיכלך על ירושלים לך יובילו מלכים שי\" (תהילים סח, ל), \u0003כסבור\u0004 הוא \u0003אינו מקבל מהם\u0004, כיון שחטאו הרבה כנגד ישראל, \u0003אמר לו הקדוש ברוך הוא למשיח: קבל מהם,\u0004 כי \u0003אכסניא עשו לבניי במצרים\u0004 שהרי התגוררו ישראל שנים רבות במצרים עוד לפני שעבודם. ומשיתקבל דורון של מצריים תרצה כוש להביא דורון, שנאמר: \u0003\"יאתיו חשמנים מני מצרים\"\u0004 (תהילים סח, לב)","\u0003נשאה כוש קל וחומר בעצמה: ומה הללו\u0004 המצריים \u0003שנשתעבדו בהן — כך\u0004 מקבלים מתנותיהם בכבוד, \u0003אני שלא נשתעבדתי בהן — לא כל שכן\u0004 שנוכל להביא דורון ויקבל מידינו. \u0003אמר לו הקדוש ברוך הוא\u0004 למשיח: \u0003קבל מהם. מיד \"כוש תריץ ידיו לאלהים\"\u0004 (תהילים סח, לב).","לאחר מכן \u0003נשאה מלכות רומי הרשעה קל וחומר בעצמה: ומה הללו שאין\u0004 הם \u0003אחיהן — כך\u0004 ומקבלים אותן יפה \u0003אנו שאנו אחיהן\u0004 בני אדום \u0003לא כל שכן? אמר לו הקדוש ברוך הוא לגבריאל: \"גער חית קנה\u0004 עדת אבירים\u0003\"\u0004 (תהילים סח, לא) — \u0003געור חיה וקנה לך עדה,\u0004 כלומר: הפרד בין אלה לאלה.","\u0003דבר אחר \"געור חית קנה\"\u0004 גער בחיה זו \u0003שדרה בין הקנים,\u0004 והיא חיה זו \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"יכרסמנה חזיר מיער וזיז שדי ירענה\"\u0004 (תהילים פ, יד) שזאת אדום שתוארה במקום אחר בהתנהגותה כחזיר.","\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: געור בחיה שכל מעשיה נכתבין בקולמוס\u0004 (בעט) \u0003אחד.\u0004 כלומר: שכל מה שיש להם לומר על אחרים הוא רק ממין אחד — דברים רעים. והמשך הפסוק: \u0003\"עדת אבירים בעגלי עמים\u0004 מתרפס ברצי כסף ביזר עמים קרבות יחפצו\u0003\"\u0004 (תהילים סח, לא) — הכוונה לאותו עם, רומי \u0003ששחטו\u0004 אנשים \u0003אבירים כעגלים שאין להם בעלים.\u0004","\u0003\"מתרפס ברצי כסף\" — שפושטין יד לקבל ממון\u0004 (מתרפס = מתיר-פס, פותח כף ידו) לקבל שוחד או מסים, אך באמת \u0003אין עושין רצון בעלים\u0004 ואפילו בזה אין לסמוך עליהם. \u0003\"פזר עמים קרבות יחפצון\" — מי גרם להם לישראל שיתפזרו לבין אומות העולם\u0004 (\"עמים\") — \u0003קריבות שהיו חפצין בהן\u0004, שרצו להיות קרובים ברוחם ובמעשיהם אל הגויים ובסופו של דבר גלו ביניהם.","\u0003ועוד שלח לו\u0004 ר' ישמעאל לרבי: \u0003שלש מאות וששים וחמשה שווקים בכרך גדול של רומי, וכל אחד ואחד היו בו שלש מאות וששים וחמשה בירניות\u0004 (מגדלים) \u0003וכל בירנית ובירנית היו בו שלש מאות וששים וחמשה מעלות\u0004 (מדרגות, קומות) \u0003וכל מעלה ומעלה היו בו\u0004 מזונות או ממון \u0003כדי לזון את כל העולם כולו.\u0004","\u0003אמר ר' ישמעאל לרבי ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר \u0003לר' ישמעאל בר' יוסי: הני\u0004 \u0005[\u0006אוצרות \u0005אלה]\u0006 \u0003למן\u0004 \u0005[למי]\u0006 כלומר: למי מיועד כל זה על פי האמת? אמר לו: \u0003לך ולחברך ולחברותך\u0004 \u0005[ולחברך ולחברתך]\u0006 כלומר לישראל וחכמיהם. \u0003שנאמר\u0004 כיוצא בו על צור: \u0003\"סחרה ואתננה קדש לה' לא יאצר ולא יחסן כי לישבים לפני ה' יהיה\u0004 סחרה לאכול לשבעה ולמכסה עתיק\u0003\"\u0004 (ישעיה כג, יח).","\u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לא יאצר\" תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף \"לא יאצר\" — זה\u0004 המוכנס בתוך \u0003בית אוצר, \"ולא יחסן\" — זה בית גניזה\u0004, שבו דברים נגנזים בתוך חומות חסונות. \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כי לישבים לפני ה'\" אמר ר' אלעזר:\u0004"],["\u0003זה המכיר מקום חבירו בישיבה\u0004 שהוא מצוי כל כך בישיבה שיודע היכן יושב כל אדם שם. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בלשון אחרת, \u0003אמר ר' אלעזר: זה המקבל פני חבירו בישיבה\u0004 ששם הוא מצוי תמיד ופוגשו שם.","\u0003מאי\u0004 \u0005[מה\u0006 משמע\u0005]\u0006 המשך הפסוק \u0003\"למכסה עתיק\" — זה המכסה\u0004 ואינו מגלה לכל \u0003דברים שכיסה עתיק יומין\u0004 (ה') \u0003ומאי נינהו\u0004 \u0005[ומה הם]\u0006 אלה \u0003סתרי תורה,\u0004 כגון מעשה בראשית, ומעשה מרכבה שראוי לכסות ולא לגלותם לכל. \u0003ואיכא דאמרי\u0004 \u0005[ויש אומרים]:\u0006 \u0003זה המגלה דברים שכיסה עתיק יומין, מאי נינהו\u0004 \u0005[מה הם]\u0006 \u0003טעמי תורה\u0004 של מצוות שונות, שאותם ראוי לגלות.","אגב הדברים שנמסרו בשם ר' ישמעאל בר' יוסי מביאים מה ש \u0003אמר רב כהנא משום ר' ישמעאל בר' יוסי: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"למנצח... מזמור לדוד\"\u0004 (תהילים ד, א. ועוד) כוונתו: \u0003זמרו\u0004 ושבחו \u0003למי שנוצחין\u0004 (מנצחים) \u0003אותו ושמח.\u0004","\u0003בא וראה שלא כמדת הקדוש ברוך הוא מדת בשר ודם. בשר ודם\u0004 כאשר \u0003מנצחין אותו\u0004 הוא \u0003עצב, אבל הקדוש ברוך הוא נוצחין אותו ושמח. שנאמר: \"ויאמר להשמידם לולי משה בחירו עמד בפרץ לפניו\u0004 להשיב חמתו מהשחית\u0003\",\u0004 הרי שמשה נקרא בחיר ה' משום שניצח את ה' ומנעו מלהשחית.","ועוד, \u0003אמר רב כהנא משום\u0004 (משמו של) \u0003ר' ישמעאל בר' יוסי אמר ר' שמעון בן לקיש משום\u0004 (משמו של) \u0003ר' יהודה נשיאה: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 בתאור חיות הקדש שבמרכבה: \u0003\"וידי אדם מתחת כנפיהם\"\u0004 (יחזקאל א, ח), שאמנם הקרי הוא \"וידי\" אבל \u0003\"ידו\" כתיב\u0004 בלשון יחיד — לדרוש מכאן: \u0003זה ידו של הקדוש ברוך הוא שפרוסה תחת כנפי החיות כדי לקבל בעלי תשובה מיד מדת הדין\u0004 שהרי לפי הדין לא היה ראוי לתת להם פתח לחזור בתשובה.","\u0003אמר רב יהודה אמר שמואל: כל כסף וזהב שבעולם יוסף לקטו והביאו למצרים, שנאמר: \"וילקט יוסף את כל הכסף הנמצא\u0004 בארץ מצרים ובארץ כנען\u0003\"\u0004 (בראשית מז, יד). \u0003אין לי אלא\u0004 שליקט כסף \u0003שבארץ מצרים ושבארץ כנען,\u0004 כסף ש\u0003בשאר ארצות מנין? תלמוד לומר: \"וכל הארץ באו מצרימה\u0004 לשבור אל יוסף כי חזק הרעב בכל הארץ\u0003\"\u0004 (בראשית מא, נז).","\u0003וכשעלו ישראל ממצרים העלוהו\u0004 את הכסף הזה \u0003עמהן, שנאמר\u0004 כשלקחו בני ישראל עמם כסף וזהב: \u0003\"וינצלו את מצרים\"\u0004 (שמות יב, לו) וכבר דרשו חכמים בביאורה של מלה זו \u0003רב אסי אמר: עשאוה\u0004 את מצרים \u0003כמצודה זו\u0004 של עופות ששמים בה תבואה לפתיון \u0003שאין בה דגן, ר' שמעון אמר: כמצולה\u0004 (עומקו של ים) \u0003שאין בה דגים.\u0004","\u0003והיה מונח\u0004 הכסף בישראל \u0003עד\u0004 זמנו של \u0003רחבעם. בא שישק מלך מצרים ונטלו מרחבעם, שנאמר: \"ויהי בשנה החמישית למלך רחבעם עלה שישק מלך מצרים על ירושלים ויקח את אצרות בית ה' ואת אוצרות בית המלך\u0004 ואת הכל לקח\u0003\"\u0004 (מלכים א' יד, כה-כו). \u0003בא זרח מלך כוש\u0004 שמלך במצרים אחר כך \u0003ונטלו משישק,\u0004","\u0003בא אסא ונטלוהו מזרח מלך כוש\u0004 שניצחו במלחמה (ראה דברי הימים ב' פי\"ד) \u0003ושיגרו\u0004 לאחר מכן \u0003להדרימון בן טברימון\u0004 מלך ארם (ראה מלכים א' פט\"ו). \u0003באו בני עמון ונטלום מהדרימון בן טברימון\u0004 כפי מסורת שהיתה בענין זה. \u0003בא יהושפט ונטלו מבני עמון\u0004 (ראה דברי הימים ב' פ\"כ) \u0003והיה מונח\u0004 בישראל \u0003עד\u0004 זמנו של \u0003אחז,\u0004","\u0003בא סנחריב ונטלו מאחז. בא חזקיהו ונטלו מסנחריב והיה מונח\u0004 בירושלים \u0003עד\u0004 זמנו של \u0003צדקיה, באו כשדיים ונטלוהו מצדקיה. באו פרסיים ונטלוהו מכשדיים. באו יוונים ונטלוהו מפרסיים. באו רומיים ונטלוהו מיד יוונים, ועדיין\u0004 הוא \u0003מונח\u0004 זהבו וכספו של עולם \u0003ברומי.\u0004","באותו ענין עצמו \u0003אמר ר' חמא בר' חנינא: שלש מטמוניות\u0004 (אוצרות) \u0003הטמין יוסף במצרים, אחת\u0004 מהן \u0003נתגלה לקרח, ואחת נתגלה לאנטונינוס בן אסוירוס\u0004 קיסר רומי \u0003ואחת גנוזה לצדיקים לעתיד לבא.\u0004","כיון שהוזכר עושרו של קרח מביאים את הכתוב \u0003\"עשר שמור לבעליו לרעתו\"\u0004 (קהלת ה, יב) \u0003אמר ר' שמעון בן לקיש: זו עשרו של קרח\u0004 שמפני עושרו נתגאה וסופו שאבד מן העולם. וראיה לכך שהיה עשיר, \u0003שנאמר: \"\u0004ואשר עשה לדתן ולאבירם בני אליאב בן ראובן אשר פצתה הארץ את פיה ותבלעם ואת בתיהם ואת אהליהם \u0003ואת כל היקום אשר ברגליהם\"\u0004 (דברים יא, ו) ו\u0003אמר ר' אלעזר: זה ממונו של אדם שמעמידו על רגליו. אמר ר' לוי: משאוי שלש מאות פרדות לבנות\u0004 שהן חזקות ומובחרות \u0003היו\u0004 רק \u0003מפתחות בית גנזיו של קרח, וכולהו אקלידי וקליפי דגלדא\u0004 \u0005[וכולם מפתחות ומנעולים של עור]\u0006 ולא האוצרות עצמם.","\u0003דיא\"ש אדי\"ש כשד\"ך מאוד\"ך סימן.\u0004 ועוד דרשו בענין ההלל שהוא כענין שיר מקהלה, שכל אחד מחלקיו נאמר עבור אדם אחר, ולכל אישיות לפי מה שמתאים לה לפי ערכה, \u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: \"אודך כי עניתני\"\u0004 (תהלים קיח, כא) — \u0003אמר דוד\u0004 להצלחת מלכותו. \u0003\"אבן מאסו הבונים היתה לראש פנה\"\u0004 (תהילים קיח, כב) — \u0003אמר ישי. \"מאת ה' היתה זאת\u0004 היא נפלאת בעינינו\u0003\"\u0004 (תהילים קיח, כג) — \u0003אמרו אחיו\u0004 של דוד. \u0003\"זה היום עשה ה'\u0004 נגילה ונשמחה בו\u0003\"\u0004 (תהילים קיח, כד) — \u0003אמר שמואל\u0004 הנביא.","\u0003\"אנא ה' הושיעה נא\"\u0004 (תהילים קיח, כה) — \u0003אמרו אחיו\u0004 של דוד. \u0003\"אנא ה' הצליחה נא\"\u0004 (תהילים קיח, כה) — \u0003אמר דוד\u0004 עצמו. \u0003\"ברוך הבא בשם ה'\"\u0004 (תהילים קיח, כו) — \u0003אמר ישי. \"ברכנוכם מבית ה'\"\u0004 (תהילים קיח, כו) — \u0003אמר שמואל. \"אל ה' ויאר לנו\"\u0004 (תהילים קיח, כז) — \u0003אמרו כולן\u0004 כאחד. \u0003\"אסרו חג בעבתים\u0004 עד קרנות המזבח\u0003\"\u0004 (תהילים קיח, כז) — \u0003אמר שמואל. \"אלי אתה ואודך\"\u0004 (תהילים קיח, כח) — \u0003אמר דוד. \"אלהי ארוממך\"\u0004 (תהילים קיח, כח) — \u0003אמרו כולן.\u0004","\u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במשנה במסכת סוכה (לח, א): \u0003מקום שנהגו\u0004"],["\u0003לכפול\u0004 פסוקים שונים בהלל — \u0003יכפול\u0004 ויאמרם פעמיים, \u0003לפשוט\u0004 כלומר שלא לכפול — \u0003יפשוט,\u0004 במקום שנהגו \u0003לברך אחריו — יברך, הכל\u0004 כפי \u0003מנהג המדינה.\u0004 בענין זה \u0003אמר אביי: לא שנו\u0004 שהדבר תלוי במנהג \u0003אלא\u0004 בברכה ש\u0003לאחריו, אבל לפניו — מצוה לברך\u0004 והכל חייבים בה. ש\u0003אמר רב יהודה אמר שמואל: כל המצות מברך עליהן עובר\u0004 (קודם) \u0003לעשייתן.\u0004","ושואלים: \u0003מאי משמע\u0004 \u0005[מה המשמעות]\u0006 ומהיכן נובע \u0003דהאי\u0004 \u0005[שזה]\u0006 \u0003\"עובר\" לישנא דאקדומי הוא\u0004 \u0005[לשון הקדמה הוא]?\u0006 \u0003אמר רב נחמן בר יצחק: דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וירץ אחימעץ דרך הככר ויעבר את הכושי\"\u0004 (שמואל ב' יח, כג) כלומר הקדים אותו. \u0003אביי אמר: מהכא\u0004 \u0005[מכאן]\u0006 יש ראיה: \u0003\"והוא עבר לפניהם\"\u0004 (בראשית לג, ג). \u0003איכא דאמרי מהכא\u0004 \u0005[יש אומרים מכאן]\u0006 הראיה: \u0003\"ויעבר מלכם לפניהם וה' בראשם\"\u0004 (מיכה ב, יג).","\u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]:\u0006 \u0003רבי כופל בה דברים\u0004 באמירת ההלל, \u0003ר' אלעזר בן פרטא מוסיף בה דברים.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 הוא \u0003מוסיף?\u0004 שודאי אין הכוונה שמוסיף מילים משלו בתוך ההלל! \u0003אמר אביי: מוסיף לכפול\u0004 דברים נוספים, \u0003מ\"אודך\"\u0004 ו\u0003למטה,\u0004 שכל הכתוב לאחר הפסוק \"אודך\" אומרים אותו פעמיים.","אגב מדרשי פסוקי ההלל מביאים מה ש \u0003דרש רב עוירא, זימנין\u0004 \u0005[פעמים]\u0006 \u0003אמר ליה\u0004 \u0005[אותו]\u0006 את הדרש הזה \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב אמי וזימנין\u0004 \u0005[ופעמים]\u0006 \u0003אמר ליה משמיה\u0004 \u0005[אותו משמו]\u0006 של \u0003רב אסי: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"ויגדל הילד ויגמל\u0004 ויעש אברהם משתה גדול ביום הגמל את יצחק\u0003\"\u0004 (בראשית כא, ח) — \u0003עתיד הקדוש ברוך הוא לעשות סעודה לצדיקים ביום שיגמל חסדו לזרעו של יצחק. לאחר שאוכלין ושותין נותנין לו לאברהם אבינו כוס של ברכה לברך,\u0004 שהוא גדול שבאבות,","\u0003ואומר להן: איני מברך\u0004 שהרי יש בי פגם, לפי \u0003שיצא ממני ישמעאל\u0004 הרשע. \u0003אומר לו\u0004 אברהם \u0003ליצחק: טול וברך. אומר להן: איני מברך לפי שיצא ממני עשו\u0004 הרשע, \u0003אומר לו ליעקב: טול וברך. אומר להם: איני מברך, שנשאתי שתי\u0004 נשים \u0003אחיות בחייהן\u0004 את רחל ולאה והרי \u0003עתידה תורה לאוסרן עלי\u0004 שאמנם לא היה הדבר אסור באותה שעה, מכל מקום לדורות נחשב הדבר לעבירה חמורה.","\u0003אומר לו למשה: טול וברך, אומר להם: איני מברך, שלא זכיתי ליכנס לארץ ישראל, לא בחיי ולא במותי. אומר לו ליהושע: טול וברך, אומר להן: איני מברך\u0004 שכן \u0003לא זכיתי לבן,\u0004 וראיה לדבר, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003יהושע בן נון\u0004 ובסדרי היוחסין נאמר ביחוס שבט אפרים: \u0003\"נון בנו יהושע בנו\"\u0004 (דברי הימים א' ז, כז) ולא הוזכרו בנים ליהושע, משמע שלא היו לו בנים.","\u0003אומר לו לדוד: טול וברך, אומר להן: אני אברך, ולי נאה לברך, שנאמר: \"כוס ישועות אשא ובשם ה' אקרא\"\u0004 (תהילים קטז, יג).","\u0003אין מפטירין אחר הפסח אפיקומן.\u0004","שואלים: \u0003מאי\u0004 \u0005[מה\u0006 משמעו\u0005]\u0006 של \u0003אפיקומן? אמר רב: שלא יעקרו מחבורה לחבורה\u0004 כלומר לאחר אכילת הפסח אין יוצאים החוצה, ואין מוציאים דברים החוצה, שהוא דורש לשון אפיקומן אפיקו מני (הוציאו דברים). ודבר זה משום גזירה שמא יבואו להוציא את הפסח למקום אחר לאחר שכבר אכלוהו במקום אחד והפסח אינו נאכל אלא במקום אחד ובחבורה אחת.","\u0003ושמואל אמר: כגון אורדילאי\u0004 \u0005[פטריות]\u0006 \u0003לי וגוזלייא\u0004 \u0005[וגוזלות]\u0006 \u0003לאבא,\u0004 לרב\u0005,\u0006 שאלה מעדנים שהיו נוהגים לאכול אחר הסעודה, ואפיקומן משמעו מיני מעדנים שאוכלים לקינוח סעודה. \u0003ורב חנינא בר שילא ור' יוחנן\u0004 אומרים: \u0003כגון תמרים, קליות ואגוזים\u0004 שאוכלים בסעודה. \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוחנן: אין מפטירין אחר הפסח, כגון תמרים קליות ואגוזים.\u0004","\u0003אמר רב יהודה אמר שמואל\u0004 דין נוסף: בזמן הזה שאין פסח — \u0003אין מפטירין אחר מצה אפיקומן.\u0004 ומקשים, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין מפטירין אחר הפסח אפיקומן\u0004 ונדייק: \u0003אחר הפסח הוא\u0004 ש\u0003לא\u0004 מפטירים, \u0003אבל לאחר מצה — מפטירין!\u0004","ודוחים: אין לדייק כך, אלא: בלשון \u0003לא מיבעיא קאמר\u0004 \u0005[נצרכה אמר],\u0006 \u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר \u0003אחר מצה\u0004 שאין אוכלים אחריה דבר — ש\u0003לא נפיש טעמייהו\u0004 \u0005[מרובה טעמה]\u0006 ואם אוכל דבר מה אחריה — מתבטל טעמה, \u0003אבל לאחר הפסח דנפיש טעמיה\u0004 \u0005[שמרובה טעמו]\u0006 \u0003ולא מצי עבוריה\u0004 \u0005[יכול להעבירו\u0006 בקלות\u0005]\u0006 — \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 איסור, \u0003קמשמע לן\u0004 \u0005[השמיע לנו]\u0006 שאפילו אחר הפסח אין מפטירים.","ומציעים: \u0003נימא מסייע ליה\u0004 \u0005[האם נאמר שאפשר לסייע לו]\u0006 מן התוספתא. ששנינו: \u0003הסופגנין\u0004 (עוגות רכות העשויות כספוג) \u0003והדובשנין\u0004 (עוגות המטוגנות בשמן ודבש) \u0003והאיסקריטין\u0004 (עוגות ממותקות בדבש), \u0003אדם ממלא כריסו מהן\u0004 בליל הפסח אם לא היו חמץ, \u0003ובלבד שיאכל כזית מצה באחרונה\u0004 ולכאורה אפשר לדייק מכאן: \u0003באחרונה — אין\u0004 \u0005[כן]\u0006 שהמצה תהא אחרונה"],["אולם \u0003בראשונה — לא,\u0004 כלומר שאין רשות לאכול מצה תחילה ואחריה דבר אחר, והרי זו ראיה לדברי רב יהודה. ודוחים: מכאן אין ראיה, בלשון \u0003לא מיבעיא קאמר\u0004 \u0005[נצרכה אמר].\u0006 \u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר שאם אוכל מצה \u0003בראשונה\u0004 שיצא בה משום \u0003דקאכיל\u0004 \u0005[ש\u0006כן \u0005הוא אוכל]\u0006 אותה \u0003לתיאבון, אבל\u0004 אם אכל \u0003באחרונה\u0004 אחר שאכל דברים אחרים \u0003דילמא אתי למיכל\u0004 \u0005[שמא יבוא לאכול]\u0006 \u0003אכילה גסה,\u0004 אכילה של אונס ובחוסר תיאבון, ואם כן \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יצא בה, \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שיכול לאכול אפילו בסוף.","\u0003מר זוטרא מתני הכי\u0004 \u0005[היה שונה\u0006 את הסוגיה הזו \u0005כך],\u0006 בלשון הבאה: \u0003אמר רב יוסף אמר רב יהודה אמר שמואל: מפטירין אחר המצה אפיקומן. נימא מסייע ליה\u0004 \u0005[האם\u0006 אפשר \u0005לסייע לו]\u0006 ממה ששנינו: \u0003אין מפטירין אחר הפסח אפיקומן,\u0004 ונדייק: \u0003אחר הפסח —\u0004 הוא ש\u0003לא, אבל אחר המצה — מפטירין,\u0004","ודוחים: בלשון \u0003לא מיבעיא קאמר\u0004 \u0005[לא נצרכה אמר].\u0006 \u0003לא מיבעיא\u0004 \u0005[לא נצרכה]\u0006 לומר שלא יאכל \u0003אחר מצה\u0004 משום ש\u0003לא נפיש טעמיה\u0004 \u0005[מרובה טעמה]\u0006 והאוכל אחריה מפיג טעם מצה לגמרי, \u0003אבל לאחר פסח אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 גזרו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאפילו אחר פסח אין מפטירים.","\u0003מיתיבי\u0004 \u0005[מקשים]:\u0006 \u0003הסופגנין והדובשנין והאיסקריטין אדם ממלא כריסו מהם ובלבד שיאכל כזית מצה באחרונה\u0004 ונדייק: \u0003באחרונה — אין\u0004 \u0005[כן]\u0006 הוא שיאכל, אבל \u0003בראשונה — לא!\u0004","ומשיבים: \u0003לא מיבעיא קאמר\u0004 כפי שאמרנו שבלשון \"לא נצרכה\" אמר, \u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר שיוצא במצה שאוכל \u0003בראשונה דקאכיל\u0004 \u0005[לפי שאוכלה]\u0006 \u0003לתיאבון אבל\u0004 אם אוכלה \u0003באחרונה דאתי למיכלה\u0004 \u0005[ש\u0006יכול \u0005לבוא לאוכלה]\u0006 \u0003אכילה גסה, אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יצא בה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שיכול לצאת אף בה.","\u0003אמר רבא:\u0004 אכילת \u0003מצה בזמן הזה\u0004 אף לאחר חורבן הבית היא \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003ומרור\u0004 חיובו רק \u0003דרבנן\u0004 \u0005[מ\u0006דברי \u0005סופרים].\u0006 ושואלים: \u0003ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 \u0003מרור?\u0004 שכן נאמר בקרבן הפסח \u0003\"על מצות ומררים\u0004 יאכלוהו\u0003\"\u0004 (במדבר ט, יא) ומכאן הוא למד: \u0003בזמן דאיכא פסח\u0004 \u0005[בזמן שיש\u0006 חובת קרבן \u0005פסח]\u0006 \u0003יש\u0004 גם חובת \u0003מרור\u0004 מן התורה, \u0003ובזמן דליכא\u0004 \u0005[שאין]\u0006 \u0003פסח ליכא\u0004 \u0005[אין]\u0006 גם חובת \u0003מרור\u0004 מן התורה.","אולם אם כן \u0003מצה נמי\u0004 \u0005[גם כן]\u0006 \u0003הא כתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"על מצות ומררים\",\u0004 הרי שאף המצה טפילה לקרבן הפסח! ודוחים: \u0003מצה מיהדר הדר ביה קרא\u0004 \u0005[חזר בו המקרא]\u0006 על חובת אכילתה בפסוק אחר, שנאמר: \u0003\"\u0004בראשון בארבעה עשר יום לחודש \u0003בערב תאכלו מצת\"\u0004 (שמות יב, יח), וקבע בזה חובה מיוחדת לאכילת מצה שאינה תלויה בקרבן. \u0003ורב אחא בר יעקב אמר: אחד זה\u0004 חובת מצה \u0003ואחד זה\u0004 חובת מרור בזמן הזה \u0003דרבנן\u0004 \u0005[\u0006מדברי \u0005סופרים],\u0006 וחיובם מן התורה רק בזמן שיש קרבן פסח.","ומקשים: \u0003אלא הכתיב\u0004 \u0005[הרי נאמר]\u0006 הפסוק הנוסף: \u0003\"בערב תאכלו מצת\"!\u0004 ומשיבים: \u0003ההיא מיבעי ליה\u0004 \u0005[אותו\u0006 כתוב \u0005צריך לו]\u0006 לא לענין מצה בזמן הזה, אלא לענין \u0003טמא\u0004 או מי \u0003שהיה בדרך רחוקה\u0004 בזמן הבית שיהא גם הוא חייב במצה, \u0003דסלקא דעתך אמינא\u0004 \u0005[שהיה עולה על דעתך לומר]\u0006 \u0003כיון דפסח לא אכלי\u0004 \u0005[אינם אוכלים]\u0006 בפסח הראשון \u0003מצה ומרור נמי\u0004 \u0005[גם כן]\u0006 \u0003לא ניכול\u0004 \u0005[יאכלו]\u0006 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שבכל זאת חייבים במצה שאינה תלויה בקרבן.","ושואלים: \u0003ורבא\u0004 הסובר שאף מצה בזמן הזה חובתה מן התורה מה אומר הוא על טענה זו? \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]:\u0006 \u0003טמא ושהיה בדרך רחוקה לא צריך קרא\u0004 \u0005[צריכים מקרא\u0006 מיוחד\u0005]\u0006 ללמד שחייבים במצה. ש\u0003לא גרעי\u0004 \u0005[גרועים\u0006 הם\u0005]\u0006 \u0003מערל ובן נכר\u0004 שחייבים בה אף על פי שאינם מקריבים ואוכלים את הפסח. \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"וכל ערל לא יאכל בו\"\u0004 (שמות יב, מח) ומדייקים: \u0003\"בו\"\u0004 כלומר בקרבן פסח \u0003אינו אוכל, אבל אוכל\u0004 הוא \u0003במצה ומרור\u0004 וכן כל שאר הדחויים מפסח,","ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 רב אחא בר יעקב, מה משיב הוא לטענה זו? ומשיבים: לדעתו \u0003כתיב בהאי וכתיב בהאי\u0004 \u0005[נאמר בזה ונאמר בזה\u0006 והם \u0005נצרכים\u0006 שניהם\u0005]\u0006 שאין ללמוד טמא מערל, ולהפך, כמבואר כבר בכמה מקומות.","ומעירים: \u0003תניא כוותיה דרבא\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו של רבא]:\u0006 \u0003\"ששת ימים תאכל מצות וביום השביעי עצרת לה' אלהיך\"\u0004 (דברים טז, ח) ונלמד מכך: \u0003מה\u0004 אכילת מצה ביום ה\u0003שביעי\u0004 אינה אלא \u0003רשות\u0004 ואין חובה ממש לאכול מצה אלא רק להמנע מן החמץ, שהרי נאמר רק \"ששת ימים תאכל מצות\", \u0003אף ששת ימים\u0004 הראשונים אינם אלא \u0003רשות.\u0004","\u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003הוי\u0004 \u0005[נעשה\u0006 לו\u0005]\u0006 היום השביעי של פסח \u0003דבר שהיה בכלל\u0004 שהרי בכלל שבעת ימי הפסח הוא, שהרי נאמר \"שבעת ימים תאכל מצות\", \u0003ויצא מן הכלל\u0004 בפסוק זה, שנאמרו בו רק ששת ימים, ואם כן לא יצא מן הכלל אלא כדי \u0003ללמד,\u0004 ובמקרה כגון זה לפי כללי מדרש ההלכה \u0003לא ללמד על עצמו\u0004 בלבד \u0003יצא, אלא ללמד על הכלל כולו יצא\u0004 שאין חובת אכילת מצה בכל שבעת ימי הפסח.","\u0003יכול אף לילה הראשון\u0004 של פסח אכילת מצה בו \u0003רשות\u0004 בלבד, \u0003תלמוד לומר: \"על מצות ומררים יאכלהו\"\u0004 (במדבר ט, יא).","ואף מכאן \u0003אין לי אלא בזמן שבית המקדש קיים\u0004 שחובה לאכול מצה, \u0003בזמן שאין בית המקדש קיים מנין\u0004 שיש חובת אכילת מצה בלילה הראשון? \u0003תלמוד לומר: \"בערב תאכלו מצת\"\u0004 הרי ש\u0003הכתוב קבעו חובה.\u0004 וכדברי רבא.","\u0003ישנו מקצתן\u0004 של הסועדים ולפיכך הפסיקו בסעודתם — \u0003יאכלו\u0004 מן הפסח אם נתעוררו אחר כך. אם ישנו \u0003כולן — לא יאכלו\u0004 עוד, שנעשה הדבר כהפסקה גמורה ונראה כאוכל פסחו בשני מקומות."],["\u0003ר' יוסי אומר נתנמנמו — יאכלו\u0004 אולם אם \u0003נרדמו\u0004 לגמרי — \u0003לא יאכלו.\u0004 ועוד אמרו: \u0003הפסח אחר חצות\u0004 הלילה \u0003מטמא את הידים\u0004 משום שהוא נעשה נותר, ונותר מטמא את הידים מדברי סופרים. וכן \u0003הפגול והנותר מטמאין את הידים\u0004 מדברי סופרים.","במשנה שנינו: \u0003ר' יוסי אומר נתנמנמו — יאכלו, נרדמו — לא יאכלו.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא\u0006 בדיוק\u0005]\u0006 \u0003נתנמנם? אמר רב אשי: נים ולא נים, תיר ולא תיר\u0004 \u0005[ישן ולא ישן, ער ולא ער]\u0006 \u0003כגון דקרי ליה, ועני\u0004 \u0005[שקוראים לו, ועונה],\u0006 \u0003ולא ידע לאהדורי סברא\u0004 \u0005[יודע להחזיר סברה],\u0006 \u0003וכי מדכרו ליה, מדכר\u0004 \u0005[וכאשר מזכירים לו\u0006 משהו שאירע, \u0005נזכר].\u0006","ובדומה להגדרה זו מסופר: \u0003אביי הוה יתיב קמיה\u0004 \u0005[היה יושב לפני]\u0006 \u0003רבה, חזא דקא נמנם\u0004 \u0005[ראה שהוא מנמנם]\u0006 לאחר שהתחיל לאכול מצת חובה באחרונה\u0005,\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מינם קא נאים מר\u0004 \u0005[האם ישן אדוני]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מינומי קא מנמנם\u0004 \u0005[מנמנם\u0006 אני\u0005],\u0006 \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003נתנמנמו — יאכלו, נרדמו — לא יאכלו.\u0004","שנינו במשנה כי \u0003הפסח אחר חצות מטמא את הידים. אלמא\u0004 \u0005[מכאן]\u0006 כי \u0003מחצות\u0004 הלילה ואילך \u0003הוה ליה\u0004 \u0005[הרי הוא]\u0006 \u0003נותר.\u0004 ושואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 שסבור כך?","\u0003אמר רב יוסף: ר' אלעזר בן עזריה הוא, דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 נאמר \u0003\"ואכלו את הבשר בלילה הזה\"\u0004 (שמות יב, ח) \u0003ר' אלעזר בן עזריה אומר: נאמר כאן\u0004 בפסוק זה \u0003\"בלילה הזה\", ונאמר להלן \"ועברתי בארץ מצרים בלילה הזה\u0004 והכיתי כל בכור בארץ מצרים\u0003\"\u0004 (שמות יב, יב),","ונלמד \"לילה\" \"לילה\" לגזירה שוה, \u0003מה להלן\u0004 במכת בכורות — \u0003עד חצות,\u0004 כאמור שמכת בכורות היתה בחצות (שמות יב, כט) \u0003אף כאן\u0004 לענין אכילת הפסח — הכוונה \u0003עד חצות\u0004 ולא אחר כך.","\u0003אמר לו ר' עקיבא: והלא נאמר\u0004 \"וככה תאכלו אותו מתניכם חגורים נעליכם ברגליכם ומקלכם בידכם ואכלתם אותו \u0003בחפזון\u0004 פסח הוא לה'\" (שמות יב, יא), כלומר: \u0003עד שעת חפזון,\u0004 וחיפזון זה, היה ביום שבו יצאו ממצרים שהוא למחרת.","\u0003אם כן מה תלמוד לומר \"בלילה\u0004 הזה\" שנאמר לענין אכילת הפסח? כדי ללמדנו הלכה זו: \u0003יכול יהא נאכל\u0004 הפסח כשאר \u0003קדשים ביום\u0004 שחיטתו כקרבן תודה וכדומה? \u0003תלמוד לומר: \"בלילה\",\u0004 כלומר, \u0003בלילה הוא נאכל, ואינו נאכל ביום.\u0004","ושואלים: \u0003ור' עקיבא האי \"הזה\"\u0004 \u0005[\"הזה\"\u0006 שנאמר בפסוק \u0005זה]\u0006 \u0003מאי עביד ליה\u0004 \u0005[מה עושה הוא בו]\u0006 מה לומד הוא ממנו? שהרי אינו לומד מכאן גזירה שוה. ומשיבים: \u0003מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 כדי \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003לילה אחר הוא דאתא\u0004 \u0005[שבא].\u0006 \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003הואיל ופסח\u0004 הוא מן ה\u0003קדשים\u0004 ה\u0003קלים,\u0004 ואף קרבן \u0003שלמים\u0004 הוא \u0003קדשים קלים. מה שלמים נאכלים לשני ימים ולילה אחד — אף פסח\u0004 יהא דינו דומה. כיצד?","\u0003אוקים\u0004 \u0005[העמד,\u0006 החלף\u0005]\u0006 \u0003לילות\u0004 לאכילת הפסח (שהרי תחילת אכילת הפסח לכל הדעות בלילה היא) \u0003במקום ימים\u0004 של אכילת השלמים \u0003ויהא\u0004 קרבן הפסח \u0003נאכל לשני לילות ויום אחד,\u0004 על כן \u0003כתב רחמנא\u0004 \u0005[המקרא]\u0006 \u0003\"הזה\",\u0004 לומר שרק בלילה זה הוא נאכל ולא באחר.","\u0003ור' אלעזר בן עזריה אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]:\u0006 דבר זה אינו צריך ללמוד מכאן, כי \u0003מ\"לא תותירו\u0004 ממנו \u0003עד בקר\u0004 והנותר ממנו עד בוקר באש תשרופו\u0003\"\u0004 (שמות יב, י) \u0003נפקא הא\u0004 \u0005[יוצא\u0006 דבר \u0005זה]\u0006 שהרי ברור שאי אפשר לאכול את הבשר בלילה הבא.","\u0003ור' עקיבא אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 כנגד טענה זו: \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא כתב רחמנא\u0004 \u0005[המקרא]\u0006 \u0003\"\u0004הלילה \u0003הזה\" הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003מאי\u0004 \u0005[מה\u0006 משמע\u0005]\u0006 \u0003\"בקר\"\u0004 שבמקרא — \u0003בקר שני,\u0004 לאחר ליל מוצאי החג (ביום ששה עשר בניסן) והוא בוקר העשוי לשריפתו. \u0003ור' אלעזר אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 כנגד טענה זו: \u0003כל היכא\u0004 \u0005[מקום]\u0006 ש\u0003כתב\u0004 המקרא \u0003\"בקר\"\u0004 — הכוונה \u0003בקר ראשון הוא.\u0004","\u0003אמר רבא: אכל מצה בזמן הזה אחר חצות,\u0004 לשיטת \u0003ר' אלעזר בן עזריה — לא יצא ידי חובתו.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שכך הוא ולשם מה היה לרבא לומר זאת? הלא \u0003כיון דאיתקש\u0004 \u0005[שהושוה\u0006 בכתוב\u0005]\u0006 מצה לקרבן ה\u0003פסח — כפסח דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006 ולפיכך אינו נאכל אלא עד חצות.","ומשיבים: יש בכל זאת חידוש בדבר, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003הא אפקיה קרא מהיקישא\u0004 \u0005[הרי הוציאו הכתוב מן ההיקש]\u0006 וכשיטת רבא עצמו שאכילת מצה היא מצוה מיוחדת בפני עצמה ונוהגת אפילו בזמן הזה ואינה קשורה לכל דבריה במצוות קרבן הפסח. \u0003קמשמע לן דכי אהדריה קרא\u0004 \u0005[השמיע לנו שכאשר החזירו הכתוב]\u0006 את מצות אכילת מצה בלילה ראשון לדון בו — \u0003למילתא קמייתא אהדריה\u0004 \u0005[לדבר הראשון החזירו]\u0006 וגם לענין זה שיאכל רק בזמן שהפסח נאכל.","שנינו במשנה כי \u0003הפיגול והנותר מטמא את הידים,\u0004 ודנו בכך \u0003רב הונא ורב חסדא. חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר:\u0004 הטעם הוא \u0003משום חשדי כהונה, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 שהטעם הוא \u0003משום עצלי כהונה.\u0004 ועוד נחלקו: \u0003חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר\u0004 שטומאת הפיגול והנותר חלה אפילו על \u0003כזית\u0004 מן הבשר, \u0003וחד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר\u0004 רק על \u0003כביצה\u0004 ממנו."],["\u0003חד תני אפיגול\u0004 \u0005[אחד מהם\u0006 היה \u0005שונה\u0006 פירושו זה \u0005לגבי פיגול]\u0006 הכתוב במשנה \u0003וחד תני אנותר\u0004 \u0005[ואחד\u0006 היה שונה פירושו \u0005על נותר].\u0006","ומבארים: \u0003מאן דתני\u0004 \u0005[מי שהיה שונה]\u0006 לענין \u0003פיגול\u0004 נתן את הטעם \u0003משום חשדי כהונה\u0004 שמא מחמת שנאה יבואו לפגל קרבנותיהם של אחרים ולכן גזרו שהעוסק בפיגול יטמא וממילא נמצא גם הוא נטמא ונפסד בכך. \u0003מאן דתני\u0004 \u0005[מי ששנה]\u0006 על \u0003נותר\u0004 נתן טעם \u0003משום עצלי כהונה\u0004 שלא יתעצלו באכילתו ולכן גזרו שיטמאו בו, כדי שיאכלוהו מהר ככל האפשר.","מה ש\u0003חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר — כזית\u0004 ו\u0003חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר — כביצה,\u0004 טעם המחלוקת היא: \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 שסובר שטומאתו ב\u0003כזית —\u0004 טעמו הוא בסברה שטומאתו של הנותר והפיגול היא כשיעור \u0003איסורו\u0004 וכיון שאיסור נותר ופיגול הוא בכזית, אף טומאתו כן. \u0003ומאן\u0004 \u0005[ומי]\u0006 ש\u0003אמר,\u0004 שסובר שטומאתו ב\u0003כביצה\u0004 — דעתו היא \u0003כטומאתו,\u0004 כלומר שכשם שטומאת שאר מיני בשר היא בכביצה, שהוא השיעור הקטן ביותר לטומאת אוכלים, אף פיגול ונותר זה שיעורם.","אם \u0003בירך ברכת הפסח\u0004 שהיא \"אשר קדשנו במצוותיו וצונו לאכול הפסח\" — \u0003פטר\u0004 על ידי כך \u0003את\u0004 הברכה \u0003של\u0004 ה\u0003זבח,\u0004 שמברכים על אכילת קרבן חגיגת הארבעה עשר \"אשר קדשנו... לאכול הזבח\", אבל אם \u0003בירך את\u0004 הברכה \u0003של זבח לא פטר את של פסח,\u0004 וצריך לברך ברכה נוספת על הפסח. אלו \u0003דברי ר' ישמעאל. ר' עקיבא אומר: לא\u0004 ברכה \u0003זו פוטרת זו ולא זו פוטרת זו\u0004 וצריך לברך על כל קרבן בפני עצמו. \u0003ב גמרא\u0004 ומסבירים את השיטות.","\u0003כשתמצא לומר\u0004 כשתמצה את הנושא ותבררנו, הרי \u0003לדברי ר' ישמעאל זריקה\u0004 של הדם על המזבח \u0003בכלל שפיכה\u0004 היא. ששפיכה היא מעשה כללי יותר. ולכן כיון שברך ברכת הפסח (שדמו בשפיכה) ממילא נכלל בכך גם ענין קרבן החגיגה שחובתו בזריקה שדין שלמים, שלדעתו הזריקה היא כפרט בתוך מצות השפיכה הכללית יותר, אבל \u0003לא שפיכה בכלל זריקה\u0004 שכשמברך על החגיגה שדמה בזריקה אינו יוצא משום ברכה על הפסח שדמו בשפיכה, לפי ששפיכה אינה בכלל זריקה.","ואילו \u0003לדברי ר' עקיבא\u0004 שתי מצוות נפרדות הן \u0003לא שפיכה בכלל זריקה ולא זריקה בכלל שפיכה,\u0004 ולכן כל אחת צריכה ברכה לעצמה."],["בדומה קצת לבעיה שעסקנו בה לגבי סדר הברכות מובאת שאלה דומה: \u0003ר' שמלאי איקלע\u0004 \u0005[הזדמן]\u0006 \u0003לפדיון הבן, בעו מיניה\u0004 \u0005[שאלו ממנו]\u0006 בדבר הברכות, ותחילה הקדימו כי \u0003פשיטא\u0004 \u0005[פשוט\u0006 לנו\u0005]\u0006 כי הברכה \u0003על פדיון הבן\u0004 שהיא: \u0003\"אשר קדשנו במצותיו וצונו על פדיון הבן\"\u0004 — ברכה זו ודאי \u0003אבי הבן מברך,\u0004 שהרי עליו המצוה לפדות את בנו. אולם הברכה השניה שמברכים \u0003\"ברוך... שהחיינו וקיימנו והגיענו לזמן הזה\",\u0004 האם \u0003כהן מברך, או אבי הבן מברך?\u0004","וצדדי השאלה: \u0003כהן מברך — דקמטי\u0004 \u0005[שמגיעה]\u0006 ה\u0003הנאה לידיה\u0004 \u0005[לידיו]\u0006 חמשת הסלעים שבפדיון הבן, וככל שאר הנהנים הריהו מברך \"שהחיינו\", \u0003או\u0004 שמא \u0003אבי הבן מברך\u0004 \"שהחיינו\" משום \u0003דקא עביד\u0004 \u0005[שהוא עושה]\u0006 \u0003מצוה\u0004 חדשה ולכך מברך עליה. \u0003לא הוה בידיה\u0004 \u0005[היתה בידו]\u0006 תשובה, \u0003אתא שאיל ביה מדרשא\u0004 \u0005[בא\u0006 ו\u0005שאל בבית המדרש].\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אבי הבן מברך שתים,\u0004 \"על פדיון הבן\" ו\"שהחינו\". ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 היא: \u0003אבי הבן מברך שתים.\u0004",""]]};
